"use client"

import { CheckCircleIcon, QueueIcon, WarningOctagonIcon, SparkleIcon } from "@phosphor-icons/react"
import React, { useMemo } from "react"
import {
    motion,
    useReducedMotion,
} from "framer-motion"
import { useTranslations } from "next-intl"
import { cn } from "@heroui/react"
import { JobCategory } from "@/modules/types/enums/job-category"
import { JobStatus } from "@/modules/types/enums/job-status"
import { WithClassNames } from "@/modules/types/base/class-name"
import { resolveAiProcessingCopy } from "@/components/utils/ai"

/** Props for {@link AIProcessingText}. */
export interface AIProcessingTextProps extends WithClassNames<{
    innerPanel?: string
    icon?: string
}> {
    jobCategory: JobCategory
    jobStatus: JobStatus
    error?: string
    showIcon?: boolean
}

const defaultIconClassName = "size-10 shrink-0"

/**
 * Theme CSS variable for border / spinner accent (aligns with status icon colors).
 */
const accentCssVarForStatus = (status: JobStatus): string => {
    switch (status) {
    case JobStatus.Queued:
    case JobStatus.Processing:
        return "var(--warning)"
    case JobStatus.Completed:
        return "var(--success)"
    case JobStatus.Failed:
        return "var(--danger)"
    default:
        return "var(--warning)"
    }
}

const useSpinningBorder = (status: JobStatus): boolean =>
    status === JobStatus.Queued 
|| status === JobStatus.Processing 
|| status === JobStatus.Completed
|| status === JobStatus.Failed

/**
 * Localized title + description for an AI job (from the `aiProcessing.*` locale namespace).
 * @param props - {@link AIProcessingTextProps}
 */
export const AIProcessingText = (props: AIProcessingTextProps) => {
    const {
        jobCategory,
        jobStatus,
        error,
        showIcon = true,
        classNames,
        className,
    } = props
    const t = useTranslations()
    const prefersReducedMotion = useReducedMotion()
    const accentVar = useMemo(
        () => accentCssVarForStatus(jobStatus),
        [
            jobStatus,
        ],
    )
    const spinningBorder = useSpinningBorder(jobStatus)
    const copy = useMemo(
        () => resolveAiProcessingCopy(
            t,
            {
                jobCategory,
                jobStatus,
                error,
            },
        ),
        [
            t,
            jobCategory,
            jobStatus,
            error,
        ],
    )
    const statusIcon = useMemo(() => {
        switch (jobStatus) {
        case JobStatus.Queued:
            return <QueueIcon className={cn(classNames?.icon, defaultIconClassName, "text-muted animate-pulse")} />
        case JobStatus.Processing:
            return <SparkleIcon className={cn(classNames?.icon, defaultIconClassName, "text-warning-soft-foreground animate-pulse")} />
        case JobStatus.Completed:
            return <CheckCircleIcon className={cn(classNames?.icon, defaultIconClassName, "text-success-soft-foreground")} />
        case JobStatus.Failed:
            return <WarningOctagonIcon className={cn(classNames?.icon, defaultIconClassName, "text-danger-soft-foreground")} />
        default:
            return null
        }
    }, [
        jobStatus,
        classNames?.icon,
    ])
    if (!copy) {
        return null
    }
    if (showIcon && !statusIcon) {
        return null
    }
    const textBlock = (
        <>
            <div className="text-sm font-medium text-foreground mb-1">{copy.title}</div>
            <div className="text-xs text-muted">{copy.description}</div>
            {jobStatus === JobStatus.Failed && copy.error && (
                <div className="mt-1 break-all text-xs text-danger-soft-foreground">{copy.error}</div>
            )}
        </>
    )
    const innerBody = !showIcon ? (
        <div className="w-full min-w-0 text-center">
            {textBlock}
        </div>
    ) : (
        <div className="flex w-full items-center gap-2">
            {statusIcon}
            <div className="w-full min-w-0">
                {textBlock}
            </div>
        </div>
    )

    if (spinningBorder) {
        return (
            <div className={cn("relative overflow-hidden rounded-2xl p-[2px]", className)}>
                <motion.div
                    className={cn(
                        "pointer-events-none absolute left-1/2 top-1/2 aspect-square h-[220%] min-h-[140%] w-[220%] min-w-[140%]",
                        "-translate-x-1/2 -translate-y-1/2",
                    )}
                    style={{
                        background: `conic-gradient(from 0deg, transparent 0deg, transparent 220deg, ${accentVar} 275deg, transparent 320deg)`,
                    }}
                    aria-hidden
                    animate={
                        prefersReducedMotion
                            ? {
                                rotate: 0,
                            }
                            : {
                                rotate: 360,
                            }
                    }
                    transition={
                        prefersReducedMotion
                            ? {
                                duration: 0,
                            }
                            : {
                                repeat: Infinity,
                                duration: 2.8,
                                ease: "linear",
                            }
                    }
                />
                <div className={cn("relative z-[1] rounded-[calc(1rem-2px)] bg-background p-3", classNames?.innerPanel)}>
                    {innerBody}
                </div>
            </div>
        )
    }
    return (
        <div
            className={
                cn(
                    "rounded-3xl border-2 border-solid bg-background p-3",
                    className,
                )
            }
            style={{
                borderColor: accentVar,
            }}
        >
            {innerBody}
        </div>
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    KeyStatusChipVariant,
} from "../enums"
import {
    AI_BALANCER_KEY_STATUS_DARK_MAP,
    AI_BALANCER_KEY_STATUS_LIGHT_MAP,
} from "../map"
import { cn } from "@heroui/react"
import { AiBalancerKeyStatus } from "@/modules/api/graphql/queries/enums/ai-balancer-key-status"

interface KeyStatusChipProps {
    /** Raw status string from GraphQL (`active` / `disabled` / `probing`). */
    status: string
    /** Translated label for the status. */
    label: string
    /** Light vs dark chip palette (defaults to dark). */
    variant?: KeyStatusChipVariant
}

/**
 * Colored status chip for one balancer API key row.
 *
 * @param props.status - Backend key lifecycle status.
 * @param props.label - Localized status label.
 * @param props.variant - Surface palette (light learn page vs dark admin).
 */
export const KeyStatusChip = ({
    status,
    label,
    variant = KeyStatusChipVariant.Dark}: KeyStatusChipProps) => {
    const visual = useMemo(
        () => {
            const map = variant === KeyStatusChipVariant.Light
                ? AI_BALANCER_KEY_STATUS_LIGHT_MAP
                : AI_BALANCER_KEY_STATUS_DARK_MAP
            return map[status]
                ?? map[AiBalancerKeyStatus.Active]
        },
        [
            status,
            variant,
        ],
    )

    const StatusIcon = visual.Icon

    return (
        <span
            className={cn("inline-flex items-center gap-2 rounded-full border px-3 py-0 text-xs font-medium", visual.chipClassName)}
        >
            <StatusIcon
                className="h-3.5 w-3.5"
            />
            {label}
        </span>
    )
}

import type { IconComponent } from "@/types"
import { CheckCircleIcon, XCircleIcon, HourglassIcon } from "@phosphor-icons/react"
import { AiBalancerKeyStatus } from "@/modules/api/graphql/queries/enums/ai-balancer-key-status"

/** Visual token for one balancer key status badge. */
export interface AiBalancerKeyStatusVisual {
    /** Tailwind classes for the status chip. */
    chipClassName: string
    /** Icon component reference. */
    Icon: IconComponent
}

/**
 * Status chip styles for dark admin surfaces.
 */
export const AI_BALANCER_KEY_STATUS_DARK_MAP: Record<string, AiBalancerKeyStatusVisual> = {
    [AiBalancerKeyStatus.Active]: {
        chipClassName: "bg-emerald-500/15 text-emerald-300 border-emerald-500/30",
        Icon: CheckCircleIcon,
    },
    [AiBalancerKeyStatus.Disabled]: {
        chipClassName: "bg-rose-500/15 text-rose-300 border-rose-500/30",
        Icon: XCircleIcon,
    },
    [AiBalancerKeyStatus.Probing]: {
        chipClassName: "bg-amber-500/15 text-amber-300 border-amber-500/30",
        Icon: HourglassIcon,
    },
}

/**
 * Status chip styles for light learn surfaces (StarCi AI page).
 */
export const AI_BALANCER_KEY_STATUS_LIGHT_MAP: Record<string, AiBalancerKeyStatusVisual> = {
    [AiBalancerKeyStatus.Active]: {
        chipClassName: "bg-emerald-100 text-emerald-800 border-emerald-200",
        Icon: CheckCircleIcon,
    },
    [AiBalancerKeyStatus.Disabled]: {
        chipClassName: "bg-rose-100 text-rose-800 border-rose-200",
        Icon: XCircleIcon,
    },
    [AiBalancerKeyStatus.Probing]: {
        chipClassName: "bg-amber-100 text-amber-800 border-amber-200",
        Icon: HourglassIcon,
    },
}

import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { EnumChip, type EnumChipEntry } from "@/components/composites/chips/EnumChip"
import { LinkBack } from "@/components/atoms/navigation/Link"
import { Typography } from "@/components/atoms/text/Typography"
import { PageHeader } from "@/components/composites/layout/Page"
import { StackH } from "@/components/frames/Stack"

/**
 * `ChallengeHeader` — the challenge-identity cluster atop the solve page: back
 * link, title, optional description, and a meta row carrying score, difficulty,
 * and the learner's pass-fail status. A `PageHeader` cluster. Two chips on
 * purpose — `difficulty` (a property of the challenge) and `status` (a property
 * of the attempt) are separate axes. Whether the status chip draws, and loading,
 * are data.
 */

/** How hard the challenge is — a property of the CHALLENGE, always known. */
export type ChallengeDifficulty = "easy" | "medium" | "hard"

/** Where the learner's own attempt stands — a property of the ATTEMPT, may not exist yet. */
export type ChallengeStatus = "completed" | "failed" | "inProgress"

/** Difficulty → chip presentation. The block owns this table (§14d.1: no caller-supplied color). */
const DIFFICULTY_MAP: Record<ChallengeDifficulty, EnumChipEntry> = {
    easy: { color: "success", label: "Easy" },
    medium: { color: "warning", label: "Medium" },
    hard: { color: "danger", label: "Hard" },
}

/**
 * Attempt status → chip presentation.
 *
 * `failed` gets a leading icon — a failed/not-passed verdict is a "universal"
 * symbol (cross), not decoration. `completed`/`inProgress` stay text-only; extend
 * the day a screen actually asks for their icon too, not preemptively.
 */
const STATUS_MAP: Record<ChallengeStatus, EnumChipEntry> = {
    completed: { color: "success", label: "Passed" },
    failed: { color: "danger", label: "Failed", icon: "cross" },
    inProgress: { color: "warning", label: "In progress" },
}

/** Props for {@link ChallengeHeader}. */
export interface ChallengeHeaderProps {
    /** Fired when the back link is pressed — the block never owns routing, only the affordance. */
    onBackPress: () => void
    /** Full back-link label override; omit to fall back to `LinkBack`'s generic "Back". */
    backLabel?: string
    /** Challenge title. */
    title: string
    /** One-sentence summary of the challenge. */
    description?: string
    /**
     * Points this challenge is worth, in RAW NUMBER — the block adds the unit
     * itself ("{n} points", §14d.1). Omit when no score is defined yet.
     */
    scoreValue?: number
    /**
     * How hard the challenge is. Always required — every challenge has a fixed
     * difficulty tier independent of whether the learner has attempted it yet.
     */
    difficulty: ChallengeDifficulty
    /**
     * The learner's own attempt outcome. Omit when the learner has not
     * attempted this challenge — the status chip is not drawn at all rather
     * than showing a "not started" chip nobody asked for.
     */
    status?: ChallengeStatus
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (§12c).
     */
    isSkeleton?: boolean
}

/**
 * The challenge identity cluster at the top of the solve page. See the file
 * header for why it is a sibling of `ContentHeader` rather than an edit of it.
 *
 * @param props - {@link ChallengeHeaderProps}
 */
const ChallengeHeader = ({
    onBackPress,
    backLabel,
    title,
    description,
    scoreValue,
    difficulty,
    status,
    isSkeleton = false,
}: ChallengeHeaderProps) => {
    // ONE row, all with the same `gap={3}`, sitting close together on the left:
    // CHIPS FIRST (status, difficulty) then the score as plain text. No
    // `prefixIcon={TrophyIcon}`, and status comes before difficulty.
    const metaRow = (
        <>
            {isSkeleton ? (
                <EnumChip
                    value="inProgress"
                    map={STATUS_MAP}
                    isSkeleton

                />
            ) : status != null ? (
                <EnumChip
                    value={status}
                    map={STATUS_MAP}

                />
            ) : null}
            {isSkeleton ? (
                <EnumChip
                    value="easy"
                    map={DIFFICULTY_MAP}
                    isSkeleton

                />
            ) : (
                <EnumChip
                    value={difficulty}
                    map={DIFFICULTY_MAP}

                />
            )}
            {isSkeleton ? (
                <Typography size="xs" color="muted" isSkeleton classNames={["w-1/4"]} />
            ) : scoreValue != null ? (
                <Typography
                    size="xs"
                    color="muted"
                    text={`${scoreValue} points`}

                />
            ) : null}
        </>
    )

    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() => (
                    <LinkBack
                        label={backLabel}
                        onPress={onBackPress}
                        isSkeleton={isSkeleton}
                    />
                )}
                title={title}
                // `PageHeader.description` is now a plain `string` (COMPOSITE-4), so this
                // block no longer wraps it in `RichText` at the call site — the field is
                // already typed/documented as a plain one-sentence summary, never markdown,
                // and `PageHeader` now owns the muted styling + skeleton swap itself.
                description={description}
                meta={({ isSkeleton }: SkeletonProps) =>
                    <StackH gap={3} align="center" principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        isSkeleton={isSkeleton} items={[() => metaRow]}  />
                }
            />
        </div>
    )
}

export { ChallengeHeader }

"use client"

import React from "react"
import { Typography, cn } from "@heroui/react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import type { SearchCourseContentItem } from "@/modules/api/graphql/queries/types/search-course-content"
import { EntityResultRow } from "@/components/blocks/learn/EntityResultRow"
import { SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"

/** Props for the {@link ChatToolResult} block. */
export interface ChatToolResultProps extends WithClassNames<undefined> {
    /** The matched sources to render as pickable rows. */
    items: Array<SearchCourseContentItem>
    /** Header label (e.g. "Flashcard", "Related lesson") — translated by the caller. */
    label: React.ReactNode
    /** Header eyebrow icon (phosphor) — signals the result kind at a glance. */
    icon?: React.ReactNode
    /** While the tool runs, mirror the list shape with skeleton rows (no spinner). */
    isLoading?: boolean
    /** Show a kind chip per row — for a MIXED-kind list; off when the header already names one kind. */
    showKindChip?: boolean
    /** Fired when a row is picked — the caller owns navigation. */
    onSelect: (item: SearchCourseContentItem) => void
    /** Optional "see all" affordance below the list (opens the full search view). */
    onViewAll?: () => void
    /** Label for the view-all footer (translated by the caller). */
    viewAllLabel?: React.ReactNode
}

/**
 * In-chat tool-result widget — a labeled, pickable list of RAG hits rendered
 * INLINE inside an assistant {@link import("@/components/blocks/feed/ChatBubble").ChatBubble}
 * (generative-UI message part). Surface-in-surface on the chat popover: a
 * border-only card (no stacked fill — [[card]] §4), a quiet header (eyebrow icon
 * + kind label + count), then shared {@link EntityResultRow}s. Loading mirrors
 * the row shape with skeletons; the caller renders a text fallback (not an empty
 * card) when nothing matched.
 */
export const ChatToolResult = ({
    items,
    label,
    icon,
    isLoading = false,
    showKindChip = false,
    onSelect,
    onViewAll,
    viewAllLabel,
    className,
}: ChatToolResultProps) => {
    return (
        <div className={cn("overflow-hidden rounded-xl border border-default bg-transparent", className)}>
            <div className="flex items-center justify-between gap-2 border-b border-default px-3 py-2">
                <span className="flex min-w-0 items-center gap-2 text-muted">
                    {icon}
                    <Typography type="body-xs" color="muted" truncate>
                        {label}
                    </Typography>
                </span>
                {!isLoading && items.length > 0 ? (
                    <Typography type="body-xs" color="muted" className="shrink-0">
                        {items.length}
                    </Typography>
                ) : null}
            </div>

            {isLoading ? (
                <>
                    {[0, 1].map((row) => (
                        <SurfaceListCardItem key={row}>
                            <div className="flex flex-col gap-2">
                                {showKindChip ? (
                                    <Skeleton.Chip />
                                ) : (
                                    <Skeleton.Typography type="body-xs" width="1/3" />
                                )}
                                <Skeleton.Typography type="body-sm" width="3/4" />
                                <Skeleton.Typography type="body-xs" width="full" />
                            </div>
                        </SurfaceListCardItem>
                    ))}
                </>
            ) : (
                <>
                    {items.map((item, index) => (
                        <EntityResultRow
                            key={`${item.kind}-${item.contentId ?? item.deckId ?? item.taskId ?? index}`}
                            item={item}
                            onSelect={onSelect}
                            showKindChip={showKindChip}
                            showSnippet
                        />
                    ))}
                    {onViewAll ? (
                        <button
                            type="button"
                            onClick={onViewAll}
                            className="group flex w-full cursor-pointer items-center gap-1 px-4 py-2 text-left text-sm font-medium text-accent-soft-foreground"
                        >
                            {viewAllLabel}
                            <ArrowRightIcon
                                aria-hidden
                                focusable="false"
                                className="size-4 transition-transform group-hover:translate-x-0.5"
                            />
                        </button>
                    ) : null}
                </>
            )}
        </div>
    )
}

"use client"

import React, { useCallback, useEffect, useMemo, useRef } from "react"
import {
    Background,
    BackgroundVariant,
    ControlButton,
    Controls,
    type Node,
    type NodeMouseHandler,
    ReactFlow,
    useEdgesState,
    useNodesState,
    useReactFlow,
} from "@xyflow/react"
import { FrameCornersIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useTheme } from "next-themes"
import { build } from "../build"
import type { MindMapThemeMode } from "../build"
import { computeMindMapProgress, resolveContentHref } from "../progress"
import { useMindMapFitView } from "../hooks"
import { COURSE_MODULE_NODE_TYPE, CourseModuleNode } from "../ModuleNode"
import type { CourseModuleSlotNodeData } from "../ModuleSlotNode"
import { CourseModuleSlotNode } from "../ModuleSlotNode"
import { COURSE_MODULE_SLOT_NODE_TYPE } from "../moduleExpansion"
import { COURSE_ROOT_NODE_TYPE, CourseRootNode } from "../RootNode"
import { MindMapFullscreenButton } from "../MindMapFullscreenButton"
import { MindMapContinueButton } from "../MindMapContinueButton"
import { MindMapBackButton } from "../MindMapBackButton"
import { MindMapLegend } from "../MindMapLegend"
import { useAppSelector } from "@/redux/hooks"
import { useQueryMyCourseOutlineSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCourseOutlineSwr"

/**
 * Inner canvas: syncs graph from Redux course + highlights active module; follows app light/dark theme.
 */
export const Canvas = () => {
    const t = useTranslations()
    const locale = useLocale()
    const { resolvedTheme } = useTheme()
    const course = useAppSelector((state) => state.course.entity)
    const courseId = useAppSelector((state) => state.course.id)
    const displayId = useAppSelector((state) => state.course.displayId)
    const activeModuleId = useAppSelector((state) => state.module.entity?.id)

    const themeMode: MindMapThemeMode = resolvedTheme === "dark" ? "dark" : "light"

    // Authenticated viewer's outline overlays progress onto the graph. Skips for guests /
    // the public standalone route (the hook returns no data when unauthenticated), so the
    // map degrades to a structure-only view.
    const { data: outline } = useQueryMyCourseOutlineSwr(courseId ?? null)
    const progress = useMemo(() => computeMindMapProgress(outline), [outline])

    /** Content-first resume target — the map is a content surface, never the capstone. */
    const resumeHref = useMemo(
        () => (outline
            ? resolveContentHref(outline.nextContentTask, outline.modules, locale, displayId)
            : null),
        [outline, locale, displayId],
    )
    /** Outline known + nothing left to do → show the "all done" note instead of Continue. */
    const allContentDone = Boolean(outline && !outline.nextContentTask)

    const graph = useMemo(
        () => build({ course, activeModuleId, themeMode, progress }),
        [course, activeModuleId, themeMode, progress],
    )

    const [nodes, setNodes, onNodesChange] = useNodesState(graph.nodes)
    const [edges, setEdges, onEdgesChange] = useEdgesState(graph.edges)

    /** Holds slot nodes computed in `setNodes` so `setEdges` can keep matching edges in the same tick. */
    const preservedSlotsRef = useRef<Array<Node>>([])
    /** Canvas container — target for the floating fullscreen button. */
    const containerRef = useRef<HTMLDivElement>(null)

    useEffect(() => {
        setNodes((prev) => {
            const keptSlots = prev.filter((node) => {
                if (node.type !== COURSE_MODULE_SLOT_NODE_TYPE) {
                    return false
                }
                const slotData = node.data as CourseModuleSlotNodeData
                return graph.nodes.some((base) => base.id === slotData.parentModuleId)
            })
            preservedSlotsRef.current = keptSlots
            return [...graph.nodes, ...keptSlots]
        })
        setEdges((prev) => {
            const mergedNodeIds = new Set([
                ...graph.nodes.map((node) => node.id),
                ...preservedSlotsRef.current.map((node) => node.id),
            ])
            const preservedExtras = prev.filter(
                (edge) =>
                    !graph.edges.some((base) => base.id === edge.id) &&
                    mergedNodeIds.has(edge.source) &&
                    mergedNodeIds.has(edge.target),
            )
            return [...graph.edges, ...preservedExtras]
        })
    }, [graph, setNodes, setEdges])

    const nodeTypes = useMemo(
        () => ({
            [COURSE_ROOT_NODE_TYPE]: CourseRootNode,
            [COURSE_MODULE_NODE_TYPE]: CourseModuleNode,
            [COURSE_MODULE_SLOT_NODE_TYPE]: CourseModuleSlotNode,
        }),
        [],
    )

    const { setCenter, fitView } = useReactFlow()

    /** Smoothly frames the clicked node: root → full overview, anything else → zoom to its center. */
    const onNodeClick = useCallback<NodeMouseHandler>(
        (_event, node) => {
            // clicking the course root pulls the camera back to the whole graph
            if (node.type === COURSE_ROOT_NODE_TYPE) {
                void fitView({
                    padding: 0.2,
                    duration: 600,
                })
                return
            }
            // otherwise animate the viewport to the node's measured center with a gentle zoom-in
            const width = node.measured?.width ?? 300
            const height = node.measured?.height ?? 100
            void setCenter(
                node.position.x + width / 2,
                node.position.y + height / 2,
                {
                    zoom: 1.4,
                    duration: 600,
                },
            )
        },
        [
            setCenter,
            fitView,
        ],
    )

    useMindMapFitView(progress.currentModuleId)

    if (!course) {
        return null
    }

    return (
        <div ref={containerRef} className="relative h-full w-full overflow-hidden bg-background/50 dark:bg-background/70">
            <ReactFlow
                aria-label={t("content.mindMapAria")}
                className="text-foreground"
                colorMode={themeMode}
                edges={edges}
                fitView
                fitViewOptions={{ padding: 0.2 }}
                maxZoom={2}
                minZoom={0.2}
                nodeTypes={nodeTypes}
                nodes={nodes}
                nodesConnectable={false}
                nodesDraggable={false}
                onEdgesChange={onEdgesChange}
                onNodeClick={onNodeClick}
                onNodesChange={onNodesChange}
                panOnScroll
                proOptions={{ hideAttribution: true }}
                zoomOnDoubleClick={false}
            >
                <Background gap={16} variant={BackgroundVariant.Dots} />
                <Controls
                    className="bg-surface shadow-sm dark:border-zinc-600 dark:bg-zinc-900/90"
                    showFitView={false}
                    showInteractive={false}
                    showZoom={false}
                >
                    <ControlButton
                        aria-label={t("mindMap.fitView")}
                        onClick={() => void fitView({ duration: 400, padding: 0.2 })}
                        title={t("mindMap.fitView")}
                    >
                        <FrameCornersIcon />
                    </ControlButton>
                </Controls>
                <MindMapBackButton />
                <MindMapFullscreenButton targetRef={containerRef} />
                <MindMapContinueButton resumeHref={resumeHref} allContentDone={allContentDone} />
                {outline ? <MindMapLegend /> : null}
            </ReactFlow>
        </div>
    )
}

