"use client"

import React, { useMemo } from "react"
import { Button } from "@heroui/react"
import { XIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { useWindowSize } from "usehooks-ts"
import { ResizableRail } from "@/components/blocks/layout/ResizableRail"
import { ContentAiChat } from "@/components/blocks/learn/ContentAiChat"
import { ContentAiScopePill } from "@/components/blocks/learn/ContentAiChat/ContentAiScopePill"
import { ContentAiChatModeSwitch } from "@/components/blocks/learn/ContentAiChat/ContentAiChatModeSwitch"
import { useContentAiChatOverlayState } from "@/hooks/zustand/overlay/hooks"

/**
 * The "rail" presentation of the content-AI chat — a RESIZABLE, full-viewport-height
 * panel docked to the window's right edge, mounted by `InnerLayout` as the RIGHT
 * half of the app split. NOT an overlay: the app column reflows beside it.
 *
 * It used to live in the learn shell's `rightRail` slot, under a full-width navbar,
 * because squeezing the whole app sideways broke a layout that keyed off the
 * VIEWPORT. That constraint is gone: the app column is a `@container` and its
 * breakpoints are `@app-*`, so it now re-lays-out against its own width and simply
 * goes compact when this rail widens. Hence the rail spans the navbar row too.
 *
 * Its own `lg:` classes stay VIEWPORT-based on purpose — whether the chat docks as
 * a rail at all is a question about the screen, not about the app column (below
 * `lg` the chat is a drawer instead).
 *
 * The drag handle is on the INNER (left) edge — drag left to widen — and the width
 * persists, capped so the app column never drops under its own `lg` breakpoint.
 * Header carries the content reference, the mode switch (jump to drawer), and a close.
 */
/** Smallest useful chat column — below this the composer + bubbles stop reading. */
const RAIL_MIN_WIDTH = 340

/**
 * Tailwind's `lg` breakpoint: the width at which the learn shell still has a
 * LEGAL desktop layout (icon rail + content-map rail + reading column).
 *
 * The rail must not squeeze the content column past this. The app is responsive
 * to the VIEWPORT, not to the column, so CSS goes on applying `lg:` rules to a
 * column that no longer has the room for them — which is exactly how a wide rail
 * left the left-hand side looking broken. Capping here keeps both sides honest
 * with no container-query refactor.
 */
const CONTENT_MIN_WIDTH = 1024

/** Never take more than half the window, however wide the screen gets. */
const MAX_WINDOW_SHARE = 0.5

/** Cap used before the window has been measured (SSR + first paint). */
const PRE_MEASURE_MAX_WIDTH = 640

/** The Content AI chat overlay rail — width-clamped panel hosting the chat UI. */
export const ContentAiChatRail = () => {
    const t = useTranslations()
    const { setOpen } = useContentAiChatOverlayState()
    // the header no longer names the lesson/course itself — `ContentAiScopePill`
    // owns that, and reads the titles straight from the store
    const { width: windowWidth } = useWindowSize()

    // Widest the reader may drag: half the window, but never wide enough to push
    // the content column under `CONTENT_MIN_WIDTH`. A 2560 screen still gets a
    // true 50/50 split (1280); 1920 settles at 896.
    //
    // Residual, accepted: under ~1364px of window even `RAIL_MIN_WIDTH` cannot
    // leave the column its full 1024, so the floor wins and the column stays
    // tight. Fixing THAT needs the column to know its own width — see proposal
    // `container-responsive-split-shell`.
    const maxWidth = useMemo(() => {
        if (!windowWidth) {
            return PRE_MEASURE_MAX_WIDTH
        }
        return Math.max(
            RAIL_MIN_WIDTH,
            Math.min(windowWidth * MAX_WINDOW_SHARE, windowWidth - CONTENT_MIN_WIDTH),
        )
    }, [windowWidth])

    return (
        <ResizableRail
            storageKey="starci.contentAiChat.railWidth"
            defaultWidth={400}
            minWidth={RAIL_MIN_WIDTH}
            maxWidth={maxWidth}
            // eslint-disable-next-line starci-fe/handler-on-prefix -- `handleSide` is a ResizableRail layout prop (which edge the resize handle sits on), a noun not an onXxx event handler
            handleSide="left"
            ariaLabel={t("contentAi.mode.rail")}
            // exports the live width as `--app-rail-w` so the app column's fixed
            // chrome (mobile bars, FABs) can sit clear of the rail instead of
            // running underneath it.
            widthVar="--app-rail-w"
            // FULL-viewport-height rail pinned to the window edge — it is a sibling of
            // the entire app column now, not of the reading content, so it spans the
            // navbar row too. `self-start` + `top-0` keep it sticky against the page's
            // one scroll container. Handle on the inner (left) edge resizes; width
            // persists. Desktop only (mobile uses the drawer).
            // NO `relative` here. `ResizableRail` deliberately leaves the root
            // unpositioned so a caller can make it `sticky`; passing `relative`
            // back in silently WINS over `lg:sticky` (same specificity, and the
            // compiled sheet puts `.relative` last), which un-sticks the rail —
            // it then scrolls away with the page and the chat looks unscrollable.
            // `sticky` is itself a positioned context, so the drag handle's
            // `absolute` still anchors correctly once the rail is visible.
            className="hidden h-dvh shrink-0 flex-col self-start overflow-hidden border-l border-default bg-surface lg:sticky lg:top-0 lg:flex"
        >
            {/* ZONE 1 — identity + actions. The scope PILL is the identity: it names
                the same thing the old title did (lesson / course) but is also the
                control that changes it, so the panel no longer says its context
                twice (title up here, pill down by the composer). */}
            <div className="flex items-center gap-2 border-b border-default px-3 py-2">
                <ContentAiScopePill className="min-w-0 flex-1" />
                <ContentAiChatModeSwitch />
                <Button
                    isIconOnly
                    size="sm"
                    variant="ghost"
                    aria-label={t("contentAi.close")}
                    onPress={() => setOpen(false)}
                >
                    <XIcon className="size-4" />
                </Button>
            </div>
            <div className="min-h-0 flex-1 overflow-hidden p-3">
                <ContentAiChat />
            </div>
        </ResizableRail>
    )
}

"use client"

import React from "react"
import { Link, Typography, cn } from "@heroui/react"
import { BookOpenIcon, CardsIcon, GlobeIcon, PuzzlePieceIcon, QuotesIcon, SparkleIcon, TargetIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { useAppSelector } from "@/redux/hooks"
import { useContentAiChatScopeStore } from "@/hooks/zustand/contentAiChatScope/store"
import { useContentAiSelection } from "@/hooks/zustand/overlay/hooks"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link ContentAiScopePill}. */
export type ContentAiScopePillProps = WithClassNames<undefined>

/**
 * What the next answer will be grounded on — the chat's IDENTITY, shown in the
 * panel header (rail + drawer) rather than above the composer.
 *
 * It sits in the header because the header used to repeat the same thing as a
 * plain title: the rail said "DevOps Mastery" up top and the pill said
 * "Whole course · DevOps Mastery" at the bottom. One surface, one identity — and
 * putting it where the title was keeps the scope SWITCH next to the name it
 * changes, instead of two screen-heights apart.
 *
 * A container by design (reads store + redux itself): the same pill renders in
 * two different hosts, and prop-drilling four values through both would drift.
 *
 * @param props - {@link ContentAiScopePillProps}
 * @see Story: .storybook/stories/features/learn/ContentAiChat/ContentAiScopePill.stories
 */
export const ContentAiScopePill = ({ className }: ContentAiScopePillProps) => {
    const t = useTranslations()
    const contentId = useAppSelector((state) => state.content.id)
    const contentTitle = useAppSelector((state) => state.content.entity?.title)
    const taskId = useAppSelector((state) => state.milestone.selectedTaskId)
    const taskTitle = useAppSelector((state) => state.milestone.selectedTaskDetail?.title)
    const challengeId = useAppSelector((state) => state.challenge.id)
    const challengeTitle = useAppSelector((state) => state.challenge.entity?.title)
    // TODO: the flashcard-quiz deck id/title are not held in redux (they live only
    // in the quiz/review route params + props), so quiz scope stays dormant here
    // until a slice/selector exposes them — matches ContentAiChat.
    const quizId: string | undefined = undefined
    const quizTitle: string | undefined = undefined
    const foundationId = useAppSelector((state) => state.foundation.foundationId)
    const foundationTitle = useAppSelector((state) => state.foundation.entity?.title)
    const courseId = useAppSelector((state) => state.course.entity?.id)
    const courseTitle = useAppSelector((state) => state.course.entity?.title)
    const { prefersCourseScope, setPrefersCourseScope } = useContentAiChatScopeStore()
    // a highlighted passage overrides every scope: the next answer is about THAT
    // excerpt (its own born-archived side-thread), so the pill says so outright
    const { selection } = useContentAiSelection()
    const isSelection = !!selection

    // mirrors the scope rule in `ContentAiChat`: a lesson grounds on itself unless
    // widened; with no lesson open the surface falls to its next grounding
    // (capstone task → challenge → quiz → foundation → whole course → `global`,
    // when there is no course at all — e.g. the chat opened from the dashboard)
    const scope = prefersCourseScope
        ? "course"
        : contentId
            ? "content"
            : taskId
                ? "task"
                : challengeId
                    ? "challenge"
                    : quizId
                        ? "quiz"
                        : foundationId
                            ? "foundation"
                            : courseId
                                ? "course"
                                : "global"
    const isCourseScope = scope === "course"
    const isGlobalScope = scope === "global"
    // a task uses a distinct 🎯 icon; a challenge its 🧩 puzzle piece and a quiz its
    // 🃏 cards (matching their retrieval-skill icons); a lesson and a foundation
    // (which reads like a single lesson) share the 📖 book
    const NonCourseIcon = scope === "task"
        ? TargetIcon
        : scope === "challenge"
            ? PuzzlePieceIcon
            : scope === "quiz"
                ? CardsIcon
                : BookOpenIcon
    // what the next answer grounds on, worded per scope
    const scopeTitle = scope === "course"
        ? t("contentAi.context.wholeCourse", { course: courseTitle ?? "" })
        : scope === "global"
            ? t("contentAi.context.global")
            : scope === "task"
                ? taskTitle
                : scope === "challenge"
                    ? challengeTitle
                    : scope === "quiz"
                        ? quizTitle
                        : scope === "foundation"
                            ? foundationTitle
                            : contentTitle

    return (
        <div
            className={cn(
                "flex min-w-0 items-center gap-2 rounded-xl border px-3 py-1.5",
                isSelection
                    ? "border-warning bg-warning-soft"
                    : isCourseScope || isGlobalScope
                        ? "border-info bg-info-soft"
                        : "border-accent bg-accent-soft",
                className,
            )}
        >
            {isSelection ? (
                <QuotesIcon aria-hidden focusable="false" className="size-4 shrink-0 text-warning-soft-foreground" />
            ) : isGlobalScope ? (
                <GlobeIcon aria-hidden focusable="false" className="size-4 shrink-0 text-info-soft-foreground" />
            ) : isCourseScope ? (
                <SparkleIcon aria-hidden focusable="false" className="size-4 shrink-0 text-info-soft-foreground" />
            ) : (
                <NonCourseIcon aria-hidden focusable="false" className="size-4 shrink-0 text-accent-soft-foreground" />
            )}
            <span className="flex min-w-0 flex-1 flex-col">
                <Typography type="body-xs" color="muted">
                    {isSelection
                        ? t("contentAi.context.selectionLabel")
                        : t("contentAi.context.label")}
                </Typography>
                <Typography type="body-sm" className="truncate" weight="medium">
                    {isSelection ? selection : scopeTitle}
                </Typography>
            </span>
            {/* the widen link is a scope switch — hidden while a passage is selected
                (the selected excerpt is its own thread; clear it to switch scope) */}
            {contentId && !isSelection ? (
                <Link
                    onPress={() => setPrefersCourseScope(!prefersCourseScope)}
                    className="shrink-0 cursor-pointer text-xs font-medium text-accent-soft-foreground"
                >
                    {isCourseScope
                        ? t("contentAi.context.backToLesson")
                        : t("contentAi.context.askWholeCourse")}
                </Link>
            ) : null}
        </div>
    )
}

