/** CTA label — a design CONSTANT, not opened to the caller (§14d.1). */
export const CTA_LABEL = "Continue"

/** Data shared by both members — ALL DATA props, no presentation props. */
export interface ContinueCardDataProps {
    /** Name of the thing in progress (course / chapter / lesson / interview session). */
    title: string
    /** Secondary line under the title — shows when there is NO `meta`/`timeLeft`. */
    subtitle?: string
    /** Current progress. `ProgressMeter` only appears when this prop is present. */
    value?: number
    /** The 100% mark. Default `100`. */
    max?: number
    /** Neutral meta fragments, joined by a dot (e.g. `["Question 7 / 8", "Middle"]`). */
    meta?: Array<string>
    /** Time left — ALWAYS renders as a chip, so the same kind of information always takes the same shape. */
    timeLeft?: string
    /** `true` → the `timeLeft` chip switches to `warning` tone. Only the TONE changes, not the element type. */
    urgent?: boolean
    /** Press handler. */
    onPress?: () => void
    /**
     * Navigation target — ONLY `.Item` can use it (its CTA is `LinkSeeMore`, a real link).
     *
     * ⚠️ `.Hero` does NOT accept it: its CTA is `Button`, and the Button atom
     * **has no `href`** (it's a button, not a link). The old version dodged this by
     * hand-rolling a `<Link>` styled to look like a button — exactly the drift being
     * cleaned up here, so it's dropped. `.Hero` navigates via `onPress` (the caller
     * does its own router-push); opening `href` for the button is work for the ATOM
     * tier, not a patch here.
     */
    href?: string
    /**
     * `true` → mirror shimmer INSTEAD of waiting for data. Applies to BOTH members
     * (`.Hero`/`.Item`) since both share `ContinueCardDataProps`.
     *
     * The flag FLOWS DOWN to the atom wherever an atom already has `isSkeleton`
     * (`Typography` for the title, `Button` for `.Hero`'s CTA, `SurfaceCard` for the card face).
     *
     * ⚠️ THREE spots in this tree have NO atom to take the flag, and the
     * scaffold/atom holding them sit OUTSIDE the 4 files touched this round (do not touch):
     *   • the meta/subtitle row goes through scaffold `ListMeta` — no `isSkeleton` yet;
     *   • `ProgressMeter` (scaffold) — no `isSkeleton` yet;
     *   • `.Item`'s CTA goes through atom `LinkSeeMore` — no `isSkeleton` yet.
     * Those three spots are TEXT/SHAPE rendered directly by CardBody/`.Item` (calling
     * the scaffold/atom straight, no layer in between), so they build their own
     * shimmer bar RIGHT HERE per the §12c rule, instead of branching off to build a
     * parallel skeleton tree for the whole `ContinueCard`.
     */
    isSkeleton?: boolean
    /** The part name of THIS card itself (§11a). */
}

/** Props for {@link ContinueCardHero}. */
export type ContinueCardHeroProps = ContinueCardDataProps

/** Props for {@link ContinueCardItem}. */
export type ContinueCardItemProps = ContinueCardDataProps

import React from "react"
import { ContinueCardHero } from "@/components/blocks/learn/ContinueCard"

/**
 * `ContinueLearning` — the "jump back to where you left off" feature. It owns
 * the domain wording (e.g. "Read 8/23 lessons"); the screen hands over only
 * numbers. There is one structure, so `isSkeleton` is a state of that leaf, not
 * a second leaf.
 */

/** Props for {@link ContinueLearning}. */
export interface ContinueLearningBaseProps {
    /** Title of the lesson in progress — raw data, the block prefixes it with "Lesson N ·" itself. */
    lessonTitle: string
    /** Lesson's order number within the course (1-based). */
    lessonIndex: number
    /** Number of lessons read / total lessons. */
    lessonsRead: number
    lessonsTotal: number
    /** Number of completed challenges / total challenges. */
    challengesDone: number
    challengesTotal: number
    /** Course progress percentage (0–100). */
    progressPercent: number
    /** Press "Continue" — the caller opens the exact lesson in progress. */
    onResume?: () => void
    /** `true` → the card switches to shimmer (the flag flows straight down to design). */
    isSkeleton?: boolean
    /** Anatomy tag for THIS block itself — lets the screen badge it as ONE node (§11a.1). */
}

/**
 * "Resume in-progress session" card — the ONE focal point of the learning page.
 *
 * Uses the design's `.Hero` variant (card face + light streak), NOT `.Item`: `.Item` is
 * one of N cards in a list, whereas this is a standalone block.
 *
 * @param props - {@link ContinueLearningBaseProps}
 */
const ContinueLearningBase = ({
    lessonTitle,
    lessonIndex,
    lessonsRead,
    lessonsTotal,
    challengesDone,
    challengesTotal,
    progressPercent,
    onResume,
    isSkeleton = false,
}: ContinueLearningBaseProps) => (
    // EVERY sentence is produced RIGHT HERE. Design doesn't know what a "lesson"/"challenge"
    // is — it only receives an already-worded `title` + `meta` (§14d.1: design receives a
    // node, never a domain concept).
    <ContinueCardHero

        title={`Lesson ${lessonIndex} · ${lessonTitle}`}
        meta={[
            `Read ${lessonsRead}/${lessonsTotal} lessons`,
            `Completed ${challengesDone}/${challengesTotal} challenges`,
        ]}
        value={progressPercent}
        max={100}
        onPress={onResume}
        isSkeleton={isSkeleton}
    />
)

/** `ContinueLearning.*` — a single-shape namespace ⇒ only `.Base` (§12a). */
export { ContinueLearningBase as ContinueLearning }

import React from "react"
import { PageHeader } from "@/components/composites/layout/Page"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { Typography } from "@/components/atoms/text/Typography"

/**
 * `CourseBrief` — the course-identity cluster atop a page. It takes crumb DATA
 * (`breadcrumbItems`) and builds the `Breadcrumbs` atom itself, so a screen
 * never holds the `PageHeader` frame or the atom directly. Meta is a muted text
 * strip joined by `·`, not a chip. The two leaves lose a node; a long trail only
 * changes the crumb count, so it is a state.
 */

/** One breadcrumb link — plain data, the block builds the atom from it. */
export interface CourseBriefCrumb {
    /** React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler → crumb is pressable; the last crumb (current page) leaves it out. */
    onPress?: () => void
}

/** Props for {@link CourseBrief}. */
export interface CourseBriefBaseProps {
    /** Breadcrumb trail as DATA — the block builds `Breadcrumbs` itself. */
    breadcrumbItems?: Array<CourseBriefCrumb>
    /** Course name. */
    title: string
    /** One-sentence course description. */
    description?: string
    /**
     * ⛔ NO pre-formatted `meta` string prop.
     * Passing `meta="8 modules · ~14h · 2,481 learners"` is **breaking the
     * structure**: the caller ends up deciding the join, units, and separator —
     * the block loses ownership of its own shape. Below are separate NUMBER
     * fields; the block joins them itself into a muted strip separated by `·`.
     */
    moduleCount?: number
    /** Total learning hours (rounded) — the block adds `~` and the "hours" word itself. */
    hours?: number
    /** Number of enrolled learners — the block formats the thousands separator itself. */
    learnerCount?: number
    /**
     * `true` → the cluster switches to a mirror shimmer INSTEAD OF waiting for
     * data — the flag FLOWS DOWN to the actual text-rendering atoms/frames
     * (`PageHeader`/`Breadcrumbs`/`Typography`), not a parallel skeleton tree
     * (§12c). `PageHeader` owns `isSkeleton` itself now (it swaps
     * `title`/`description` to shimmer internally), so this block just
     * forwards the flag straight through.
     */
    isSkeleton?: boolean
}

/**
 * Course identity cluster at the top of a page. See the file header for the
 * full contract.
 *
 * @param props - {@link CourseBriefBaseProps}
 */
const CourseBriefBase = ({
    breadcrumbItems,
    title,
    description,
    moduleCount,
    hours,
    learnerCount,
    isSkeleton = false,
}: CourseBriefBaseProps) => {
    // Meta strip joined by the BLOCK from NUMBERS — units, separators, thousands
    // grouping are all presentation; the caller doesn't touch this (§14d.1).
    const metaParts = [
        moduleCount != null ? `${moduleCount} modules` : null,
        hours != null ? `~${hours} hours` : null,
        learnerCount != null ? `${learnerCount.toLocaleString("vi-VN")} learners` : null,
    ].filter(Boolean)

    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={
                    breadcrumbItems?.length
                        ? ({ isSkeleton: skeleton }: SkeletonProps) => (
                            <div className="w-fit">
                                {/* collapse: below @app-sm or trail ≥ 4 crumbs → back-link (the old
                        capability of ResponsiveBreadcrumb, now a prop of the Breadcrumbs atom). */}
                                <Breadcrumbs
                                    collapseOnMobile
                                    collapseFrom={4}
                                    items={breadcrumbItems ?? []}
                                    isSkeleton={skeleton}
                                />
                            </div>
                        )
                        : undefined
                }
                title={title}
                description={description}
                meta={
                    metaParts.length > 0
                        ? () => (
                            <span>
                                <Typography size="xs" color="muted" text={metaParts.join(" · ")} />
                            </span>
                        )
                        : undefined
                }
            />
        </div>
    )
}

/** `CourseBrief.*` — single-component namespace ⇒ only `.Base`. */
export { CourseBriefBase as CourseBrief }

import { InputTextarea } from "@/components/atoms/forms"
import React, { useState } from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { Avatar } from "@/components/atoms/display/Avatar"
import { Button } from "@/components/atoms/buttons/Button"

import { InputButtonLike } from "@/components/composites/buttons/InputButtonLike"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * BLOCK — `CourseQaComposer`: the ONE writing shape reused three ways on a
 * course Q&A board — the root "ask the whole course" collapsible pill, an
 * answer's inline edit form, and an inline reply form. See the component file
 * header for the full mode/`initialValue`/fold-back contract and why this is
 * genuinely new rather than a duplicate of `_legacy/blocks/feed/Composer`.
 */

/** Which of the block's two writing shapes to render. */
export type CourseQaComposerMode = "collapsible" | "plain"

/** The signed-in viewer writing this — plain data, the block builds the avatar from it. */
export interface CourseQaComposerUser {
    /** Display name; also seeds the avatar's initials fallback. */
    name: string
    /** Avatar image URL. Omitted → the avatar falls back per its own chain. */
    avatarSrc?: string
}

/** Props for {@link CourseQaComposer}. */
export interface CourseQaComposerProps {
    /**
     * `"collapsible"` — boots as a slim avatar + placeholder pill, opens into the
     * full form on press (the root "ask the whole course" composer). `"plain"` —
     * always the full form (an answer's inline edit, an inline reply, or a
     * bottom "write an answer" box).
     */
    mode: CourseQaComposerMode
    /** The signed-in viewer. Omitted → no leading avatar is drawn (either shape). */
    currentUser?: CourseQaComposerUser
    /**
     * Existing content this composer opened WITH (an edit/reply reopened, not a
     * fresh draft). Read once, only to decide a `"collapsible"` composer's BOOT
     * state — see the file header. Never re-consulted after mount; the live
     * draft is entirely `value`/`onValueChange`.
     */
    initialValue?: string
    /** The current draft text — fully controlled by the caller. */
    value: string
    /** Fired with the next draft text on every keystroke. */
    onValueChange: (value: string) => void
    /** Placeholder for both the collapsed pill and the open textarea. */
    placeholder?: string
    /** Label for the submit button. Defaults to `"Send"`. */
    submitLabel?: string
    /**
     * Fired when the viewer submits. The caller already holds the draft via
     * `value`, so this fires with no argument. A `"collapsible"` composer folds
     * itself back to the pill right after — the caller is still responsible for
     * clearing `value`.
     */
    onSubmit: () => void
    /**
     * Fired when the viewer backs out. Shown whenever `mode === "collapsible"`
     * (folding back to the pill always needs a way out) or whenever the caller
     * supplies this (the edit/reply shapes of `mode === "plain"`).
     */
    onCancel?: () => void
    /** `true` → submit is in flight: the Submit button owns the busy affordance and both buttons lock. */
    isPending?: boolean
    /**
     * `true` → every composed atom mirrors itself. The flag FLOWS DOWN into the
     * real atoms (§12c) rather than a parallel skeleton tree, within whichever
     * leaf (`CollapsedPrompt`/`ExpandedForm`) is currently showing.
     */
    isSkeleton?: boolean
}

/**
 * The Q&A board's one writing shape. See the file header for the mode
 * contract, the controlled-text/`initialValue` split, and the fold-back
 * judgement call.
 *
 * @param props - {@link CourseQaComposerProps}
 */
const CourseQaComposer = ({
    mode,
    currentUser,
    initialValue,
    value,
    onValueChange,
    placeholder,
    submitLabel = "Send",
    onSubmit: onSubmitAction,
    onCancel: onCancelAction,
    isPending = false,
    isSkeleton = false,
}: CourseQaComposerProps) => {
    // Transient UI-only chrome (§ not domain data) — owned here, never lifted to
    // the caller. A "plain" composer has no collapsed shape at all, so it always
    // boots open; a "collapsible" one boots open only when reopened WITH content.
    const [expanded, setExpanded] = useState(() => mode === "plain" || Boolean(initialValue))

    const canSubmit = value.trim().length > 0 && !isPending
    const showCancel = mode === "collapsible" || onCancelAction != null

    const onSubmit = () => {
        onSubmitAction()
        // Folding back is presentational chrome the block owns; the caller still
        // clears `value` itself (it owns the draft) — see file header.
        if (mode === "collapsible") {
            setExpanded(false)
        }
    }

    const onCancel = () => {
        if (mode === "collapsible") {
            setExpanded(false)
        }
        onCancelAction?.()
    }

    const avatar = currentUser || isSkeleton ? (
        <Avatar
            name={currentUser?.name}
            src={currentUser?.avatarSrc}
            size="sm"
            isSkeleton={isSkeleton}
            classNames={["shrink-0"]}

        />
    ) : null

    // ── LEAF — CollapsedPrompt: avatar + pill, nothing else composed ──────────
    if (mode === "collapsible" && !expanded) {
        return (
            <div>
                <StackH
                    gap={3}
                    isSkeleton={isSkeleton}
                    items={[
                        () => avatar,
                        () => (
                            <div className="min-w-0 flex-1">
                                <InputButtonLike
                                    placeholder={placeholder ?? "Ask a question about this course…"}
                                    onPress={() => setExpanded(true)}
                                    isSkeleton={isSkeleton}
                                />
                            </div>
                        ),
                    ]}
                />
            </div>
        )
    }

    // ── LEAF — ExpandedForm: avatar + textarea + action row ───────────────────
    const actionRow = (
        <>
            {showCancel ? (
                <Button
                    label="Cancel"
                    variant="tertiary"
                    size="sm"
                    onPress={onCancel}
                    isDisabled={isPending}
                    isSkeleton={isSkeleton}

                />
            ) : null}
            <Button
                label={submitLabel}
                variant="primary"
                size="sm"
                onPress={onSubmit}
                isDisabled={!canSubmit}
                isPending={isPending}
                isSkeleton={isSkeleton}

            />
        </>
    )

    const form = (
        <>
            <InputTextarea
                value={value}
                onValueChange={onValueChange}
                placeholder={placeholder}
                ariaLabel={placeholder ?? "Content"}
                rows={3}
                isDisabled={isPending}
                isSkeleton={isSkeleton}

            />
            <StackH gap={3} principle="flex-action"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                justify="end" isSkeleton={isSkeleton} items={[() => actionRow]}  />
        </>
    )

    return (
        <div>
            <StackH
                gap={3}
                isSkeleton={isSkeleton}
                items={[
                    () => avatar,
                    ({ isSkeleton }: SkeletonProps) => <StackV gap={3} isSkeleton={isSkeleton} classNames={["min-w-0", "flex-1"]} items={[() => form]} />,
                ]}
            />
        </div>
    )
}

export { CourseQaComposer }

