"use client"

import React from "react"
import type { ReactNode } from "react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import type { ResponsiveBreadcrumbItem } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { pathConfig } from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"

/** Props for {@link LearnBreadcrumb}. */
export interface LearnBreadcrumbProps {
    /**
     * The final (current page) crumb — read-only, no navigation. OMIT on the course-learn home
     * (then `<course>` itself is the last read-only crumb instead of a link).
     */
    current?: ReactNode
    /**
     * Optional intermediate clickable crumb inserted between `<course>` and `current` — for a
     * sub-view of a learn tab (e.g. a flashcard deck under "Review": the section crumb links back
     * to the tab's overview, `current` is the deck name). Only used when `current` is set.
     */
    section?: {
        /** Section label (e.g. "Review"). */
        label: ReactNode
        /** Navigate back to the section overview. */
        onPress: () => void
    }
}

/**
 * Shared page breadcrumb for the course-learn tabs: Home › Courses › <course> › [section ›] {current}.
 *
 * Self-contained (reads the active course from Redux + owns its routing), so any learn page can
 * drop it in — render it INSIDE the page's reading column / `PageHeader` `breadcrumb` slot so it
 * shares that column's padding + cap (no separate padded wrapper). Only the last crumb (+ optional
 * section) varies.
 *
 * @param props - {@link LearnBreadcrumbProps}
 */
export const LearnBreadcrumb = ({ current, section }: LearnBreadcrumbProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const course = useAppSelector((state) => state.course.entity)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)

    const items: Array<ResponsiveBreadcrumbItem> = [
        {
            key: "home",
            label: t("nav.home"),
            onPress: () => router.push(pathConfig().locale().build()),
        },
        {
            key: "courses",
            label: t("nav.courses"),
            onPress: () => router.push(pathConfig().locale(locale).course().build()),
        },
        {
            key: "course",
            label: course?.title || t("nav.courses"),
            // clickable only when it's NOT the current (last read-only) crumb
            onPress: current != null
                ? () => router.push(pathConfig().locale(locale).course(courseDisplayId).build())
                : undefined,
        },
        ...(current != null && section
            ? [{ key: "section", label: section.label, onPress: section.onPress }]
            : []),
        ...(current != null ? [{ key: "current", label: current }] : []),
    ]

    return <ResponsiveBreadcrumb items={items} />
}

export default LearnBreadcrumb

"use client"

import {
    ListBulletsIcon,
    ListIcon,
} from "@phosphor-icons/react"
import React, { useEffect, useState } from "react"
import { Button, Drawer, ScrollShadow } from "@heroui/react"
import { useTranslations } from "next-intl"
import { useRouter, useSelectedLayoutSegments } from "next/navigation"
import { ContentMap } from "@/components/blocks/learn/ContentMap"
import {
    useSidebarNavItems,
} from "@/hooks/useSidebarNavItems"
import { SidebarNavItem } from "@/components/blocks/navigation/SidebarNavItem"
import { SidebarNavAccordionGroup } from "@/components/blocks/navigation/SidebarNavAccordionGroup"

/** Props for {@link LearnMobileBar}. */
export type LearnMobileBarProps = Record<string, never>
/**
 * Mobile toolbar for the course-learn pages (hidden from `lg` up).
 *
 * Container: surfaces the two sidebars that are hidden on small screens as
 * slide-in drawers — the course nav (left) and the module outline (right). The
 * nav rows reuse the {@link SidebarNavItem} block (always expanded here) and
 * self-route via the shared select handler. Each drawer is controlled by local
 * open state. `"use client"` for the interactive triggers + shared nav hook.
 * @param props - {@link LearnMobileBarProps}
 */
export const LearnMobileBar = () => {
    const t = useTranslations()
    const router = useRouter()
    // shared course-nav entries (same list the desktop sidebar renders)
    const { items, selectedTab, onSelect } = useSidebarNavItems()
    // the module-outline (ContentMap) drawer only makes sense on the content reader
    // routes; on other surfaces (flashcards / leaderboard / foundations…) it would
    // open the wrong tree, so the outline trigger + drawer are hidden there.
    const segments = useSelectedLayoutSegments()
    const isContentRoute = segments.includes("modules") || segments[0] === "content"
    // open state for the left (course menu) drawer
    const [isMenuOpen, setMenuOpen] = useState(false)
    // open state for the right (module outline) drawer
    const [isOutlineOpen, setOutlineOpen] = useState(false)

    // rows self-dispatch their tab + navigation; collapse the drawer whenever the
    // active tab changes so the user lands back on the content
    useEffect(() => {
        setMenuOpen(false)
    }, [selectedTab])

    return (
        // fixed FOOTER bar (mirrors LearnMobileTabBar's own bottom placement — every
        // learn page's mobile chrome lives in the SAME footer zone, whether it renders
        // this simple drawer trigger or the reader's full tab bar); mobile/tablet only
        <div className={"fixed bottom-0 left-0 right-[var(--app-rail-w,0px)] z-40 flex h-16 items-center gap-3 border-t bg-background/90 px-3 backdrop-blur-xl @app-lg:hidden"}>
            {/* trigger: open the course navigation drawer */}
            <Button variant="ghost" size="sm" onPress={() => setMenuOpen(true)}>
                <ListIcon className="size-5" />
                {t("nav.courseMenu")}
            </Button>
            {/* trigger: open the module outline drawer — content reader routes only */}
            {isContentRoute ? (
                <Button variant="ghost" size="sm" onPress={() => setOutlineOpen(true)}>
                    <ListBulletsIcon className="size-5" />
                    {t("nav.contentOutline")}
                </Button>
            ) : null}

            {/* left drawer — course-learn navigation list */}
            <Drawer>
                <Drawer.Backdrop isOpen={isMenuOpen} onOpenChange={setMenuOpen}>
                    <Drawer.Content placement="left">
                        <Drawer.Dialog className="p-0">
                            <div className="p-3">
                                <Drawer.CloseTrigger />
                                <Drawer.Header>
                                    <Drawer.Heading>{t("nav.courseMenu")}</Drawer.Heading>
                                </Drawer.Header>
                            </div>
                            <div className="border-b" />
                            <Drawer.Body className="p-3">
                                <div className="flex flex-col gap-3">
                                    {items.map((item) => (
                                        item.children ? (
                                            <SidebarNavAccordionGroup
                                                key={item.value}
                                                icon={item.icon}
                                                label={item.label}
                                                items={item.children.map((child) => ({
                                                    value: child.value,
                                                    label: child.label,
                                                    isActive: child.isActive,
                                                    onPress: () => {
                                                        setMenuOpen(false)
                                                        router.push(child.url)
                                                    },
                                                }))}
                                            />
                                        ) : (
                                            <SidebarNavItem
                                                key={item.value}
                                                icon={<item.icon className="size-5 shrink-0" />}
                                                label={item.label}
                                                isActive={selectedTab === item.tab}
                                                onPress={() => onSelect(item)}
                                            />
                                        )
                                    ))}
                                </div>
                            </Drawer.Body>
                        </Drawer.Dialog>
                    </Drawer.Content>
                </Drawer.Backdrop>
            </Drawer>

            {/* right drawer — module + content outline (content reader routes only) */}
            {isContentRoute ? (
                <Drawer>
                    <Drawer.Backdrop isOpen={isOutlineOpen} onOpenChange={setOutlineOpen}>
                        <Drawer.Content placement="right">
                            <Drawer.Dialog className="p-0">
                                <div className="p-3">
                                    <Drawer.CloseTrigger />
                                    <Drawer.Header>
                                        <Drawer.Heading>{t("nav.contentOutline")}</Drawer.Heading>
                                    </Drawer.Header>
                                </div>
                                <div className="border-b" />
                                <Drawer.Body className="p-0">
                                    <ScrollShadow hideScrollBar className="h-full overflow-y-auto">
                                        <ContentMap />
                                    </ScrollShadow>
                                </Drawer.Body>
                            </Drawer.Dialog>
                        </Drawer.Content>
                    </Drawer.Backdrop>
                </Drawer>
            ) : null}
        </div>
    )
}

"use client"

import {
    BookOpenIcon,
    ListIcon,
    ListBulletsIcon,
} from "@phosphor-icons/react"
import React, { useEffect } from "react"
import { cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { ContentMap } from "@/components/blocks/learn/ContentMap"
import { OnThisPage } from "@/components/blocks/learn/OnThisPage"
import { useTableOfContents } from "@/components/blocks/learn/OnThisPage/hooks/useTableOfContents"
import { useSidebarNavItems } from "@/hooks/useSidebarNavItems"
import { SidebarNavItem } from "@/components/blocks/navigation/SidebarNavItem"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { setMobileView, type MobileLearnView } from "@/redux/slices/sidebar"

/**
 * Mobile bottom-tab bar for the lesson reader (hidden from `lg` up).
 *
 * The desktop 4-column layout (course-nav · content-map · content · on-this-page)
 * has no room on phones, so this collapses it into an app-style bottom-tab: one
 * full-screen view at a time, thumb-reachable. Three tabs —
 *  - **Contents**: course-nav rows ({@link SidebarNavItem}) + the {@link ContentMap}
 *    lesson list (both are "navigation");
 *  - **Lesson**: the content itself (the reader is rendered by the shell — this
 *    tab just closes the overlays);
 *  - **On this page**: the {@link OnThisPage} outline (self-hides → tab omitted when
 *    the lesson has no headings).
 *
 * Selecting a new lesson lands the reader back on the content view. State lives in
 * the `sidebar` slice (`mobileView`) so the shell can mount the matching view.
 */
export const LearnMobileTabBar = () => {
    const t = useTranslations()
    const dispatch = useAppDispatch()
    const view = useAppSelector((state) => state.sidebar.mobileView)
    const contentId = useAppSelector((state) => state.content.id)
    const { items, selectedTab, onSelect } = useSidebarNavItems()
    // mirror OnThisPage's self-hide: no headings → no "on this page" tab
    const { headings } = useTableOfContents(contentId)
    const hasToc = headings.length > 0

    // opening a new lesson (from the map) lands the reader back on the content
    useEffect(() => {
        dispatch(setMobileView("content"))
    }, [contentId, dispatch])

    // never strand the user on an "On this page" tab that just vanished
    useEffect(() => {
        if (view === "toc" && !hasToc) {
            dispatch(setMobileView("content"))
        }
    }, [view, hasToc, dispatch])

    const tabs: Array<{ key: MobileLearnView; icon: typeof ListIcon; label: string }> = [
        { key: "map", icon: ListIcon, label: t("learnTabs.contents") },
        { key: "content", icon: BookOpenIcon, label: t("learnTabs.lesson") },
        ...(hasToc
            ? [{ key: "toc" as const, icon: ListBulletsIcon, label: t("learnTabs.onThisPage") }]
            : []),
    ]

    return (
        <>
            {/* full-screen "Contents" overlay — course-nav + the lesson list */}
            {view === "map" && (
                <div className="fixed top-16 bottom-16 left-0 right-[var(--app-rail-w,0px)] z-30 overflow-y-auto bg-background @app-lg:hidden">
                    <div className="flex flex-col gap-3 p-6">
                        {items.map((item) => (
                            <SidebarNavItem
                                key={item.value}
                                icon={<item.icon className="size-5 shrink-0" />}
                                label={item.label}
                                isActive={selectedTab === item.tab}
                                onPress={() => onSelect(item)}
                            />
                        ))}
                    </div>
                    <div className="border-t" />
                    <ContentMap />
                </div>
            )}

            {/* full-screen "On this page" overlay — the lesson outline + actions */}
            {view === "toc" && hasToc && (
                <div className="fixed top-16 bottom-16 left-0 right-[var(--app-rail-w,0px)] z-30 overflow-y-auto bg-background @app-lg:hidden">
                    <OnThisPage mobile />
                </div>
            )}

            {/* the bottom-tab bar itself */}
            <nav
                role="tablist"
                aria-label={t("learnTabs.contents")}
                className="fixed bottom-0 left-0 right-[var(--app-rail-w,0px)] z-40 flex h-16 border-t bg-background/90 backdrop-blur-xl @app-lg:hidden"
            >
                {tabs.map((tab) => {
                    const isActive = view === tab.key
                    return (
                        <button
                            key={tab.key}
                            type="button"
                            role="tab"
                            aria-selected={isActive}
                            onClick={() => dispatch(setMobileView(tab.key))}
                            className={cn(
                                "flex flex-1 flex-col items-center justify-center gap-2 outline-none",
                                "focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-inset",
                                isActive ? "text-accent-soft-foreground" : "text-muted",
                            )}
                        >
                            <tab.icon className="size-5" />
                            <span className="text-xs">{tab.label}</span>
                        </button>
                    )
                })}
            </nav>
        </>
    )
}

export default LearnMobileTabBar

import React from "react"
import { ArrowRightIcon, CardsIcon, MicrophoneStageIcon, TrophyIcon, type Icon } from "@phosphor-icons/react"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Typography } from "@/components/atoms/text/Typography"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"

/** Which contextual nudge a row is — the block picks the icon from this, the caller never passes a node. */
export type LearnNudgeKind = "due" | "interview" | "rank"

/** kind → leading icon (the block owns the glyph; the connected file passes only `kind`). */
const KIND_ICON: Record<LearnNudgeKind, Icon> = {
    due: CardsIcon,
    interview: MicrophoneStageIcon,
    rank: TrophyIcon,
}

/** One resolved nudge row — `kind` + already-localized `label` + its route handler. */
export interface LearnNudgeItem {
    /** Stable key. */
    key: string
    /** Which nudge — decides the leading icon. */
    kind: LearnNudgeKind
    /** Already-localized row label. */
    label: string
    /** Open the nudge's route. */
    onPress?: () => void
}

/** Props for {@link _LearnNudges} — presentational; all data resolved, no fetch/store/i18n. */
export interface LearnNudgesProps {
    /** The nudges to show, already resolved + ranked. Empty (and not shimmering) → the strip renders nothing. */
    items: Array<LearnNudgeItem>
    /**
     * `true` → a 2-row shimmer instead of self-hiding. The universal shimmer prop
     * (§ every presentational leaf speaks `isSkeleton`); the connected file decides
     * WHEN — here it forwards its own "counts still loading" flag as `isSkeleton`.
     */
    isSkeleton?: boolean
    /** Where this strip sits inside its parent. */
    classNames?: Array<AllowedClassName>
}

/**
 * Contextual "next actions" strip on the content home — the aids that orbit the course spine
 * (due flashcards, mock-interview, rank), surfaced with their REAL state so they read as timely
 * nudges, not a static link grid. Each nudge self-hides when absent from `items`; the whole strip
 * renders nothing when `items` is empty. While `isSkeleton` it shimmers the SAME `SurfaceCardList`
 * (one render path, row content swapped for bars) rather than flashing empty.
 * See `design/storybook/architecture/split.md` — the connected {@link import("./index").LearnNudges}
 * owns the fetch and i18n.
 *
 * @param props - {@link LearnNudgesProps}
 */
export const _LearnNudges = ({ items, isSkeleton = false, classNames }: LearnNudgesProps) => {
    // No timely nudge and not shimmering → render nothing (no empty card).
    if (!isSkeleton && items.length === 0) {
        return null
    }
    // ONE render path: still `SurfaceCardList`, only the row content is swapped for bars while shimmering.
    const rows: Array<SurfaceCardListItem> = isSkeleton
        ? Array.from({ length: 2 }, (_unused, index) => ({
            key: `pending-${index}`,
            content: () => <Typography size="sm" isSkeleton />,
        }))
        : items.map((item) => ({
            key: item.key,
            leadingIcon: KIND_ICON[item.kind],
            title: item.label,
            trailingIcon: ArrowRightIcon,
            onPress: item.onPress,
        }))
    return <SurfaceCardList identity={{ tier: "block", component: "LearnNudges" }} classNames={classNames} items={rows} />
}

"use client"

import {
    CaretDoubleLeftIcon,
    CaretDoubleRightIcon,
} from "@phosphor-icons/react"
import React from "react"
import { useTranslations } from "next-intl"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { toggleRightCollapsed } from "@/redux/slices/sidebar"

/** Props for {@link LearnPanelToggles}. */
export type LearnPanelTogglesProps = Record<string, never>
/**
 * Desktop collapse handle styled as a short accent bar on the content's right
 * border.
 *
 * Container: reads/dispatches the right-rail collapse flag on the `sidebar` slice.
 * The handle (right border) shrinks/expands the module-outline rail. (The LEFT
 * rail now collapses via the {@link import("@/components/blocks").CollapsibleSidebar}
 * block's own toggle, so no left handle is rendered here.) The handle is a slim
 * vertical bar that reveals a direction caret on hover, kept centered in the
 * viewport via a sticky wrapper. Hidden below `lg` (mobile uses drawers). Must be
 * rendered inside a `relative` content column. `"use client"` for redux + presses.
 * @param props - {@link LearnPanelTogglesProps}
 */
export const LearnPanelToggles = () => {
    const t = useTranslations()
    const dispatch = useAppDispatch()
    // current collapse state drives both the caret direction and the aria label
    const rightCollapsed = useAppSelector((state) => state.sidebar.rightCollapsed)

    // short vertical bar that grows a touch on hover
    const barClass = "block h-16 w-1.5 rounded-full bg-accent/60 transition-all duration-200 group-hover:h-24 group-hover:bg-accent"
    // hover caret chip centered on the bar
    const caretClass = "absolute left-1/2 top-1/2 flex size-5 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full bg-accent text-white opacity-0 shadow transition-opacity duration-200 group-hover:opacity-100"

    return (
        // full-height, click-through overlay spanning the content column; desktop only.
        // absolute so it adds no layout, z-20 to float above the article text.
        <div className={"pointer-events-none absolute inset-0 z-20 hidden @app-lg:block"}>
            {/* zero-height bar that sticks at viewport mid-line, so the handle stays centered while scrolling */}
            <div className="sticky top-1/2">
                {/* right handle: sits on the divider between content and the outline rail */}
                <button
                    type="button"
                    aria-label={rightCollapsed ? t("nav.expandRightRail") : t("nav.collapseRightRail")}
                    title={rightCollapsed ? t("nav.expandRightRail") : t("nav.collapseRightRail")}
                    onClick={() => dispatch(toggleRightCollapsed())}
                    className="group pointer-events-auto absolute right-0 top-1/2 -translate-y-1/2 translate-x-1/2 cursor-pointer outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-2 rounded-full"
                >
                    <span className={barClass} />
                    {/* caret points outward (collapse) when expanded, inward (expand) when collapsed */}
                    <span className={caretClass}>
                        {rightCollapsed ? (
                            <CaretDoubleLeftIcon className="size-3" />
                        ) : (
                            <CaretDoubleRightIcon className="size-3" />
                        )}
                    </span>
                </button>
            </div>
        </div>
    )
}

"use client"

import React from "react"
import {
    Chip,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    LockIcon,
} from "@phosphor-icons/react"
import {
    useRouter,
} from "next/navigation"
import {
    useSidebarNavItems,
} from "@/hooks/useSidebarNavItems"
import type {
    LearnNavBadge,
    LearnNavGroup,
} from "@/components/layouts/LearnShellLayout/types"
import { ResumeRail } from "../ResumeRail"
import { CollapsibleSidebar } from "@/components/blocks/navigation/CollapsibleSidebar"
import { SidebarNavGroup } from "@/components/blocks/navigation/SidebarNavGroup"
import { SidebarNavItem } from "@/components/blocks/navigation/SidebarNavItem"
import { SidebarNavAccordionGroup } from "@/components/blocks/navigation/SidebarNavAccordionGroup"

/** localStorage key persisting the learn course-nav collapsed flag. */
const SIDEBAR_STORAGE_KEY = "starci.learn.sidebar.collapsed"

/**
 * Order the labelled nav clusters render in: the mandatory spine (path), then the
 * aids (practice), then the meta surfaces (track). The first group has no divider;
 * every later group gets a full-width {@link SidebarNavGroup} divider on top.
 */
const GROUP_ORDER: ReadonlyArray<LearnNavGroup> = ["path", "practice", "track"]

/**
 * Render a row's trailing status badge: a warning-tinted due-card count, or the
 * viewer's rank as accent text. Kept small so it doesn't crowd the label.
 *
 * @param badge - The {@link LearnNavBadge} to render.
 * @returns The badge node.
 */
const renderBadge = (badge: LearnNavBadge): React.ReactNode => {
    if (badge.tone === "rank") {
        return (
            <Typography type="body-xs" className="text-accent-soft-foreground">
                {`#${badge.value}`}
            </Typography>
        )
    }
    return (
        <Chip size="sm" className="bg-warning-soft text-warning-soft-foreground">
            <Chip.Label>{badge.value}</Chip.Label>
        </Chip>
    )
}

/** Props for {@link LearnSidebar}. */
export type LearnSidebarProps = Record<string, never>
/**
 * Course-learn left navigation rail (desktop).
 *
 * Container: pulls the shared nav entries from {@link useSidebarNavItems} and
 * composes the {@link CollapsibleSidebar} block — which owns the collapse-in-place
 * animation, the toggle, the divider, and persisting the collapsed flag. Rows are
 * split into separator-divided clusters by their `group` (study / practice);
 * each row is a {@link SidebarNavItem} that self-dispatches its tab + navigation
 * through the shared select handler. Hidden below `lg` (mobile uses the drawer in
 * {@link import("../LearnMobileBar").LearnMobileBar}). `"use client"` for the hooks.
 *
 * @param props - {@link LearnSidebarProps}
 */
export const LearnSidebar = () => {
    const t = useTranslations()
    const router = useRouter()
    // shared entries + active tab (also used by the mobile drawer)
    const { items, selectedTab, onSelect } = useSidebarNavItems()
    // role-group captions (sentence case — no uppercase)
    const groupLabels: Record<LearnNavGroup, string> = {
        path: t("nav.groupPath"),
        practice: t("nav.groupPractice"),
        track: t("nav.groupTrack"),
    }
    return (
        <CollapsibleSidebar
            title={t("nav.courseMenu")}
            collapseLabel={t("nav.collapseLeftRail")}
            expandLabel={t("nav.expandLeftRail")}
            storageKey={SIDEBAR_STORAGE_KEY}
            topSlot={<ResumeRail />}
        >
            {GROUP_ORDER.map((group, index) => {
                // rows belonging to this cluster, in their declared order
                const groupItems = items.filter((item) => item.group === group)
                if (groupItems.length === 0) {
                    return null
                }
                return (
                    // first cluster has no divider; later clusters get the full-width separator
                    <SidebarNavGroup key={group} divider={index > 0} label={groupLabels[group]}>
                        {groupItems.map((item) => (
                            item.children ? (
                                <SidebarNavAccordionGroup
                                    key={item.value}
                                    icon={item.icon}
                                    label={item.label}
                                    items={item.children.map((child) => ({
                                        value: child.value,
                                        label: child.label,
                                        isActive: child.isActive,
                                        onPress: () => router.push(child.url),
                                    }))}
                                />
                            ) : (
                                <SidebarNavItem
                                    key={item.value}
                                    icon={<item.icon className="size-5 shrink-0" />}
                                    label={item.label}
                                    isActive={selectedTab === item.tab}
                                    endContent={item.locked ? (
                                        <LockIcon
                                            aria-label={t("enrollGate.locked")}
                                            focusable="false"
                                            className="size-4 text-muted"
                                        />
                                    ) : item.badge ? renderBadge(item.badge) : undefined}
                                    onPress={() => onSelect(item)}
                                />
                            )
                        ))}
                    </SidebarNavGroup>
                )
            })}
        </CollapsibleSidebar>
    )
}

