import React from "react"
import type { ReactNode } from "react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { RatingBar, type RatingOption } from "@/components/blocks/buttons/RatingBar"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `QuizRecapList` — the run is over: go back over what you answered and say how well
 * you actually knew each one. This learner-supplied grade is not the run's verdict —
 * a card can be marked correct yet be one the learner wants back tomorrow (the
 * `CorrectButShaky` case), which the spaced-repetition schedule needs. Already-graded
 * cards keep their rating bar — nothing locks after a tap, so a changed mind still
 * counts. Card count and which are rated are states of one shape; finishing changes
 * only the counter line.
 */

/** One answered card in the recap. */
export interface QuizRecapCard {
    /** Stable React key. */
    key: string
    /** The question, as authored markdown. */
    question: string
    /** The expected answer, as authored markdown. */
    expectedAnswer: string
    /** What the learner typed during the run. */
    givenAnswer?: string
    /** How the run judged it. */
    wasCorrect: boolean
    /** The learner's own recall grade, once they have given one. */
    rating?: number
}

interface QuizRecapListOwnProps {
    /** Recall grades offered per card. */
    ratingOptions: Array<RatingOption>
    /** Fired with the card key and the grade the learner picked. */
    onRate: (cardKey: string, grade: number) => void
    /** Accessible name for each card's rating group, localized by the caller. */
    ratingAriaLabel: string
    /** Card count to shimmer while `isSkeleton` (no real `cards` yet). Defaults to `3`. */
    skeletonCount?: number
}

/**
 * Props for {@link QuizRecapList}. `cards` is REQUIRED unless `isSkeleton`
 * (§12b) — a shimmer recap has no real cards to show yet.
 */
export type QuizRecapListProps = QuizRecapListOwnProps &
    (
        | { isSkeleton: true; cards?: Array<QuizRecapCard> }
        | { isSkeleton?: false; cards: Array<QuizRecapCard> }
    )

/**
 * One recap card's content — verdict chip, question, given/expected answers,
 * rating bar. Extracted to a helper (rather than hoisted to a const) because
 * it depends on the loop variable `card` from the `.map()` that calls it.
 */
const recapCardBody = (
    card: QuizRecapCard,
    ratingOptions: Array<RatingOption>,
    onRate: (cardKey: string, grade: number) => void,
    ratingAriaLabel: string,
): ReactNode => (
    <StackV
        gap={6}
        principle="block-boundary"
        explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
        items={[
            () => (
                <StackH
                    gap={3}
                    principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    align="center"

                    items={[
                        () => (
                            <Chip
                                tone={card.wasCorrect ? "success" : "danger"}
                                text={card.wasCorrect ? "Correct" : "Incorrect"}

                            />
                        ),
                    ]}
                />
            ),
            () => (
                <MarkdownContent
                    source={card.question}
                    measure="compact"

                />
            ),
            ...(card.givenAnswer != null ? [() => (
                <StackV
                    gap={3}

                    items={[
                        () => <Typography size="xs" color="muted" text="Your answer" />,
                        () => <Typography size="sm" text={card.givenAnswer} />,
                    ]}
                />
            )] : []),
            () => (
                <StackV
                    gap={3}

                    items={[
                        () => <Typography size="xs" color="muted" text="Expected answer" />,
                        () => (
                            <MarkdownContent
                                source={card.expectedAnswer}
                                measure="compact"

                            />
                        ),
                    ]}
                />
            ),
            // Stays put after a tap. A learner going back over a run changes
            // their mind, and removing the control would make the first tap
            // final without ever saying so.
            () => (
                <RatingBar
                    options={ratingOptions}
                    onRate={(grade) => onRate(card.key, grade)}
                    ariaLabel={ratingAriaLabel}


                />
            ),
        ]}
    />
)

/**
 * The end-of-run recap. See the file header for the full contract.
 *
 * @param props - {@link QuizRecapListProps}
 */
const QuizRecapList = ({
    cards,
    ratingOptions,
    onRate,
    ratingAriaLabel,
    isSkeleton = false,
    skeletonCount = 3,
}: QuizRecapListProps) => {
    if (isSkeleton) {
        const skeletonCardBody = (
            <>
                <Skeleton className="h-5 w-16 rounded-full" />
                <Skeleton className="h-4 w-full rounded" />
                <Skeleton className="h-4 w-2/3 rounded" />
            </>
        )
        const skeletonCards = Array.from({ length: skeletonCount }, (_unused, index) => (
            <SurfaceCard
                key={index}

                body={() => <StackV gap={6} isSkeleton={isSkeleton} items={[() => skeletonCardBody]} />}
            />
        ))
        const loadingBody = (
            <>
                <Skeleton className="h-3.5 w-40 rounded" />
                {skeletonCards}
            </>
        )
        return (
            <div>
                <StackV gap={6} isSkeleton={isSkeleton} items={[() => loadingBody]} />
            </div>
        )
    }
    const unrated = (cards ?? []).filter((card) => card.rating == null).length

    const recapCards = (cards ?? []).map((card) => (
        <SurfaceCard
            key={card.key}

            body={() => recapCardBody(card, ratingOptions, onRate, ratingAriaLabel)}
        />
    ))

    const recapBody = (
        <>
            {/* Counted, not celebrated. The recap is work; the learner is here to finish
                it, not to be congratulated for starting it. */}
            <Typography
                size="sm"
                color="muted"
                text={unrated > 0 ? `${unrated}/${(cards ?? []).length} cards left to self-grade` : `All ${(cards ?? []).length} cards self-graded`}

            />
            {recapCards}
        </>
    )

    return (
        <div>
            <StackV gap={6} isSkeleton={isSkeleton} items={[() => recapBody]} />
        </div>
    )
}

export { QuizRecapList }

import { InputText } from "@/components/atoms/forms"
import React from "react"
import { type SkeletonProps } from "@/components/frames/_slot"
import { PlayIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { ButtonRadioGroup } from "@/components/composites/buttons/ButtonRadioGroup"

import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCard } from "@/components/composites/cards/SurfaceCard"
import { Callout } from "@/components/composites/feedback/Callout"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `QuizSetup` — choose the shape of a drill (length, seniority, name), then
 * start it. The block owns the domain wording and the lengths behind it: the
 * learner picks "quick" or "deep" and the block turns that into 5 or 10 cards,
 * saying so on the button. A run already in progress takes priority — the resume
 * strip leads the card above the form. A failed draw is reported next to the
 * button that failed.
 */

/** How long a drill runs. */
export type QuizLength = "quick" | "deep"

/** Seniority the questions aim at. */
export type QuizLevel = "junior" | "middle" | "senior" | "staff"

/** Card count per length. The BLOCK owns this — it is the judgement, not a prop. */
const LENGTH_CARDS: Record<QuizLength, number> = { quick: 5, deep: 10 }

const LENGTH_LABEL: Record<QuizLength, string> = { quick: "Quick", deep: "Deep" }

const LEVEL_LABEL: Record<QuizLevel, string> = {
    junior: "Junior",
    middle: "Middle",
    senior: "Senior",
    staff: "Staff",
}

/** A run the learner left unfinished. */
export interface QuizResumable {
    /** What the run was called when it was started. */
    name: string
    /** How many cards were answered already. */
    answered: number
    /** How many cards the run has in total. */
    total: number
    /** Fired when the learner picks the run back up. */
    onResume: () => void
}

/** Props for {@link QuizSetup}. */
export interface QuizSetupProps {
    /** Section label, localized by the caller — e.g. "Set up session". */
    label: string
    /** Current run name. */
    name: string
    /** Fired as the learner types a name. */
    onNameChange: (value: string) => void
    /** Chosen length. */
    length: QuizLength
    /** Fired when the learner picks a length. */
    onLengthChange: (length: QuizLength) => void
    /** Chosen seniority. */
    level: QuizLevel
    /** Fired when the learner picks a seniority. */
    onLevelChange: (level: QuizLevel) => void
    /** Fired when the learner starts the run. */
    onStart: () => void
    /** A run left unfinished. Present → the resume strip leads the card. */
    resumable?: QuizResumable
    /** `true` → the draw is in flight; the start button owns the busy affordance. */
    isPending?: boolean
    /** Set → the draw failed. Reported beside the action that failed. */
    errorMessage?: string
    /** `true` → the card draws its own mirror while the setup data loads. */
    isSkeleton?: boolean
}

/**
 * The drill setup form. See the file header for the full contract.
 *
 * @param props - {@link QuizSetupProps}
 */
const QuizSetup = ({
    label,
    name,
    onNameChange,
    length,
    onLengthChange,
    level,
    onLevelChange,
    onStart,
    resumable,
    isPending = false,
    errorMessage,
    isSkeleton = false,
}: QuizSetupProps) => {
    const nameField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Session name" />,
                ({ isSkeleton }: SkeletonProps) => (
                    <InputText
                        value={name}
                        onValueChange={onNameChange}
                        placeholder="e.g. review Docker before the interview"
                        ariaLabel="Session name"
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    const lengthField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Length" />,
                () => (
                    <ButtonRadioGroup
                        ariaLabel="Session length"
                        value={length}
                        onChange={onLengthChange}

                        items={(Object.keys(LENGTH_LABEL) as Array<QuizLength>).map((key) => ({
                            value: key,
                            content: `${LENGTH_LABEL[key]} · ${LENGTH_CARDS[key]} questions`,
                        }))}
                    />
                ),
            ]}
        />
    )

    const levelField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => <Typography size="sm" weight="medium" isSkeleton={isSkeleton} text="Level" />,
                () => (
                    <ButtonRadioGroup
                        ariaLabel="Question level"
                        value={level}
                        onChange={onLevelChange}

                        items={(Object.keys(LEVEL_LABEL) as Array<QuizLevel>).map((key) => ({
                            value: key,
                            content: LEVEL_LABEL[key],
                        }))}
                    />
                ),
            ]}
        />
    )

    const submitRow = (
        <StackH
            gap={3}
            principle="flex-action"
            explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
            justify="end"
            isSkeleton={isSkeleton}
            items={[
                ({ isSkeleton }: SkeletonProps) => (
                    <Button
                        label={`Start · ${LENGTH_CARDS[length]} questions`}
                        variant="primary"
                        prefixIcon={PlayIcon}
                        onPress={onStart}
                        isPending={isPending}
                        isSkeleton={isSkeleton}

                    />
                ),
            ]}
        />
    )

    // The error sits WITH the action that failed. At the top of the card it
    // would read as a problem with the whole form.
    const actionField = (
        <StackV
            gap={3}
            isSkeleton={isSkeleton}
            items={[
                ...(errorMessage != null ? [() => (
                    <Callout
                        status="danger"
                        title={errorMessage}

                    />
                )] : []),
                () => submitRow,
            ]}
        />
    )

    const formBody = (
        <>
            {resumable != null ? (
                // A learner who left mid-run almost always means to come back. Making
                // them scroll past a start button to find their own session is how one
                // run gets abandoned twice.
                <Callout
                    title={resumable.name}
                    description={`In progress · ${resumable.answered}/${resumable.total} questions`}
                    actionLabel="Continue"
                    onAction={resumable.onResume}

                />
            ) : null}

            {nameField}
            {lengthField}
            {levelField}
            {actionField}
        </>
    )

    return (
        <div>
            <SurfaceCard
                label={label}
                isSkeleton={isSkeleton}

                body={() => <StackV gap={6} isSkeleton={isSkeleton} items={[() => formBody]} />}
            />
        </div>
    )
}

export { QuizSetup }

import React from "react"
import type { ReactNode } from "react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { SurfaceCardPressableGroup, type SurfaceCardPressableGroupItem } from "@/components/composites/cards/SurfaceCard"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `RatingBar` — how well did you remember it: four tiles tapped after an answer is
 * revealed, feeding the spaced-repetition schedule. Shared between flashcard review
 * and quiz recap. Grading is an action, not a selection — nothing stays lit after
 * the tap. The colour ramp (rose → emerald) is a tier, not a status: "I forgot" is
 * not an error and "easy" is not a success, just positions on one axis. The hint
 * line and the pending lock are states; `isSkeleton` is its own leaf.
 */

/** One recall grade offered to the learner. */
export interface RatingOption {
    /** SM-2 grade reported to {@link RatingBarProps.onRate}, 0 = forgot … 3 = easy. */
    grade: number
    /** Button label, localized by the caller (blocks carry no i18n). */
    label: string
    /** Optional second line, usually the next-interval preview. */
    hint?: string
}

/**
 * Grade → palette colour for the tile's verdict band. A grade is a TIER, so it
 * uses the difficulty ramp rather than the status palette.
 */
const GRADE_COLOR: Record<number, string> = {
    0: "rose-500",
    1: "orange-500",
    2: "amber-500",
    3: "emerald-500",
}

/** Props for {@link RatingBar}. */
export interface RatingBarProps {
    /** Grades to offer, weakest recall first. */
    options: Array<RatingOption>
    /** Called with the grade the learner picked. */
    onRate: (grade: number) => void
    /**
     * Accessible name for the group, localized by the caller. Without it a screen
     * reader hears four loose buttons with nothing tying them together.
     */
    ariaLabel: string
    /** `true` → a grade is in flight; every tile stops accepting taps. */
    isPending?: boolean
    /** `true` → the group draws its own tile mirror. */
    isSkeleton?: boolean
}

/**
 * One rating tile's content — label + key-hint chip, plus an optional interval
 * hint. Extracted to a helper (rather than hoisted to a const) because it
 * depends on the loop variables `option`/`position` from the `.map()` that
 * calls it.
 */
const ratingTileBody = (option: RatingOption, position: number): ReactNode => (
    <StackV
        gap={3}
        principle="sibling-stack"
        explain="Same-kind peer stack — not group-boundary, because these items are repeating siblings rather than section groups."

        items={[
            () => (
                <StackH
                    gap={3}
                    principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    align="center"
                    justify="between"

                    items={[
                        () => <Typography size="sm" weight="medium" text={option.label} />,
                        // One chip per tile, and it goes to the KEY — that is the classifying
                        // mark. The interval below is a quiet fact, so it stays as text.
                        () => <Chip tone="default" text={String(position + 1)} />,
                    ]}
                />
            ),
            ...(option.hint != null ? [() => (
                <Typography size="xs" color="muted" text={option.hint} />
            )] : []),
        ]}
    />
)

/**
 * The recall-grade row. See the file header for the full contract.
 *
 * @param props - {@link RatingBarProps}
 */
const RatingBar = ({
    options,
    onRate,
    ariaLabel,
    isPending = false,
    isSkeleton = false,
}: RatingBarProps) => {
    const items: Array<SurfaceCardPressableGroupItem> = options.map((option, position) => ({
        key: String(option.grade),
        onPress: () => onRate(option.grade),
        isDisabled: isPending,
        withVerdict: { enable: true, color: GRADE_COLOR[option.grade] },
        content: () => ratingTileBody(option, position),
    }))

    return (
        <div>
            <div>
                <SurfaceCardPressableGroup ariaLabel={ariaLabel} columns={{ base: 2, md: 4 }} keyboardShortcut items={items} isSkeleton={isSkeleton} principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title." />
            </div>
        </div>
    )
}

export { RatingBar }

import { cn } from "@heroui/react"
import { REACTION_BY_TYPE, type ReactionType } from "../types"

/** Props for the {@link ReactionGlyph} helper below. */
interface ReactionGlyphProps {
