            <SparkleIcon className={cn("size-5 shrink-0", classNames?.icon)} />
            <Chip.Label>{t("cv.submission.aiBrand")}</Chip.Label>
        </Chip>
    )
}

import React from "react"
import { CheckCircleIcon, XCircleIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import { ButtonRadioGroup, type ButtonRadioGroupItem } from "@/components/composites/buttons/ButtonRadioGroup"
import { Chip } from "@/components/atoms/chips/Chip"
import {
    AsyncContent,
    type AsyncContentEmptyProps,
    type AsyncContentErrorProps,
} from "@/components/composites/async/AsyncContent"
import { Cluster } from "@/components/frames/Cluster"

/**
 * `SubmissionAttemptSelector` — which graded attempt the reader is looking at: a
 * flex-wrap row of attempt buttons (verdict + "Attempt N" + score) plus an optional
 * "+N" trigger for the rest of the history. The select chrome is `ButtonRadioGroup`
 * and each button's content is a `Chip`; the block turns `{ attemptNumber, score,
 * isPassing }` into that composition, and the "+N" trigger uses the group's own
 * `trailing` slot. Pressing "+N" only fires `onOverflowPress` — what it opens is a
 * screen decision. Loading, empty, error, few, and many attempts are all states of
 * the one chip strip.
 */

/** One graded attempt the reader can switch to. */
export interface SubmissionAttempt {
    /** Stable id — the value reported to {@link SubmissionAttemptSelectorProps.onSelect}. */
    id: string
    /** 1-based order the attempt was made in — the block turns this into "Attempt N". */
    attemptNumber: number
    /** `null` → not graded yet (or ungraded by design); shown without a score. */
    score: number | null
    /** Drives the verdict glyph + `Chip` tone — pass (`success`) or fail (`danger`). */
    isPassing: boolean
}

/** Props for {@link SubmissionAttemptSelector}. */
export interface SubmissionAttemptSelectorProps {
    /** The attempts offered, in display order. */
    attempts: Array<SubmissionAttempt>
    /** The attempt currently being viewed. Unset → none selected yet. */
    selectedId?: string
    /** Fired with the id of the attempt the reader picked. */
    onSelect: (id: string) => void
    /** Accessible name for the row, localized by the caller (blocks carry no i18n). */
    ariaLabel: string
    /** How many MORE attempts exist beyond this row — set (and > 0) → the "+N" trigger shows. */
    overflowCount?: number
    /** Label for the "+N" trigger. Defaults to `+{overflowCount}` when omitted. */
    overflowLabel?: string
    /**
     * Fired when the reader presses "+N". What that opens is the CALLER's call
     * (Rule 7) — a history drawer, a modal, a route change — this block only
     * reports the press.
     */
    onOverflowPress?: () => void
    /** `true` → this row's own fetch is in flight; the strip shows its skeleton mirror. */
    isLoading?: boolean
    /** `true` (once loading has finished) → the row falls to its empty message. */
    isEmpty?: boolean
    /** Empty-state message. Defaults to a standard "no attempts yet" line. */
    emptyLabel?: string
    /** Truthy → the row falls to its error message (beats loading, per `AsyncContent`). */
    error?: unknown
    /** Retry handler — paired with `retryLabel` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Label of the retry button — required alongside `onRetry` for it to appear. */
    retryLabel?: string
    /** `true` → a parent-forced skeleton paint, same branch as `isLoading` (see file header). */
    isSkeleton?: boolean
}

const EMPTY_LABEL_DEFAULT = "No attempts to choose from yet"
const ERROR_TITLE = "Couldn't load the attempt list"

/** No attempt id is ever the empty string, so `""` safely reads as "none selected". */
const NONE_SELECTED = ""

/** How many skeleton pills mirror the strip while `attempts` hasn't landed yet. */
const SKELETON_ITEM_COUNT = 3

/** Turns one attempt into its `Chip` — the verdict glyph, "Attempt N", and its score. */
const attemptChip = (attempt: SubmissionAttempt) => (
    <Chip
        icon={attempt.isPassing ? CheckCircleIcon : XCircleIcon}
        tone={attempt.isPassing ? "success" : "danger"}
        text={attempt.score != null ? `Attempt ${attempt.attemptNumber} · ${attempt.score}` : `Attempt ${attempt.attemptNumber}`}

    />
)

/** Mirrors the real strip's footprint while attempts are loading — pill-for-pill, no data. */
const AttemptRowSkeleton = () => (
    <Cluster
        gap={3}

        items={Array.from({ length: SKELETON_ITEM_COUNT }, () => () => <Button isSkeleton size="sm" />)}
    />
)

/**
 * The graded-attempt row. See the file header for what it owns (verdict+label
 * wording, the few-vs-many decision) and what it deliberately does not (what
 * "+N" opens).
 *
 * @param props - {@link SubmissionAttemptSelectorProps}
 */
const SubmissionAttemptSelector = ({
    attempts,
    selectedId,
    onSelect,
    ariaLabel,
    overflowCount,
    overflowLabel,
    onOverflowPress,
    isLoading = false,
    isEmpty = false,
    emptyLabel,
    error,
    onRetry,
    retryLabel,
    isSkeleton = false,
}: SubmissionAttemptSelectorProps) => {
    const hasOverflow = (overflowCount ?? 0) > 0

    const emptyContent: AsyncContentEmptyProps = {
        title: emptyLabel ?? EMPTY_LABEL_DEFAULT,

    }

    const errorContent: AsyncContentErrorProps = {
        title: ERROR_TITLE,
        onRetry,
        retryLabel,

    }

    const items: Array<ButtonRadioGroupItem<string>> = attempts.map((attempt) => ({
        value: attempt.id,
        content: attemptChip(attempt),
    }))

    return (
        <div>
            <AsyncContent
                // A parent-forced skeleton and this row's own in-flight fetch share the
                // one loading branch `AsyncContent` exposes (see file header).
                isLoading={isLoading || isSkeleton}
                skeleton={() => <AttemptRowSkeleton />}
                isEmpty={isEmpty}
                emptyContent={emptyContent}
                error={error}
                errorContent={errorContent}

                content={() => (
                    <ButtonRadioGroup
                        ariaLabel={ariaLabel}
                        value={selectedId ?? NONE_SELECTED}
                        onChange={onSelect}
                        items={items}

                        trailing={
                            hasOverflow ? (
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    label={overflowLabel ?? `+${overflowCount}`}
                                    onPress={onOverflowPress}

                                />
                            ) : undefined
                        }
                    />
                )}
            />
        </div>
    )
}

export { SubmissionAttemptSelector }

import React from "react"
import type { ComponentType, ReactNode, SVGProps } from "react"
import { InfoIcon, LightbulbIcon, MapPinIcon, WarningCircleIcon } from "@phosphor-icons/react"
import { cn } from "@heroui/react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import {
    AsyncContentEmpty,
    AsyncContentError,
} from "@/components/composites/async/AsyncContent"
import { SurfaceCardAccordion, type SurfaceCardAccordionItem } from "@/components/composites/cards/SurfaceCard"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * `SubmissionFindingsList` — "Feedback": one accordion row per quality-gate finding
 * on a graded attempt — severity icon + plain-text message (backtick code only) +
 * location chip in the trigger; markdown detail, a linked file location, and a
 * markdown suggestion in the panel. The frame is `SurfaceCard.Accordion` end to end;
 * the block supplies the domain (severity → icon/tone/sort-rank, the high→low sort,
 * the repo-URL → file-link builder). Loading, empty, error, and populated are all
 * states of the one accordion card, routed through its own `isSkeleton`/`emptyState`
 * axes.
 */

/** Severity a finding carries — drives the trigger icon/tone and the sort rank (high sorts first). */
export type SubmissionFeedbackSeverity = "high" | "medium" | "low"

/** An icon passed as a COMPONENT, rendered by this block at the size the text beside it uses. */
type SeverityIconComponent = ComponentType<SVGProps<SVGSVGElement> & { weight?: "regular" | "bold" }>

/** One severity's trigger icon + text tone + sort rank — see {@link SEVERITY_VISUAL}. */
interface SeverityVisual {
    /** Trigger icon for this severity. */
    icon: SeverityIconComponent
    /** Tailwind text-color class for the icon (matches the severity's weight). */
    iconTone: string
    /** Sort rank — lower sorts first (high = 0). */
    rank: number
}

/**
 * Severity → trigger icon + text tone + sort rank. This is the block's own
 * domain vocabulary, never something a caller hands in.
 */
const SEVERITY_VISUAL: Record<SubmissionFeedbackSeverity, SeverityVisual> = {
    high: { icon: WarningCircleIcon, iconTone: "text-danger", rank: 0 },
    medium: { icon: WarningCircleIcon, iconTone: "text-warning", rank: 1 },
    low: { icon: InfoIcon, iconTone: "text-muted", rank: 2 },
}

/** One quality-gate finding for a graded attempt. */
export interface SubmissionFinding {
    /** Stable id — also the accordion row's expand key. */
    id: string
    /**
     * Short summary shown (clamped to one line) in the accordion trigger — plain
     * text, at most `` `code` `` spans (never bold/italic/link: a trigger title
     * is tier 1). Full markdown
     * belongs in `detail`/`suggestion`, which render in the panel body instead.
     */
    message: string
    /** Longer explanation, authored as markdown, shown in the panel. */
    detail?: string
    /** Suggested fix, authored as markdown, shown in the panel. */
    suggestion?: string
    /** Repo-relative file path this finding points at, e.g. `src/app/page.tsx`. */
    location?: string
    /** High/medium/low — decides the trigger icon/tone and the sort order. */
    severity: SubmissionFeedbackSeverity
    /** Author-authored order among findings that share a severity. Defaults to `0`. */
    sortIndex?: number
}

/** Props for {@link SubmissionFindingsList}. */
export interface SubmissionFindingsListProps {
    /** The findings, in ANY order — the block re-sorts them itself (severity, then `sortIndex`). */
    findings: Array<SubmissionFinding>
    /**
     * Repo URL the attempt was submitted from — turns each `location` into a
     * `blob/HEAD` deep-link. Omit → `location` still shows, as plain text.
     */
    repositoryUrl?: string
    /** Section label rendered above the card (e.g. `"Feedback"`). */
    label: string
    /** `true` → this list's own fetch is in flight; the card falls to its self-mirror. */
    isLoading?: boolean
    /** `true` (once loading has finished) → the card falls to its empty message. */
    isEmpty?: boolean
    /** Empty-state title. Defaults to a standard "no findings yet" line. */
    emptyLabel?: string
    /** Truthy → the card falls to its error message (beats loading/empty — see file header). */
    error?: unknown
    /** Retry handler — paired with `retryLabel` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Label of the retry button — required alongside `onRetry` for it to appear. */
    retryLabel?: string
    /** `true` → a parent-forced skeleton paint, same branch as `isLoading` (see file header). */
    isSkeleton?: boolean
}

const EMPTY_LABEL_DEFAULT = "No feedback yet"
const ERROR_TITLE = "Could not load feedback"

/**
 * High → low, then by each finding's own authored order. The block's own
 * vocabulary, so a caller never has to pre-sort what it hands in.
 */
const sortFindings = (findings: ReadonlyArray<SubmissionFinding>): Array<SubmissionFinding> =>
    [...findings].sort((a, b) => {
        const rankDiff = SEVERITY_VISUAL[a.severity].rank - SEVERITY_VISUAL[b.severity].rank
        return rankDiff !== 0 ? rankDiff : (a.sortIndex ?? 0) - (b.sortIndex ?? 0)
    })

/**
 * `repositoryUrl` + a repo-relative `location` → a `blob/HEAD` deep-link. Ported
 * from `FindingAccordionItem` unchanged.
 */
const buildLocationHref = (location: string, repositoryUrl?: string): string | undefined =>
    repositoryUrl ? `${repositoryUrl.replace(/\.git$/, "")}/blob/HEAD/${location.replace(/^\//, "")}` : undefined

/**
 * Trigger icon: the severity glyph, its OWN tone colour independent of the
 * title text — rides `titleStart`, not composed into `title` itself (§ same
 * rule as `ChallengeDeliverableList`'s status icon).
 */
const findingIcon = (finding: SubmissionFinding): ReactNode => {
    const { icon: Icon, iconTone } = SEVERITY_VISUAL[finding.severity]
    return (
        <Icon
            aria-hidden
            focusable="false"
            weight="bold"

            className={cn("size-3.5 shrink-0", iconTone)}
        />
    )
}

/** Trailing trigger slot: the finding's file location, as a quiet chip. */
const findingLocationChip = (finding: SubmissionFinding): ReactNode | undefined =>
    finding.location ? (
        <Chip
            tone="default"
            text={finding.location}
            classNames={["shrink-0"]}

        />
    ) : undefined

/**
 * Panel content: the markdown detail, the linked file location, and the markdown
 * suggested fix — each optional, each its own row (`related`: independent facts
 * about one finding, not a single unit of meaning).
 */
const findingPanel = (finding: SubmissionFinding, repositoryUrl: string | undefined): ReactNode => {
    const locationHref = finding.location ? buildLocationHref(finding.location, repositoryUrl) : undefined
    const locationRow = finding.location ? (
        <StackH
            gap={2}
            align="center"
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            items={[
                () => <MapPinIcon aria-hidden focusable="false" weight="bold" className="size-3 shrink-0 text-muted" />,
                () =>
                    locationHref ? (
                        <Typography
                            size="xs"
                            color="muted"
                            isLink
                            underlineOnHover
                            href={locationHref}
                            target="_blank"
                            rel="noopener noreferrer"
                            text={finding.location}

                        />
                    ) : (
                        <Typography size="xs" color="muted" text={finding.location} />
                    ),
            ]}
        />
    ) : null
    const suggestionRow = finding.suggestion ? (
        <StackH
            gap={2}
            align="start"
            principle="icon-text"
            explain="Icon beside its label — not name-handle, because this pairs a glyph with text rather than a name/handle identity."
            items={[
                () => <LightbulbIcon aria-hidden focusable="false" weight="bold" className="size-3.5 shrink-0 text-muted" />,
                () => (
                    <div className="min-w-0 flex-1 text-muted [&_p]:m-0">
                        <MarkdownContent
                            source={finding.suggestion ?? ""}
                            measure="compact"

                        />
                    </div>
                ),
            ]}
        />
    ) : null
    return (
        <StackV
            gap={3}

            items={[
                ...(finding.detail ? [() => (
                    <div className="text-muted [&_p]:m-0">
                        <MarkdownContent
                            source={finding.detail ?? ""}
                            measure="compact"

                        />
                    </div>
                )] : []),
                () => locationRow,
                () => suggestionRow,
            ]}
        />
    )
}

/** Props for {@link ErrorEmptyState}. */
interface ErrorEmptyStateProps {
    onRetry?: () => void
    retryLabel?: string
}

const ErrorEmptyState = ({ onRetry, retryLabel }: ErrorEmptyStateProps) => (
    <AsyncContentError
        title={ERROR_TITLE}
        onRetry={onRetry}
        retryLabel={retryLabel}
    />
)

/** Props for {@link PlainEmptyState}. */
interface PlainEmptyStateProps {
    title: string
}

const PlainEmptyState = ({ title }: PlainEmptyStateProps) => (
    <AsyncContentEmpty title={title} />
)

/**
 * The "Feedback" findings card. See the file header for what this block owns
 * (severity vocabulary, sort order, the repo-URL→file-link builder) and why
 * loading/empty/error all stay bounded inside the one `SurfaceCard.Accordion`
 * frame instead of swapping it out for `AsyncContent`'s own switch.
 *
 * @param props - {@link SubmissionFindingsListProps}
 */
const SubmissionFindingsList = ({
    findings,
    repositoryUrl,
    label,
    isLoading = false,
    isEmpty,
    emptyLabel,
    error,
    onRetry,
    retryLabel,
    isSkeleton = false,
}: SubmissionFindingsListProps) => {
    // Error outranks even a stale loading/skeleton flag — same priority order
    // `AsyncContent` itself documents ("error → loading → empty → content") — so a
    // caller handing both `error` and `isLoading` still sees the error, not a
    // skeleton pretending the fetch is still running.
    const skeleton = !error && (isLoading || isSkeleton)
    const resolvedEmpty = !error && (isEmpty ?? findings.length === 0)

    const items: Array<SurfaceCardAccordionItem> = error
        ? []
        : sortFindings(findings).map((finding) => ({
            id: finding.id,
            titleStart: () => findingIcon(finding),
            title: finding.message,
            titleEnd: () => findingLocationChip(finding),
            body: () => findingPanel(finding, repositoryUrl),
        }))

    const emptyState = error
        ? () => <ErrorEmptyState onRetry={onRetry} retryLabel={retryLabel} />
        : resolvedEmpty
            ? () => <PlainEmptyState title={emptyLabel ?? EMPTY_LABEL_DEFAULT} />
            : undefined

    return (
        <SurfaceCardAccordion
            identity={{ tier: "block", component: "SubmissionFindingsList" }}
            label={label}
            items={items}
            isSkeleton={skeleton}
            emptyState={emptyState}


        />
    )
}

export { SubmissionFindingsList }

import React from "react"
import { LinkBack } from "@/components/atoms/navigation/Link"
import { PageHeader } from "@/components/composites/layout/Page"

/**
 * `SubmissionResultHeader` — the identity band of a graded-result page: a way back
 * to the challenge, plus the requirement's title and description. Sibling of
 * `ContentHeader`, but a result page has left the material — no read-state chip,
 * minutes, or outcomes card, just "where am I, what is this, how do I leave". The
 * breadcrumb slot holds a `LinkBack` composed from `backLabel` + `onBack`. One
 * shape: `isSkeleton` is a state, since only the data changes.
 */

/** Props for {@link SubmissionResultHeader}. */
export interface SubmissionResultHeaderProps {
    /** Back-link label, localized by the caller, e.g. "Back to the solution". */
    backLabel: string
    /** Fired when the learner leaves the result page for the challenge solve page. */
    onBack: () => void
    /** The graded requirement's title. */
    title: string
    /** The requirement's own description/prompt. Omitted → the header ends at the title. */
    description?: string
    /**
     * `true` → every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms (or their skeleton mirror when the atom has none
     * of its own) rather than building a parallel skeleton tree (§12c).
     */
    isSkeleton?: boolean
}

/**
 * Identity band of a graded-result page. See the file header for the full
 * contract and why the breadcrumb slot holds a back-link instead of a trail.
 *
 * @param props - {@link SubmissionResultHeaderProps}
 */
const SubmissionResultHeader = ({
    backLabel,
    onBack,
    title,
    description,
    isSkeleton = false,
}: SubmissionResultHeaderProps) => {
    return (
        <div>
            <PageHeader
                isSkeleton={isSkeleton}
                breadcrumb={() => (
                    <LinkBack label={backLabel} onPress={onBack} isSkeleton={isSkeleton} />
                )}
                title={title}
                description={description}
            />
        </div>
    )
}

export { SubmissionResultHeader }

import React from "react"
import { WarningIcon } from "@phosphor-icons/react"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import { Callout } from "@/components/composites/feedback/Callout"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { MarkdownContent } from "@/components/composites/viewers/MarkdownContent"
import { SurfaceCardAccordion, type SurfaceCardAccordionItem } from "@/components/composites/cards/SurfaceCard"
import { ContentRelatedList, type ContentRelatedItem } from "@/components/blocks/learn/ContentRelatedList"
import { StackV } from "@/components/frames/Stack"

/**
 * `TaskBriefBody` — the reading column of a personal-project milestone task. A task
 * resolves into exactly one of two shapes depending on whether it carries a Schema
 * V2 brief: `SchemaV2Brief` (modern per-language markdown instructions) or
 * `LegacySchemaV1` (the older public criteria accordion + code guides). A task is
 * never both, so these are two leaves; `Skeleton` is a third (the block guesses
 * Schema V2 while loading). Within each schema shape, `isLocked` toggling the notice
 * is a plain data state.
 */

/** One pass criterion of a SCHEMA V1 (legacy) task — `src`'s `MilestoneTaskCriteriaEntity`. */
export interface TaskBriefCriteriaItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** Criterion trigger text. */
    text: string
    /** Grading hint, markdown. Blank → the row shows a plain "no hint yet" line instead. */
    hint?: string
    /** Points this criterion is worth — rides as a trailing chip on the trigger. */
    score: number
}

/** One per-language implementation guide of a SCHEMA V1 (legacy) task — `src`'s `CodeImplementationEntity`. */
export interface TaskBriefCodeImplementationItem {
    /** Stable React key, also the accordion item id. */
    key: string
    /** Language label (typescript / java / csharp / go). */
    lang: string
    /** Mapping guide, markdown. */
    guide: string
    /** Example code, markdown. */
    example: string
}

/** Props for {@link TaskBriefBody}. */
export interface TaskBriefBodyProps {
    /** Task title. */
    title: string
    /** Task description. Omitted when the task carries none. */
    description?: string
    /**
     * `true` → the learner is previewing a task ahead of their current progress:
     * the reading stays visible but a warning notice replaces the graded panel
     * (out of scope here) with a way back to the unlocked task.
     */
    isLocked: boolean
    /** Fired from the locked notice's "go to current task" button. */
    onGoToCurrentTask: () => void
    /**
     * SCHEMA V2 per-language brief, already resolved to the active locale by
     * the backend (`src`'s `TaskBrief`). Blank/absent ⇒ this is a SCHEMA V1
     * task and the legacy fallback below takes over instead.
     */
    briefBody?: string
    /** SCHEMA V1 fallback: public pass criteria. Read only when `briefBody` is blank. */
    legacyCriteria?: ReadonlyArray<TaskBriefCriteriaItem>
    /** SCHEMA V1 fallback: per-language implementation guides. Read only when `briefBody` is blank. */
    legacyCodeImplementations?: ReadonlyArray<TaskBriefCodeImplementationItem>
    /** Related lessons worth reading before this task. Empty → `ContentRelatedList` renders nothing. */
    relatedItems: Array<ContentRelatedItem>
    /** Section label for the related list, localized by the caller. */
    relatedLabel: string
    /** `true` → title/description and the brief-body guess switch to their own shimmer. */
    isSkeleton?: boolean
}

/** Fixed copy for the locked-preview notice — this block owns its own wording (§14d.1). */
const LOCKED_ALERT_TITLE = "Finish the previous task first"
const LOCKED_ALERT_DESCRIPTION = "You can still read this task's criteria. AI evaluation, feedback, history and the GitHub section unlock once you finish the previous step."
const LOCKED_ALERT_BUTTON_LABEL = "Back to current task"

/** Fixed copy for the SCHEMA V1 fallback card's two sub-labels. */
const CRITERIA_LABEL = "Grading criteria"
const CRITERIA_EMPTY_TITLE = "This task has no grading criteria yet."
const CRITERIA_NO_HINT = "No guidance for this criterion yet."
const IMPLEMENTATION_GUIDE_HEADING = "Guide"
const IMPLEMENTATION_EXAMPLE_HEADING = "Example"

/** `SurfaceCardAccordion.emptyState` for the SCHEMA V1 criteria fallback — a component reference (COMPOSITE-4), not a built element. */
const CriteriaEmptyState = () => <EmptyState title={CRITERIA_EMPTY_TITLE} />

/** How many shimmer paragraph lines `BriefMarkdown` guesses while `isSkeleton` — see file header. */
const BRIEF_SKELETON_LINE_WIDTHS = ["w-full", "w-full", "w-3/4", "w-2/3"] as const

/**
 * The personal-project task reading column. See the file header for the full
 * schema-generation contract and every judgement call.
 *
 * @param props - {@link TaskBriefBodyProps}
 */
const TaskBriefBody = ({
    title,
    description,
    isLocked,
    onGoToCurrentTask,
    briefBody,
    legacyCriteria,
    legacyCodeImplementations,
    relatedItems,
    relatedLabel,
    isSkeleton = false,
}: TaskBriefBodyProps) => {
    const trimmedBrief = briefBody?.trim() ?? ""
    // Schema-generation test, identical to `src`'s `(displayTask?.briefs?.length ?? 0) === 0`:
    // a brief present ⇒ SCHEMA V2, this task's rubric stays internal to the brief text.
    // While isSkeleton the generation isn't known yet — guessed SCHEMA V2, see file header.
    const showBrief = isSkeleton || trimmedBrief.length > 0
    const showLegacy = !isSkeleton && trimmedBrief.length === 0

    const criteriaItems: Array<SurfaceCardAccordionItem> = (legacyCriteria ?? []).map((item, index) => ({
        id: item.key,
        title: `${index + 1}. ${item.text}`,
        titleEnd: () => <Chip tone="accent" text={`${item.score} pts`} />,
        body: () => (
            item.hint?.trim() ? (
                <MarkdownContent source={item.hint} measure="compact" />
            ) : (
                <Typography size="sm" color="muted" isItalic text={CRITERIA_NO_HINT} />
            )
        ),
    }))

    const implementationBody = (item: TaskBriefCodeImplementationItem) => (
        <StackV
            gap={2}
            items={[
                () => <Typography size="xs" weight="semibold" color="muted" text={IMPLEMENTATION_GUIDE_HEADING} />,
                () => <MarkdownContent source={item.guide} measure="compact" />,
                () => <Typography size="xs" weight="semibold" color="muted" text={IMPLEMENTATION_EXAMPLE_HEADING} />,
                () => <MarkdownContent source={item.example} measure="compact" />,
            ]}
        />
    )

    const implementationItems: Array<SurfaceCardAccordionItem> = (legacyCodeImplementations ?? []).map((item) => ({
        id: item.key,
        title: item.lang,
        body: () => implementationBody(item),
    }))

    const readingColumn = (
        <>
            {/* TitleDesc — always present; both lines fall back to their own shimmer bar. */}
            <StackV
                gap={2}
                isSkeleton={isSkeleton}

                items={[
                    () => <Typography size="h3" weight="bold" isSkeleton={isSkeleton} classNames={isSkeleton ? ["w-1/2"] : undefined} text={title} />,
                    ...(isSkeleton
                        ? [() => <Typography size="sm" color="muted" isSkeleton classNames={["w-2/3"]} />]
                        : description != null && description.trim().length > 0
                            ? [() => <Typography size="sm" color="muted" text={description} />]
                            : []),
                ]}
            />

            {/* LockedAlert — self-hides when unlocked; honored regardless of `isSkeleton` since
                `isLocked` is already-resolved data the caller holds, same call as
                `ContentArticle`'s own `isLocked`. */}
            {isLocked ? (
                <Callout
                    status="warning"
                    icon={WarningIcon}
                    title={LOCKED_ALERT_TITLE}
                    description={LOCKED_ALERT_DESCRIPTION}
                    actionLabel={LOCKED_ALERT_BUTTON_LABEL}
                    onAction={onGoToCurrentTask}

                />
            ) : null}

            {/* BriefMarkdown — SCHEMA V2. Skeleton guesses a plain shimmer paragraph rather
                than calling `MarkdownContent` with no source, mirroring `ChallengeBrief`'s
                own list-skeleton judgement call (a viewer needs a real payload; a guessed
                loading state cannot fabricate one). */}
            {showBrief ? (
                isSkeleton ? (
                    <StackV
                        gap={2}
                        isSkeleton={isSkeleton}

                        items={BRIEF_SKELETON_LINE_WIDTHS.map((width) => () => (
                            <Typography size="base" isSkeleton classNames={[width]} />
                        ))}
                    />
                ) : (
                    <MarkdownContent source={trimmedBrief} measure="reading" />
                )
            ) : null}

            {/* LegacyCriteriaCard — SCHEMA V1 fallback ONLY, never while isSkeleton (see file header). */}
            {showLegacy ? (
                <StackV
                    gap={4}
                    isSkeleton={isSkeleton}

                    items={[
                        () => <Typography size="sm" weight="semibold" text={CRITERIA_LABEL} />,
                        () => (
                            <SurfaceCardAccordion
                                items={criteriaItems}
                                allowsMultipleExpanded
                                emptyState={CriteriaEmptyState}


                            />
                        ),
                        ...(implementationItems.length > 0 ? [() => (
                            <SurfaceCardAccordion
                                items={implementationItems}
                                allowsMultipleExpanded


                            />
                        )] : []),
                    ]}
                />
            ) : null}

            {/* RelatedList — the block never gates it; `ContentRelatedList` already self-hides. */}
            <ContentRelatedList
                items={relatedItems}
                label={relatedLabel}
                isSkeleton={isSkeleton}


            />
        </>
    )

    return (
        <StackV identity={{ tier: "block", component: "TaskBriefBody" }} gap={6} isSkeleton={isSkeleton} items={[() => readingColumn]} />
    )
}

