import React from "react"
import { ArrowRightIcon } from "@phosphor-icons/react"
import { Callout } from "@/components/composites/feedback/Callout"
import { Alert } from "@/components/atoms/feedback/Alert"
import { Button } from "@/components/atoms/buttons/Button"

/**
 * `TrialEnrollBanner` — the ambient "you're on a trial" nudge, reused across every
 * free surface a trial learner can reach (foundations resource page and grid, and
 * leaderboard). A caller-resolved `isVisible` drives shown vs hidden; it renders
 * both a title and a description, and `isSkeleton` covers the enrollment check still
 * being in flight. Three leaves: "shown"/"hidden" differ in structure (a node vs an
 * empty tree), and the skeleton (two text bars, no CTA) is a third structure.
 */

/** Props for {@link TrialEnrollBanner}. */
export interface TrialEnrollBannerProps {
    /**
     * `true` → the caller has resolved the learner as a known trial learner
     * (not yet enrolled) and wants the nudge shown. `false` covers BOTH
     * "enrolled" and "not yet known" — either way the banner renders nothing
     * (the "not yet known" window instead goes through {@link isSkeleton}).
     */
    isVisible: boolean
    /** Fired when the learner taps the CTA (caller owns opening the enroll flow). */
    onEnroll: () => void
    /**
     * `true` → the enrollment check that feeds `isVisible` is still in flight.
     * Reserves the banner's shape without shimmering the copy (fixed, not
     * fetched) and without a CTA (nothing to press before the check lands).
     * Wins over `isVisible`.
     */
    isSkeleton?: boolean
}

/**
 * The trial → enroll ambient nudge. See the file header for the self-gating
 * condition, the consolidation history, and why `isSkeleton` is a separate
 * window from `isVisible = false`.
 *
 * @param props - {@link TrialEnrollBannerProps}
 */
const TrialEnrollBanner = ({
    isVisible,
    onEnroll,
    isSkeleton = false,
}: TrialEnrollBannerProps) => {
    if (isSkeleton) {
        // `Callout` has no `isSkeleton` of its own (§12c gap, same one
        // `CourseTeamGate` already documents) — its `title`/`description` slots
        // render inside `<p>` (`Alert.Title`/`Alert.Description`), which cannot
        // legally contain the `<div>` a hand-built `Typography isSkeleton` bar
        // emits (real hydration error, caught live in this exact leaf). `Alert`
        // itself DOES own `isSkeleton` and draws two safe `<div>` bars straight
        // inside its content region — call it directly, same precedent as
        // `CourseTeamGate.tsx`.
        return (
            <div>
                <Alert
                    isSkeleton
                    status="accent"

                />
            </div>
        )
    }

    // SELF-HIDE — the block owns its own show condition; the screen doesn't need to ask.
    if (!isVisible) {
        return null
    }

    return (
        <div>
            <Callout
                status="accent"
                title="You're on a trial"
                description="Unlock the full course and build proof of work employers can see on your profile."

                body={() => (
                    <Button
                        label="Unlock the course"
                        variant="primary"
                        size="sm"
                        suffixIcon={ArrowRightIcon}
                        iconSlide
                        onPress={onEnroll}

                    />
                )}
            />
        </div>
    )
}

export { TrialEnrollBanner }

"use client"

import React, {
    useCallback,
} from "react"
import {
    useTranslations,
} from "next-intl"
import { Callout } from "@/components/composites/feedback/Callout"
import { Box } from "@/components/frames/Box"
import { useAppSelector } from "@/redux/hooks"
import { usePaymentOverlayState } from "@/hooks/zustand/overlay/hooks"
import { PaymentFlow } from "@/modules/types/payment"

/** Props for {@link TrialEnrollHook}. */
export type TrialEnrollHookProps = Record<string, never>
/**
 * A thin, self-gating "you're on a trial → unlock the course" banner for the
 * FREE learn surfaces (leaderboard, foundations, flashcard study) — the ambient
 * arm of the conversion spine ([[layout-must-funnel-to-courses]]). Renders NOTHING
 * once the status query settles as enrolled (or before it settles), so a paid
 * learner never sees it and it never flashes. Outcome-framed (build real job
 * proof), one line, non-interruptive — not a popup, not repeated. Reads the
 * course off Redux; opens the shared enroll payment flow.
 *
 * @param props - optional className (placement only).
 */
export const TrialEnrollHook = () => {
    const t = useTranslations()
    const enrolled = useAppSelector((state) => state.user.enrolled)
    const enrollKnown = useAppSelector((state) => state.user.enrollKnown)
    const { open } = usePaymentOverlayState()

    /** Open the shared payment modal in the course-enroll flow. */
    const onEnroll = useCallback(
        () => open({
            flow: PaymentFlow.CourseEnroll,
        }),
        [open],
    )

    // only a settled trial (logged-in, not purchased) sees the hook
    if (!enrollKnown || enrolled) {
        return null
    }

    return (
        <Box identity={{ tier: "block", component: "TrialEnrollHook" }}>
            <Callout
                status="accent"
                title={t("enrollGate.hookTitle")}
                description={t("enrollGate.hookDesc")}
                actionLabel={t("enrollGate.hookCta")}
                onAction={onEnroll}
            />
        </Box>
    )
}

"use client"

import type { ReactNode } from "react"
import { ArrowRightIcon, CheckCircleIcon } from "@phosphor-icons/react"
import { SectionCard } from "@/components/blocks/cards/SectionCard"
import { Button } from "@/components/atoms/buttons/Button"
import { Typography } from "@/components/atoms/text/Typography"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * Props for the {@link UpNextCard} block.
 *
 * A presentational, props-only "you just finished — here's the next rung" card
 * fired at the COMPLETION moment of a learn surface (end of a lesson, end of a
 * flashcard session, a scorecard…) to hand the learner off to the next step in
 * the course loop while momentum is high. It performs no data fetching and reads
 * no store — the caller computes the next rung and wires navigation via
 * {@link onPress} (and {@link secondaryOnPress}).
 */
export interface UpNextCardProps {
    /**
     * Small quiet eyebrow above the title (e.g. "Next"). Rendered muted.
     * Pair with {@link showCheck} for the "you just finished ✓" micro-feedback.
     */
    eyebrow?: ReactNode
    /**
     * When true, a success check precedes the eyebrow — the completion
     * micro-feedback that makes the next CTA read as riding the momentum.
     */
    showCheck?: boolean
    /** The next rung, phrased as the concrete thing to do next (the CTA's promise). */
    title: ReactNode
    /**
     * Optional one-line "why / toward what outcome" under the title — frame it
     * toward the outcome (e.g. moving the job-readiness band), not generically.
     */
    description?: ReactNode
    /** Primary CTA label — descriptive + contextual ("Do 2 challenges from this lesson"). */
    ctaLabel: ReactNode
    /** Primary CTA press handler (caller wires router navigation). */
    onPress: () => void
    /** Optional secondary, quieter action label (e.g. "Do the chapter capstone"). */
    secondaryLabel?: ReactNode
    /** Optional secondary press handler. */
    secondaryOnPress?: () => void
}

/**
 * UpNextCard renders the single, prominent completion-handoff card for the course
 * learning loop. It stacks: an optional check + eyebrow ("Done · Next"),
 * the next rung as a title, an optional outcome-framed description, then ONE
 * primary CTA (accent, `size="lg"`, trailing arrow — the one obvious next action)
 * and an optional quiet secondary link. Static card + button affordance (the card
 * itself is not pressable — the CTA is the single, clear target). Composes
 * {@link SectionCard} for the card face — its own content stack already runs
 * `flex flex-col gap-3`, so this block hands it three rows directly rather than
 * adding a layout wrapper of its own.
 *
 * @param props - {@link UpNextCardProps}
 */
export const UpNextCard = ({
    eyebrow,
    showCheck,
    title,
    description,
    ctaLabel,
    onPress,
    secondaryLabel,
    secondaryOnPress,
}: UpNextCardProps) => {
    const hasEyebrowRow = Boolean(eyebrow || showCheck)

    return (
        <SectionCard identity={{ tier: "block", component: "UpNextCard" }}>
            {/* completion micro-feedback + "next" eyebrow */}
            {hasEyebrowRow ? (
                <StackH
                    gap={2}
                    items={[
                        ...(showCheck ? [() => (
                            <CheckCircleIcon
                                aria-hidden
                                focusable="false"
                                className="size-5 shrink-0 text-success-soft-foreground"
                            />
                        )] : []),
                        ...(eyebrow ? [() => (
                            <Typography size="xs" color="muted" text={eyebrow} />
                        )] : []),
                    ]}
                />
            ) : null}

            {/* the next rung */}
            <StackV
                gap={2}
                items={[
                    () => <Typography size="base" weight="semibold" text={title} />,
                    ...(description ? [() => (
                        <Typography size="sm" color="muted" text={description} />
                    )] : []),
                ]}
            />

            {/* one primary CTA (+ optional quiet secondary) */}
            <Cluster
                gap={3}
                items={[
                    () => (
                        <Button
                            variant="primary"
                            size="lg"
                            label={ctaLabel}
                            suffixIcon={ArrowRightIcon}
                            onPress={onPress}
                        />
                    ),
                    ...(secondaryLabel && secondaryOnPress ? [() => (
                        <Button variant="tertiary" label={secondaryLabel} onPress={secondaryOnPress} />
                    )] : []),
                ]}
            />
        </SectionCard>
    )
}

import React from "react"
import { Chip } from "@/components/atoms/chips/Chip"
import { capitalize, DIFFICULTY_COLOR, type VariantChipDifficultyProps } from "../types"

/**
 * `VariantChipDifficulty` — a color dot by tier + a difficulty word (GitHub
 * language-dot style). A thin wrapper over the `Chip` atom; color comes from
 * {@link DIFFICULTY_COLOR}.
 *
 * The shape is ALWAYS a pill — the atom's default, and design doesn't expose a
 * shape axis to the caller (see the ⛔ note at the top of this file).
 *
 * @param props - {@link VariantChipDifficultyProps}
 */
export const VariantChipDifficulty = ({
    difficulty,
    classNames,
    isSkeleton,
}: VariantChipDifficultyProps) => {
    // Part name so the anatomy tree can call out exactly what this design builds —
    // the tree reads off the DOM, so without a name the story reveals nothing
    // about what it's made of.
    // The label must be the NAMESPACE name (`Chip`) because readers look it
    // up by story name.
    // Two branches because the atom's `isSkeleton` is a disjoint union (when
    // skeleton, `text` isn't required): passing a single `boolean | undefined`
    // into one call site wouldn't type-check. The skeleton branch STILL keeps
    // `dotClassName` so the atom sizes the box correctly while leaving room for
    // the dot.
    const chip = isSkeleton ? (
        <Chip
            isSkeleton
            dotClassName={DIFFICULTY_COLOR[difficulty]}
            classNames={classNames}
        />
    ) : (
        <Chip
            dotClassName={DIFFICULTY_COLOR[difficulty]}
            text={capitalize(difficulty)}
            classNames={classNames}
        />
    )
    // Part name goes on the span that WRAPS the chip itself — NOT through
    // `AnatomyOverlay`.
    //
    // The overlay emits an `inset-0` span sitting NEXT TO the chip rather than
    // wrapping it, so `Dot`/`Label` (inside the chip) walking up the ancestor
    // chain never reach `VariantChipDifficulty` → the anatomy tree flattens
    // wrong, with the two atoms jumping up to sit level with design. The tree
    // is inferred from the DOM, so the name
    // must sit on the node that ACTUALLY contains the children.
    return chip
}

/** The supported difficulty levels a piece of content can be tagged with. */
export type Difficulty = "beginner" | "intermediate" | "advanced" | "insane"

/**
 * Dot color scale by difficulty tier — the SSOT for this ramp, import it, don't
 * redeclare it.
 *
 * Uses a sequential Tailwind palette ramp (hotter = harder) INSTEAD OF the 5
 * semantic tokens (`accent`/`success`/`warning`/`danger`/`default`): difficulty is
 * a **TIER**, not a **STATE** — forcing 4 tiers into semantic tokens would collide
 * on `danger` twice.
 */
export const DIFFICULTY_COLOR: Record<Difficulty, string> = {
    beginner: "text-emerald-500",
    intermediate: "text-amber-500",
    advanced: "text-orange-500",
    insane: "text-rose-500",
}

/** Props for {@link VariantChipDifficulty}. */
export interface VariantChipDifficultyProps {
    /** Difficulty tier — decides BOTH the label AND the dot color. The one axis. */
    difficulty: Difficulty
    /**
     * Extra classes on the wrapper. A closed union, not a free string: this
     * value is handed straight to `Chip`'s own closed `classNames` union, so an
     * unconstrained string here would only fail one tier down.
     */
    classNames?: Array<import("@/components/atoms/_allowed-class-name").AllowedClassName>
    /** `true` → shimmer bar mirroring the exact dot+label shape (the atom draws it itself). */
    isSkeleton?: boolean
    /** Dev/spec: overlay anatomy labels on this chip. */
}

/** Title-case a difficulty key for the default label. */
export const capitalize = (value: Difficulty): string => value.charAt(0).toUpperCase() + value.slice(1)

import { InputTextarea } from "@/components/atoms/forms"
import { useState } from "react"
import { MicrophoneIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"

import { Typography } from "@/components/atoms/text/Typography"
import { StackV } from "@/components/frames/Stack"

/**
 * `VoiceHero` — the voice-first answer composer. A large push-to-talk mic with
 * its live transcript is the hero; a quiet typed textarea is the fallback for
 * browsers without speech-to-text, or lessons that only want typed answers.
 * Two structural leaves — `MicHero` (circular button + transcript) and
 * `TypedFallback` (textarea + switch-back link) — chosen from `sttSupported`
 * and `answerMode`, plus an ephemeral toggle reachable only when both input
 * methods are offered (`answerMode="both"` with STT supported). The
 * "type instead" / "use voice" link is a state inside each leaf, tracking the
 * `canToggle` boolean. No `isSkeleton` — nothing to mirror.
 */

/** How the caller wants an answer collected. */
export type VoiceAnswerMode = "voice" | "text" | "both"

/** Wording for both leaves — the block carries no i18n of its own (§14d.1). */
export interface VoiceHeroLabels {
    /** Aria label for the mic button while NOT listening. */
    pushToTalk: string
    /** Aria label for the mic button, and its transcript-line hint, WHILE listening with nothing recognized yet. */
    listening: string
    /** Switch-away link shown in `MicHero` when both input methods are offered. */
    typeInstead: string
    /** Switch-back link shown in `TypedFallback` when both input methods are offered. */
    useVoice: string
    /** Placeholder of the typed field, and `MicHero`'s idle empty-transcript hint. */
    placeholder: string
}

/** Props for {@link VoiceHero}. */
export interface VoiceHeroProps {
    /** `false` → this browser/device cannot do speech-to-text; only `TypedFallback` is ever offered. */
    sttSupported: boolean
    /** `true` → the mic is actively recording. */
    listening: boolean
    /** Live, not-yet-committed transcript while `listening`. Empty once recognized speech lands in `value`. */
    interimTranscript: string
    /** The committed answer — final voice transcript, or whatever the learner typed. */
    value: string
    /** Fired as the typed field changes. Voice never calls this directly; recognized speech lands in `value` upstream. */
    onValueChange: (value: string) => void
    /** Fired when the mic button is pressed, toggling `listening`. */
    onToggleListen: () => void
    /** Which input method(s) this answer accepts. See the file header for how it decides a leaf. */
    answerMode: VoiceAnswerMode
    /** Wording for both leaves. */
    labels: VoiceHeroLabels
}

/**
 * The voice-first answer composer. See the file header for leaf selection and
 * the transcript/mic-color judgement calls.
 *
 * @param props - {@link VoiceHeroProps}
 */
const VoiceHero = ({
    sttSupported,
    listening,
    interimTranscript,
    value,
    onValueChange,
    onToggleListen,
    answerMode,
    labels,
}: VoiceHeroProps) => {
    // Ephemeral UI-only choice — see file header. Only reachable when BOTH leaves
    // are actually on offer, so there is nothing to reset when the caller's props change.
    const [manualTyped, setManualTyped] = useState(false)

    const forcedText = !sttSupported || answerMode === "text"
    const forcedVoice = sttSupported && answerMode === "voice"
    const canToggle = !forcedText && !forcedVoice
    const showTypedFallback = forcedText || (canToggle && manualTyped)

    if (showTypedFallback) {
        return (
            <div>
                <StackV
                    gap={4}

                    items={[
                        () => (
                            <InputTextarea
                                value={value}
                                onValueChange={onValueChange}
                                placeholder={labels.placeholder}
                                ariaLabel={labels.placeholder}
                                rows={5}

                            />
                        ),
                        ...(canToggle ? [() => (
                            <Typography
                                size="sm"
                                isLink
                                text={labels.useVoice}
                                onPress={() => setManualTyped(false)}

                            />
                        )] : []),
                    ]}
                />
            </div>
        )
    }

    // Provisional whenever there is nothing FINAL to show yet: an interim fragment
    // still being recognized, or (while listening) no speech landed in `value` at all.
    const transcriptIsProvisional = listening && (interimTranscript.length > 0 || value.length === 0)
    const transcriptText = listening && interimTranscript
        ? interimTranscript
        : value || (listening ? labels.listening : labels.placeholder)

    return (
        <div>
            <StackV
                gap={4}
                principle="card-caption"
                explain="Holds caption text under card media so the caption stays attached to the image above it."
                align="center"

                items={[
                    () => (
                        <Button
                            isIconOnly
                            size="lg"
                            variant={listening ? "danger" : "primary"}
                            prefixIcon={MicrophoneIcon}
                            ariaLabel={listening ? labels.listening : labels.pushToTalk}
                            onPress={onToggleListen}

                        />
                    ),
                    // real `src` (`VoiceHero/index.tsx:136`): `<Typography color="default">`
                    // declares NO `type` ⇒ defaults to base (16px), not `lg`.
                    () => (
                        <Typography
                            size="base"
                            align="center"
                            color={transcriptIsProvisional ? "muted" : "default"}
                            isItalic={transcriptIsProvisional}
                            text={transcriptText}

                        />
                    ),
                    ...(canToggle ? [() => (
                        <Typography
                            size="sm"
                            isLink
                            text={labels.typeInstead}
                            onPress={() => setManualTyped(true)}

                        />
                    )] : []),
                ]}
            />
        </div>
    )
}

export { VoiceHero }

"use client"

import {
    CaretDownIcon,
    LockIcon,
    SparkleIcon,
} from "@phosphor-icons/react"
import React from "react"
import { Dropdown, DropdownItem, DropdownMenu, DropdownPopover, DropdownSection, DropdownTrigger, Tooltip } from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import type {
    AiLabModelSelection,
} from "../types"
import { AiModelCategory } from "@/modules/api/graphql/queries/query-ai-models"
import { type AiGradableModel } from "@/modules/api/graphql/queries/types/ai-models"
import { AiCategoryChip } from "@/components/blocks/chips/AiCategoryChip"

/** Props for {@link LaneModelPicker}. */
export type LaneModelPickerProps = {
    /** Enabled models the user can pick from (from the `aiModels` catalog). */
    models: Array<AiGradableModel>
    /** The current lane + model selection. */
    selection: AiLabModelSelection
    /** Whether the Premium lane (specific models) is unlocked for this user. */
    canPremium: boolean
    /** Disables the whole control (e.g. while a run is in flight). */
    isDisabled?: boolean
    /** Fired with the new selection when the user picks an option. */
    onSelect: (selection: AiLabModelSelection) => void
    /** Fired when a locked (subscription-required) model is pressed — route to AI settings. */
    onUpgrade: () => void
}

/**
 * Lane + model picker for an AI Lab run.
 *
 * Presentational: renders the free "Auto" lane plus every catalog model (each tagged
 * with its cost category chip) and forwards the chosen {@link AiLabModelSelection}.
 * Premium models are locked unless `canPremium`. Mirrors the challenge panel's
 * `GradeModelDropdown` but uses the local selection type.
 * @param props - {@link LaneModelPickerProps}
 */
export const LaneModelPicker = ({
    models,
    selection,
    canPremium,
    isDisabled = false,
    onSelect,
    onUpgrade}: LaneModelPickerProps) => {
    const t = useTranslations()
    const isAuto = selection.model === null
    const triggerLabel = isAuto
        ? t("aiSettings.lanes.auto.title")
        : selection.model

    return (
        <Dropdown>
            <DropdownTrigger
                isDisabled={isDisabled}
                className={"cursor-pointer"}
            >
                <div className="flex items-center gap-2">
                    <SparkleIcon className="size-5" />
                    <span className="max-w-40 truncate">{triggerLabel}</span>
                    <CaretDownIcon weight="bold" className="size-4" />
                </div>
            </DropdownTrigger>
            <DropdownPopover
                placement="bottom start"
                className="min-w-64"
            >
                <DropdownMenu aria-label={t("aiSettings.pickModel")}>
                    {/* Auto lane — balancer picks a complimentary model, free of charge */}
                    <DropdownSection>
                        <DropdownItem
                            key="auto"
                            onPress={() => onSelect({
                                model: null,
                                provider: null,
                            })}
                        >
                            <div className="flex items-center gap-2">
                                <span>{t("aiSettings.lanes.auto.title")}</span>
                            </div>
                        </DropdownItem>
                    </DropdownSection>
                    {/* One entry per catalog model, with a category chip. Free + Economy
                        models run without a plan; Balanced + Premium are locked without a
                        subscription (pressing routes to AI settings). */}
                    <DropdownSection className="border-t border-divider pt-1 mt-1">
                        {models.map((model) => {
                            const key = `${model.provider}:${model.model}`
                            const categoryChip = <AiCategoryChip category={model.category} />
                            // Free + Economy are usable without a plan; Balanced + Premium
                            // require a paid subscription.
                            const requiresPlan = model.category === AiModelCategory.Medium
                                || model.category === AiModelCategory.High
                            if (!model.available) {
                                return (
                                    <DropdownItem
                                        key={key}
                                        textValue={model.model}
                                        onPress={() => undefined}
                                    >
                                        <Tooltip>
                                            <Tooltip.Trigger>
                                                <div className="flex w-full items-center justify-between gap-2 text-muted">
                                                    <span className="flex min-w-0 items-center gap-2">
                                                        <LockIcon className="size-5 shrink-0" />
                                                        <span className="truncate">{model.model}</span>
                                                    </span>
                                                    {categoryChip}
                                                </div>
                                            </Tooltip.Trigger>
                                            <Tooltip.Content>{t("aiSettings.modelUnavailable")}</Tooltip.Content>
                                        </Tooltip>
                                    </DropdownItem>
                                )
                            }
                            if (requiresPlan && !canPremium) {
                                return (
                                    <DropdownItem
                                        key={key}
                                        textValue={model.model}
                                        onPress={onUpgrade}
                                    >
                                        <Tooltip>
                                            <Tooltip.Trigger>
                                                <div className="flex w-full items-center justify-between gap-2 text-muted">
                                                    <span className="flex min-w-0 items-center gap-2">
                                                        <LockIcon className="size-5 shrink-0" />
                                                        <span className="truncate">{model.model}</span>
                                                    </span>
                                                    {categoryChip}
                                                </div>
                                            </Tooltip.Trigger>
                                            <Tooltip.Content>{t("aiSettings.subscribeToGrade")}</Tooltip.Content>
                                        </Tooltip>
                                    </DropdownItem>
                                )
                            }
                            return (
                                <DropdownItem
                                    key={key}
                                    textValue={model.model}
                                    onPress={() => onSelect({
                                        model: model.model,
                                        provider: model.provider,
                                    })}
                                >
                                    <div className="flex items-center justify-between gap-2">
                                        <span className="truncate">{model.model}</span>
                                        {categoryChip}
                                    </div>
                                </DropdownItem>
                            )
                        })}
                    </DropdownSection>
                </DropdownMenu>
            </DropdownPopover>
        </Dropdown>
    )
}

"use client"

import React from "react"
import {
    useTranslations,
} from "next-intl"
import type {
    AiLabParamsForm,
} from "../types"

/** Props for {@link ParamControls}. */
export type ParamControlsProps = {
    /** Current generation params. */
    params: AiLabParamsForm
    /** Disables all inputs (e.g. while a run is in flight). */
    isDisabled?: boolean
    /** Fired with the patched params when any field changes. */
    onChange: (params: AiLabParamsForm) => void
}

/** One labelled numeric param input row. */
interface ParamFieldProps {
    /** Label shown above the input. */
    label: string
    /** DOM id for the input. */
    id: string
    /** Current numeric value. */
    value: number
    /** Smallest allowed value. */
    min: number
    /** Largest allowed value. */
    max: number
    /** Step increment. */
    step: number
    /** Disables the input. */
    isDisabled: boolean
    /** Fired with the parsed number on change. */
    onChange: (value: number) => void
}

/** A single numeric param input, styled to match the codebase's plain-input convention. */
const ParamField = ({
    label,
    id,
    value,
    min,
    max,
    step,
    isDisabled,
    onChange,
}: ParamFieldProps) => (
    <div className="flex flex-col gap-2">
        <label
            htmlFor={id}
            className="text-sm text-muted"
        >
            {label}
        </label>
        <input
            id={id}
            type="number"
            min={min}
            max={max}
            step={step}
            value={Number.isFinite(value) ? value : ""}
            disabled={isDisabled}
            onChange={(event) => onChange(Number(event.target.value))}
            className="w-full rounded-2xl border border-default bg-background px-4 py-2 text-sm text-foreground focus:border-accent focus:outline-none disabled:opacity-50"
        />
    </div>
)

/**
 * Three numeric inputs for the generation params (temperature / top-p / max tokens).
 *
 * Presentational — the parent owns the {@link AiLabParamsForm} state and receives a
 * full patched object on every change.
 * @param props - {@link ParamControlsProps}
 */
export const ParamControls = ({
    params,
    isDisabled = false,
    onChange}: ParamControlsProps) => {
    const t = useTranslations()
    return (
        <div className={"grid grid-cols-1 gap-3 @app-sm:grid-cols-3"}>
            <ParamField
                id="ai-lab-temperature"
                label={t("aiLab.playground.temperature")}
                value={params.temperature}
                min={0}
                max={2}
                step={0.1}
                isDisabled={isDisabled}
                onChange={(temperature) => onChange({ ...params, temperature })}
            />
            <ParamField
                id="ai-lab-top-p"
                label={t("aiLab.playground.topP")}
                value={params.topP}
                min={0}
                max={1}
                step={0.05}
                isDisabled={isDisabled}
                onChange={(topP) => onChange({ ...params, topP })}
            />
            <ParamField
                id="ai-lab-max-tokens"
                label={t("aiLab.playground.maxTokens")}
                value={params.maxTokens}
                min={1}
                max={32000}
                step={1}
                isDisabled={isDisabled}
                onChange={(maxTokens) => onChange({ ...params, maxTokens })}
            />
        </div>
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
    useState,
} from "react"
import { Button, Chip, Spinner } from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    LaneModelPicker,
} from "../LaneModelPicker"
import { GradeCreditCaption } from "@/components/blocks/grading/GradeCreditCaption"
import { SurfaceListCard, SurfaceListCardItem } from "@/components/blocks/cards/SurfaceListCard"
import {
    ParamControls,
} from "../ParamControls"
import type {
    AiLabModelSelection,
    AiLabParamsForm,
} from "../types"
import { type AiGradableModel } from "@/modules/api/graphql/queries/types/ai-models"
import { type AiLabPlaygroundData } from "@/modules/api/graphql/queries/types/ai-lab-playground"
import { type GraphQLResponse } from "@/modules/api/graphql/types"
import { type RunPlaygroundPromptData } from "@/modules/api/graphql/mutations/types/run-playground-prompt"
import { useAiLabRunStreamSocketIo } from "@/hooks/socketio/useAiLabRunStreamSocketIo"
import { useMutateRunPlaygroundPromptSwr } from "@/hooks/swr/api/graphql/mutations/useMutateRunPlaygroundPromptSwr"
import { useQueryAiModelsSwr } from "@/hooks/swr/api/graphql/queries/useQueryAiModelsSwr"
import { useQueryMyAiQuotaSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyAiQuotaSwr"
import { useQueryMyAiSettingsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyAiSettingsSwr"
import { useQueryMyAiLabRunsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyAiLabRunsSwr"
import { AiLabRunStatus } from "@/hooks/socketio/types/ai-lab"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { useGraphQLWithToast } from "@/modules/toast/hooks"

/** Props for {@link PromptPlayground}. */
export type PromptPlaygroundProps = {
    /** The playground bound to this lesson. */
    playground: AiLabPlaygroundData
}

/** Default param values used when the playground does not seed them. */
const FALLBACK_PARAMS: AiLabParamsForm = {
    temperature: 0.7,
    topP: 1,
    maxTokens: 1024,
}

/** Build the param form from the playground defaults (falling back per field). */
const buildDefaultParams = (playground: AiLabPlaygroundData): AiLabParamsForm => ({
    temperature: playground.defaultParams?.temperature ?? FALLBACK_PARAMS.temperature,
    topP: playground.defaultParams?.topP ?? FALLBACK_PARAMS.topP,
    maxTokens: playground.defaultParams?.maxTokens ?? FALLBACK_PARAMS.maxTokens,
})

/**
 * Prompt playground surface: system + user prompt inputs, generation params, a lane/model
 * picker, and a Run/Abort control. The streamed response is read live from the Redux
 * `aiLabRunById` map via {@link useAiLabRunStreamSocketIo}; cache hits render inline.
 *
 * Container: owns the editable prompt/param/selection state and the run mutation, then
 * subscribes to the `/ai_lab` token stream for non-cached runs.
 * @param props - {@link PromptPlaygroundProps}
 */
export const PromptPlayground = ({ playground}: PromptPlaygroundProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const runGraphQL = useGraphQLWithToast()

    // Editable prompt + param + lane state, seeded from the playground defaults.
    const [systemPrompt, setSystemPrompt] = useState(playground.defaultSystemPrompt ?? "")
    const [userPrompt, setUserPrompt] = useState(playground.defaultUserPrompt ?? "")
    const [params, setParams] = useState<AiLabParamsForm>(() => buildDefaultParams(playground))
    const [selection, setSelection] = useState<AiLabModelSelection>({
        model: null,
        provider: null,
    })

    // The run currently being tracked (set after the mutation returns a streaming run id).
    const [runId, setRunId] = useState<string | undefined>(undefined)
    // Inline output when the run was served from cache (no socket stream).
    const [cachedOutput, setCachedOutput] = useState<string | null>(null)
    // Window budget hint returned by the last run.
    const [quotaExhausted, setQuotaExhausted] = useState(false)

    const runPromptSwr = useMutateRunPlaygroundPromptSwr()
    const { run, subscribe, abort, reset } = useAiLabRunStreamSocketIo(runId)

    // Lane/model catalog + entitlement for the picker.
    const aiModelsSwr = useQueryAiModelsSwr()
    const aiSettingsSwr = useQueryMyAiSettingsSwr()
    const canPremium = Boolean(aiSettingsSwr.data?.canPremium)
    const aiQuotaSwr = useQueryMyAiQuotaSwr()
    const runsSwr = useQueryMyAiLabRunsSwr(playground.id)

    const gradableModels = useMemo<Array<AiGradableModel>>(
        () => aiModelsSwr.data?.aiModels?.data?.gradableModels ?? [],
        [aiModelsSwr.data],
    )

    /** Route to AI settings so the user can subscribe or add a BYOK key. */
    const onGoToAiSettings = useCallback(
        () => {
            router.push(`/${locale}/profile/settings/ai-settings`)
        },
        [router, locale],
    )

    // The run is streaming while the socket has a live, not-yet-done entry for it.
    const isStreaming = Boolean(run && !run.done)
    const isPending = runPromptSwr.isMutating || isStreaming

    /** Submit the prompt: fire the mutation, then either render the cache hit or subscribe to the stream. */
    const onRun = useCallback(
        async () => {
            if (!userPrompt.trim()) {
                return
            }
            // Reset prior run state before starting a new one.
            if (runId) {
                reset(runId)
            }
            setRunId(undefined)
            setCachedOutput(null)
            // The run payload captured from the mutation so the success path can drive streaming.
            let result: GraphQLResponse<RunPlaygroundPromptData> | undefined
            const ok = await runGraphQL<RunPlaygroundPromptData>(
                async () => {
                    const response = await runPromptSwr.trigger({
                        playgroundId: playground.id,
                        systemPrompt: systemPrompt.trim() || undefined,
                        userPrompt: userPrompt.trim(),
                        params: {
                            temperature: params.temperature,
                            topP: params.topP,
                            maxTokens: params.maxTokens,
                        },
                        selectedModel: selection.model ?? undefined,
                        selectedModelProvider: selection.provider ?? undefined,
                    })
                    result = response.data?.runPlaygroundPrompt
                    if (!result?.success || !result.data) {
                        throw new Error(result?.message ?? response.error?.message)
                    }
                    return result
                },
                { showSuccessToast: false },
            )
            if (!ok || !result?.data) {
                return
            }
            const { runId: nextRunId, status, cachedOutput: nextCachedOutput, quotaExhausted: exhausted } =
                result.data
            setQuotaExhausted(exhausted)
            // Cache hit: the output is returned inline, never streamed over the socket.
            if (status === AiLabRunStatus.Cached) {
                setCachedOutput(nextCachedOutput ?? "")
                setRunId(nextRunId)
                return
            }
            // Live run: track it and subscribe to the token stream.
            setRunId(nextRunId)
            subscribe(nextRunId)
        },
        [
            userPrompt,
            runId,
            reset,
            runGraphQL,
            runPromptSwr,
            playground.id,
            systemPrompt,
            params,
            selection,
            subscribe,
        ],
    )

    /** Abort the in-flight stream. */
    const onAbort = useCallback(
        () => {
            if (runId) {
                abort(runId)
            }
        },
        [runId, abort],
    )

    /** Restore the prompts/params to the playground defaults and drop the tracked run. */
    const onReset = useCallback(
        () => {
            setSystemPrompt(playground.defaultSystemPrompt ?? "")
            setUserPrompt(playground.defaultUserPrompt ?? "")
            setParams(buildDefaultParams(playground))
            setSelection({ model: null, provider: null })
            setCachedOutput(null)
            if (runId) {
                reset(runId)
            }
            setRunId(undefined)
        },
        [playground, runId, reset],
    )

    // Output to render: cache hit text, otherwise the accumulated stream.
    const outputText = cachedOutput ?? run?.output ?? ""
    const isCached = cachedOutput !== null
    const isFailed = run?.status === AiLabRunStatus.Failed
    const promptTokens = run?.promptTokens
    const completionTokens = run?.completionTokens
    const priorRuns = runsSwr.data ?? []

    return (
        <div className={"flex flex-col gap-6"}>
            <div className="flex flex-col gap-2">
                <h3 className="text-lg font-semibold">{t("aiLab.playground.title")}</h3>
                <p className="text-sm text-muted">{t("aiLab.playground.description")}</p>
            </div>

            {/* System prompt */}
            <div className="flex flex-col gap-2">
                <label
                    htmlFor="ai-lab-system-prompt"
                    className="text-sm text-muted"
                >
                    {t("aiLab.playground.systemPrompt")}
                </label>
                <textarea
                    id="ai-lab-system-prompt"
                    rows={3}
                    value={systemPrompt}
                    disabled={isPending}
                    onChange={(event) => setSystemPrompt(event.target.value)}
                    placeholder={t("aiLab.playground.systemPromptPlaceholder")}
                    className="w-full resize-y rounded-2xl border border-default bg-background px-4 py-3 text-sm text-foreground focus:border-accent focus:outline-none disabled:opacity-50"
                />
            </div>

            {/* User prompt */}
            <div className="flex flex-col gap-2">
                <label
                    htmlFor="ai-lab-user-prompt"
                    className="text-sm text-muted"
                >
                    {t("aiLab.playground.userPrompt")}
                </label>
                <textarea
                    id="ai-lab-user-prompt"
                    rows={5}
                    value={userPrompt}
                    disabled={isPending}
                    onChange={(event) => setUserPrompt(event.target.value)}
                    placeholder={t("aiLab.playground.userPromptPlaceholder")}
                    className="w-full resize-y rounded-2xl border border-default bg-background px-4 py-3 text-sm text-foreground focus:border-accent focus:outline-none disabled:opacity-50"
                />
            </div>

            {/* Params */}
            <div className="flex flex-col gap-2">
                <span className="text-sm text-muted">{t("aiLab.playground.params")}</span>
                <ParamControls
                    params={params}
                    isDisabled={isPending}
                    onChange={setParams}
                />
            </div>

            {/* Lane/model + actions */}
            <div className="flex flex-wrap items-center justify-between gap-3">
                <div className="flex items-center gap-2">
                    <span className="text-sm text-muted">{t("aiLab.playground.model")}:</span>
                    <LaneModelPicker
                        models={gradableModels}
                        selection={selection}
                        canPremium={canPremium}
                        isDisabled={isPending}
                        onSelect={setSelection}
                        onUpgrade={onGoToAiSettings}
                    />
                    <GradeCreditCaption
                        creditUsage={aiQuotaSwr.data}
                        hasPinnedModel={Boolean(selection.model)}
                        autoCreditCost={undefined}
                    />
                </div>
                <div className="flex items-center gap-2">
                    <Button
                        variant="tertiary"
                        size="sm"
                        isDisabled={isPending}
                        onPress={onReset}
                    >
                        {t("aiLab.playground.resetToDefault")}
                    </Button>
                    {isStreaming ? (
                        <Button
                            variant="danger"
                            size="sm"
                            onPress={onAbort}
                        >
                            {t("aiLab.playground.abort")}
                        </Button>
                    ) : null}
                    <Button
                        variant="primary"
                        size="sm"
                        isPending={isPending}
                        isDisabled={!userPrompt.trim()}
                        onPress={onRun}
                    >
                        {t("aiLab.playground.run")}
                    </Button>
                </div>
            </div>

            {/* Quota exhausted nudge → BYOK */}
            {quotaExhausted ? (
                <div className="flex flex-wrap items-center justify-between gap-2 rounded-2xl border border-warning/30 bg-warning-soft p-3">
                    <span className="text-sm">
                        {t("aiLab.playground.quotaExhausted")} {t("aiLab.playground.byokNudge")}
                    </span>
                    <Button
                        variant="secondary"
                        size="sm"
                        onPress={onGoToAiSettings}
                    >
                        {t("aiLab.playground.goToAiSettings")}
                    </Button>
                </div>
            ) : null}

            {/* Output pane */}
            <div className="flex flex-col gap-2">
                <div className="flex items-center gap-2">
                    <span className="text-sm text-muted">{t("aiLab.playground.output")}</span>
                    {isCached ? (
                        <Chip
                            size="sm"
                            color="default"
                            variant="soft"
                        >
                            {t("aiLab.playground.cached")}
                        </Chip>
                    ) : null}
                    {isStreaming ? <Spinner size="sm" /> : null}
                </div>
                <div className="min-h-24 rounded-3xl border border-default bg-surface p-4">
                    {isFailed ? (
                        <span className="text-sm text-danger-soft-foreground">
                            {run?.errorMessage ?? t("aiLab.playground.failed")}
                        </span>
                    ) : outputText ? (
                        <MarkdownContent markdown={outputText} />
                    ) : (
                        <span className="text-sm text-muted">{t("aiLab.playground.outputEmpty")}</span>
                    )}
                </div>
                {(promptTokens != null || completionTokens != null) ? (
                    <span className="text-xs text-muted">
                        {t("aiLab.playground.tokens", {
                            prompt: promptTokens ?? 0,
                            completion: completionTokens ?? 0,
                        })}
                    </span>
                ) : null}
            </div>

            {/* Prior runs */}
            {priorRuns.length > 0 ? (
                <div className="flex flex-col gap-2">
                    <span className="text-sm text-muted">{t("aiLab.playground.runHistory")}</span>
                    <SurfaceListCard bordered>
                        {priorRuns.map((priorRun) => (
                            <SurfaceListCardItem key={priorRun.id}>
                                <div className="flex items-center justify-between gap-3">
                                    <span className="min-w-0 truncate text-sm">{priorRun.userPrompt}</span>
                                    <Chip
                                        size="sm"
                                        color={priorRun.status === AiLabRunStatus.Failed ? "danger" : "default"}
                                        variant="soft"
                                    >
                                        {t(`aiLab.status.${priorRun.status}`)}
                                    </Chip>
                                </div>
                            </SurfaceListCardItem>
                        ))}
                    </SurfaceListCard>
                </div>
            ) : null}
        </div>
    )
}

"use client"

import React from "react"
import {
    PromptPlayground,
} from "./PromptPlayground"
import { useAppSelector } from "@/redux/hooks"
import { useQueryAiLabPlaygroundSwr } from "@/hooks/swr/api/graphql/queries/useQueryAiLabPlaygroundSwr"

/** Props for the AI Lab tab body. */
export type AiLabBodyProps = Record<string, never>
/** Known AI Lab playground kinds (mirrors backend `AiLabPlaygroundKind`). */
const PLAYGROUND_KIND = {
    Prompt: "prompt",
    Rag: "rag",
    Comparison: "comparison",
} as const

/**
 * AI Lab tab body: resolves the lesson's playground from SWR, then renders the matching
 * surface by `kind` (prompt → {@link PromptPlayground}; rag / comparison → placeholder).
 * Reads `content` from Redux to scope the playground query.
 * @param props - Optional wrapper styling props.
 */
export const AiLab = () => {
    const content = useAppSelector((state) => state.content.entity)
    const playgroundSwr = useQueryAiLabPlaygroundSwr(content?.id)
    const playground = playgroundSwr.data

    if (!playground) {
        return null
    }

    return (
        <div className={"flex flex-col gap-6"}>
            {playground.kind === PLAYGROUND_KIND.Prompt ? (
                <PromptPlayground playground={playground} />
            ) : (
                // RAG / comparison playgrounds are P1/P2 — fall back to the prompt surface,
                // which still drives a single prompt run against the configured model.
                <PromptPlayground playground={playground} />
            )}
        </div>
    )
}

import type { ModelProvider } from "@/modules/api/graphql/queries/query-my-ai-settings"

/**
 * A concrete model the user picked in the AI Lab.
 *
 * Mirrors the challenge panel's selection shape but lives locally so the AI Lab
 * surfaces do not import modal-internal types.
 */
export interface AiLabModelSelection {
    /** Concrete model name; null on the Auto lane (balancer chooses). */
    model: string | null
    /** Provider serving {@link model}; null on the Auto lane. */
    provider: ModelProvider | null
}

/** Generation params edited by the param controls (kept as numbers for the inputs). */
export interface AiLabParamsForm {
    /** Sampling temperature. */
    temperature: number
    /** Nucleus sampling top-p. */
    topP: number
    /** Max output tokens. */
    maxTokens: number
}

"use client"

import {
    TrophyIcon,
    FlameIcon,
    LightbulbIcon,
    CircleIcon,
    CircleNotchIcon,
    CheckCircleIcon,
    XCircleIcon,
    PlayIcon,
    ArrowClockwiseIcon,
    EyeIcon,
    type Icon,
} from "@phosphor-icons/react"
import React, { useMemo } from "react"
import { Button, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { useParams } from "next/navigation"
import { useRouter } from "@/i18n/navigation"
import { ChallengeDifficulty } from "@/modules/types/enums/challenge-difficulty"
import { type ChallengeEntity } from "@/modules/types/entities/challenge"
import type { ChallengeProgressStatus } from "@/modules/api/graphql/queries/types/challenge-submission-progress"
import { DifficultyChip } from "@/components/blocks/chips/DifficultyChip"
import { toDifficulty } from "@/modules/utils/difficulty"
import { useAppSelector } from "@/redux/hooks"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"

/** i18n key for each difficulty tier label (covers all 5 BE tiers). */
const DIFFICULTY_LABEL_KEY: Record<ChallengeDifficulty, string> = {
    [ChallengeDifficulty.Easy]: "challenge.difficulty.easy",
    [ChallengeDifficulty.Medium]: "challenge.difficulty.medium",
    [ChallengeDifficulty.Hard]: "challenge.difficulty.hard",
    [ChallengeDifficulty.Insane]: "challenge.difficulty.insane",
    [ChallengeDifficulty.Expert]: "challenge.difficulty.expert",
}

/** Status → eyebrow chip (icon + label color). */
const STATUS_META: Record<ChallengeProgressStatus, { labelKey: string; className: string; icon: Icon }> = {
    notStarted: { labelKey: "challenge.status.notStarted", className: "text-muted", icon: CircleIcon },
    inProgress: { labelKey: "challenge.status.inProgress", className: "text-warning-soft-foreground", icon: CircleNotchIcon },
    failed: { labelKey: "challenge.status.failed", className: "text-danger-soft-foreground", icon: XCircleIcon },
    completed: { labelKey: "challenge.status.completed", className: "text-success-soft-foreground", icon: CheckCircleIcon },
}

/** Status → primary action label + icon (resume semantics). */
const CTA_META: Record<ChallengeProgressStatus, { labelKey: string; icon: Icon }> = {
    notStarted: { labelKey: "challenge.cta.start", icon: FlameIcon },
    inProgress: { labelKey: "challenge.cta.continue", icon: PlayIcon },
    failed: { labelKey: "challenge.cta.retry", icon: ArrowClockwiseIcon },
    completed: { labelKey: "challenge.cta.review", icon: EyeIcon },
}

/** Props for {@link ChallengeCard}. */
export interface ChallengeCardProps {
    /** Challenge row displayed in content tab. */
    challenge: ChallengeEntity
}

/**
 * One challenge in the "Challenges" tab — a single card (bounded object): puzzle
 * eyebrow + status chip → title → difficulty/score/hint chips → clamped description
 * → footer (attempts + best score on the left, status-driven primary action on the
 * right). The card is a static surface — only the footer button navigates.
 * @param {ChallengeCardProps} props Challenge card props.
 */
export const ChallengeCard = ({ challenge}: ChallengeCardProps) => {
    const t = useTranslations()
    const router = useRouter()
    const params = useParams()
    // Per-challenge progress, populated by `useQueryChallengeSubmissionProgressSwr`.
    const completionTasks = useAppSelector((state) => state.challenge.completionTasks)
    const progress = useMemo(
        () => completionTasks.find((completionTask) => completionTask.id === challenge.id) ?? null,
        [completionTasks, challenge.id],
    )
    const status: ChallengeProgressStatus = progress?.status ?? "notStarted"
    const statusMeta = STATUS_META[status]
    const ctaMeta = CTA_META[status]
    const StatusIcon = statusMeta.icon
    const CtaIcon = ctaMeta.icon

    // Footer-left progress line: attempts + best score, or "not attempted yet".
    const maxScore = progress?.maxScore ?? challenge.score
    const attemptsLine = useMemo(() => {
        const attempts = progress?.numAttempts ?? 0
        if (attempts <= 0) {
            return t("challenge.attempts.none")
        }
        const base = t("challenge.attempts.some", { count: attempts })
        if (progress?.lastScore == null) {
            return base
        }
        return `${base} · ${t("challenge.attempts.bestScore", { score: progress.lastScore, maxScore })}`
    }, [progress?.numAttempts, progress?.lastScore, maxScore, t])

    const openChallenge = () => {
        const courseId = params.courseId as string
        const moduleId = params.moduleId as string
        const contentId = params.contentId as string
        router.push(`/courses/${courseId}/learn/content/modules/${moduleId}/contents/${contentId}/challenges/${challenge.id}`)
    }

    return (
        // each challenge is its OWN distinct card (surface fill + border on a plain div so
        // the utilities aren't overridden by HeroUI Card's unlayered styles). The card itself
        // is static (NOT clickable, no hover/cursor) — only the footer "Do" button navigates.
        // Completed rows are de-emphasized.
        <div className={cn("rounded-3xl border border-default bg-surface p-4", status === "completed" && "opacity-80")}>
            <div className="flex flex-col gap-3">
                <div>
                    <div className="flex items-center justify-between gap-2 mb-2">
                        {/* quiet eyebrow — the challenge number is a low-key label, not a heading;
                            the title below is the meaningful line. No motif icon (it lives once on
                            the section's LabeledCard label). */}
                        <span className="text-xs text-muted">
                            {t("challenge.number", { index: challenge.sortIndex })}
                        </span>
                        <span className={cn("inline-flex items-center gap-2 text-xs", statusMeta.className)}>
                            <StatusIcon className="size-4 shrink-0" />
                            {t(statusMeta.labelKey)}
                        </span>
                    </div>
                    <div className="font-medium">{challenge.title}</div>
                </div>
                <div className="flex items-center gap-2 flex-wrap">
                    {/* the difficulty ramp lives in ONE place (`DifficultyChip`); this row used to
                        tint a generic chip from a second, raw-Tailwind palette of its own */}
                    <DifficultyChip
                        difficulty={toDifficulty(challenge.difficulty)}
                        label={t(DIFFICULTY_LABEL_KEY[challenge.difficulty] ?? "challenge.difficulty.easy")}
                    />
                    <span className="inline-flex items-center gap-1 text-xs text-muted">
                        <TrophyIcon className="size-4 shrink-0" />
                        {challenge.score}
                    </span>
                    {challenge.hint ? (
                        <span className="inline-flex items-center gap-1 text-xs text-muted">
                            <LightbulbIcon className="size-4 shrink-0" />
                            {t("challenge.hintTag")}
                        </span>
                    ) : null}
                </div>
                {challenge.description ? (
                    <MarkdownContent
                        markdown={challenge.description}
                        className="text-xs text-muted [&_p]:m-0 [&_p]:line-clamp-2"
                    />
                ) : null}
                <div className="flex items-center justify-between gap-2">
                    <span className="inline-flex items-center gap-2 text-xs text-muted">
                        <ArrowClockwiseIcon className="size-4 shrink-0" />
                        {attemptsLine}
                    </span>
                    <Button onPress={openChallenge}>
                        <CtaIcon className="size-5" />
                        {t(ctaMeta.labelKey)}
                    </Button>
                </div>
            </div>
        </div>
    )
}

"use client"

import React, { useMemo } from "react"
import { Pagination } from "@heroui/react"
import { useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { ChallengeCard } from "./ChallengeCard"
import { ChallengeCardSkeleton } from "./ChallengeCardSkeleton"
import _ from "lodash"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { WithClassNames } from "@/modules/types/base/class-name"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { UpNextCard } from "@/components/blocks/learn/UpNextCard"
import { useQueryChallengesSwr } from "@/hooks/swr/api/graphql/queries/useQueryChallengesSwr"
import { setChallengePageNumber } from "@/redux/slices/challenge"
import { useLessonNavigation } from "../hooks/useLessonNavigation"

/** Props for {@link ChallengeBody}. */
export type ChallengeBodyProps = WithClassNames<undefined>

/** Content tab body listing the lesson's challenges, paginated. */
export const ChallengeBody = () => {
    const t = useTranslations()
    const router = useRouter()
    const dispatch = useAppDispatch()
    const queryChallengesSwr = useQueryChallengesSwr()
    const challenges = useAppSelector((state) => state.challenge.entities)
    const count = useAppSelector((state) => state.challenge.count)
    // completion handoff: when the learner has PASSED every challenge of THIS lesson,
    // the natural next rung is the NEXT lesson (within the learn-content track).
    const completionTasks = useAppSelector((state) => state.challenge.completionTasks)
    const content = useAppSelector((state) => state.content.entity)
    const { next } = useLessonNavigation()
    const allChallengesPassed = useMemo(
        () => {
            const contentChallenges = content?.challenges ?? []
            return contentChallenges.length > 0
                && contentChallenges.every(
                    (challenge) => completionTasks.find((task) => task.id === challenge.id)?.completed === true,
                )
        },
        [content?.challenges, completionTasks],
    )
    const limit = useAppSelector((state) => state.challenge.limit)
    const pageNumber = useAppSelector((state) => state.challenge.pageNumber)
    // gate on first-load only (NOT isValidating) — a background revalidate on page
    // change keeps the current cards on screen instead of flashing the skeleton
    const isLoading = queryChallengesSwr.isLoading
    // surface fetch failures (e.g. the FE↔BE schema drift that broke this tab) as a
    // distinct error+retry state instead of an indistinguishable "no challenges" empty
    const error = queryChallengesSwr.error
    const isEmpty = !isLoading && !error && !challenges?.length
    const pageSize = limit ?? 10
    const totalPages = useMemo(() => {
        if (count == null || count <= 0) {
            return 0
        }
        return Math.max(1, Math.ceil(count / pageSize))
    }, [count, pageSize])
    const pageNumbers = useMemo(
        () => Array.from({ length: totalPages }, (_, index) => index + 1),
        [totalPages],
    )
    const currentPage = pageNumber ?? 1
    // frameless ONLY once real cards render (each ChallengeCard self-frames); while
    // loading/empty/erroring there is no bounded surface, so LabeledCard's own Card
    // must frame it — otherwise the section's label would also disappear along with
    // the frame (AsyncContent used to sit OUTSIDE LabeledCard entirely).
    const hasChallenges = !isLoading && !error && !isEmpty

    return (
        <LabeledCard
            identity={{ tier: "block", component: "ChallengeBody" }}
            label={t("challenge.count", { count: count ?? 0 })}
            frameless={hasChallenges}

        >
            <AsyncContent
                isLoading={isLoading}
                skeleton={(
                    <div className="flex flex-col gap-3">
                        <ChallengeCardSkeleton />
                        <ChallengeCardSkeleton />
                    </div>
                )}
                isEmpty={isEmpty}
                emptyContent={{ title: t("challenge.empty") }}
                error={error}
                errorContent={{
                    title: t("challenge.errorTitle"),
                    description: t("challenge.errorDescription"),
                    onRetry: () => queryChallengesSwr.mutate(),
                    retryLabel: t("challenge.retry"),
                }}
            >
                <div className="flex flex-col gap-6">
                    <div className="flex flex-col gap-3">
                        {
                            _.cloneDeep(challenges)
                                ?.sort((prev, next) => prev.sortIndex - next.sortIndex)
                                .map((challenge) => <ChallengeCard key={challenge.id} challenge={challenge} />)
                        }
                    </div>
                    {count ? (
                        <Pagination
                            aria-label={t("common.pagination.navAria")}
                            className="justify-start"
                            size="sm"
                        >
                            <Pagination.Content className="flex flex-wrap justify-start gap-1">
                                <Pagination.Item>
                                    <Pagination.Previous
                                        aria-label={t("common.pagination.previous")}
                                        isDisabled={currentPage <= 1}
                                        onPress={() => dispatch(setChallengePageNumber(currentPage - 1))}
                                        className="cursor-pointer rounded-medium transition-colors hover:bg-default"
                                    >
                                        <Pagination.PreviousIcon />
                                    </Pagination.Previous>
                                </Pagination.Item>
                                {pageNumbers.map((pageNumber) => (
                                    <Pagination.Item key={pageNumber}>
                                        <Pagination.Link
                                            isActive={pageNumber === currentPage}
                                            onPress={() => dispatch(setChallengePageNumber(pageNumber))}
                                            className="cursor-pointer rounded-medium transition-colors hover:bg-default data-[active=true]:hover:bg-accent"
                                        >
                                            {pageNumber}
                                        </Pagination.Link>
                                    </Pagination.Item>
                                ))}
                                <Pagination.Item>
                                    <Pagination.Next
                                        aria-label={t("common.pagination.next")}
                                        isDisabled={currentPage >= totalPages}
                                        onPress={() => dispatch(setChallengePageNumber(currentPage + 1))}
                                        className="cursor-pointer rounded-medium transition-colors hover:bg-default"
                                    >
                                        <Pagination.NextIcon />
                                    </Pagination.Next>
                                </Pagination.Item>
                            </Pagination.Content>
                        </Pagination>
                    ) : null}
                    {/* passed every challenge of this lesson → hand off to the next lesson */}
                    {allChallengesPassed && next ? (
                        <UpNextCard
                            showCheck
                            eyebrow={t("content.upNext.challengesDoneEyebrow")}
                            title={t("content.upNext.nextLessonTitle", { title: next.title })}
                            description={t("content.upNext.nextLessonDesc")}
                            ctaLabel={t("content.upNext.nextLessonCta")}
                            onPress={() => router.push(next.href)}
                        />
                    ) : null}
                </div>
            </AsyncContent>
        </LabeledCard>
    )
}

"use client"

import React from "react"
import { cn } from "@heroui/react"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SkeletonText } from "@/components/blocks/skeleton/SkeletonText"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link CodeBodySkeleton}. */
export interface CodeBodySkeletonProps extends WithClassNames<undefined> {
    /** Number of placeholder code cards to render. Defaults to `2`. */
    count?: number
}

/**
 * Loading placeholder for the code-oriented content tabs (lesson / explaining /
 * implementation). Mirrors the real cards: a chip row, a `rounded-xl` editor
 * block, and a few stepped text lines suggesting an explanation.
 * @param props - {@link CodeBodySkeletonProps}
 */
export const CodeBodySkeleton = ({
    count = 2,
    className,
}: CodeBodySkeletonProps) => {
    return (
        <div className={cn("flex flex-col gap-6", className)}>
            {Array.from({ length: Math.max(count, 1) }).map((_unused, index) => (
                <article
                    key={index}
                    className="rounded-xl border border-default-200 p-4 flex flex-col gap-3"
                >
                    {/* chip row (index + language chips) */}
                    <div className="flex items-center gap-2">
                        <Skeleton className="h-6 w-16 rounded-full" />
                        <Skeleton className="h-6 w-12 rounded-full" />
                    </div>
                    {/* the code editor block */}
                    <Skeleton className="h-40 w-full rounded-xl" />
                    {/* a few explanation lines of varying width */}
