import { ClockIcon, FlameIcon } from "@phosphor-icons/react"
import _ from "lodash"
import React, {
    useMemo,
} from "react"
import {
    Chip,
    Typography,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    ReadBadge,
} from "../ReadBadge"
import { CheckListCard, CheckListItem } from "@/components/blocks/cards/CheckListCard"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import type { ResponsiveBreadcrumbItem } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { useAppSelector } from "@/redux/hooks"
import { getContentChallengeCount } from "@/modules/types/entities/content"
import { pathConfig } from "@/resources/path"

/**
 * Title, description and meta-chip row (reading time, challenges, read state)
 * for the loaded content view.
 *
 * Self-contained section (single-use): reads the content entity + read state
 * from redux; the container renders `<ContentHeader />` with no props.
 */
export const ContentHeader = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const content = useAppSelector((state) => state.content.entity)
    const course = useAppSelector((state) => state.course.entity)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    const title = content?.title
    const description = content?.description
    const minutesRead = content?.minutesRead ?? 0

    /** Tier-1 breadcrumb (Home › Courses › <course> › Module) — lives in the PageHeader
     *  breadcrumb slot so the whole header is one unit (moved out of the route layout). */
    const breadcrumbItems = useMemo<Array<ResponsiveBreadcrumbItem>>(() => [
        { key: "home", label: t("nav.home"), onPress: () => router.push(pathConfig().locale().build()) },
        { key: "courses", label: t("nav.courses"), onPress: () => router.push(pathConfig().locale(locale).course().build()) },
        { key: "course", label: course?.title || t("nav.courses"), onPress: () => router.push(pathConfig().locale(locale).course(courseDisplayId).build()) },
        { key: "modules", label: t("modules.title"), onPress: () => router.push(pathConfig().locale(locale).course(courseDisplayId).learn().content().build()) },
    ], [t, locale, router, course?.title, courseDisplayId])

    /** Challenge count for the meta chip, tolerant of a missing entity. */
    const challengeCount = useMemo(
        () => getContentChallengeCount(content ?? {}),
        [content],
    )

    /** "What you'll learn" bullets, ordered (mount `# outcomes`); empty → callout hidden. */
    const outcomes = useMemo(
        () => _.sortBy(content?.outcomes ?? [], (outcome) => outcome.sortIndex),
        [content],
    )

    return (
        // header proper (title+desc+meta) → outcomes = header → content boundary = gap-10 (page-heading debt)
        <div className="flex flex-col gap-10">
            {/* header (tier 1/2) via the shared PageHeader block for cross-page consistency:
                title (H3) + description + a quiet meta-chip row (read state · time · challenges). */}
            <PageHeader
                breadcrumb={<ResponsiveBreadcrumb items={breadcrumbItems} />}
                title={title}
                description={description || undefined}
                meta={(
                    <div className="flex flex-wrap items-center gap-2">
                        <ReadBadge />
                        <Chip color="default">
                            <ClockIcon className="size-4" />
                            <Chip.Label>
                                {t("content.minutesRead", { minutes: minutesRead })}
                            </Chip.Label>
                        </Chip>
                        <Typography type="body-xs" color="muted" className="flex items-center gap-1">
                            <FlameIcon className="size-4" />
                            {t("content.challengeCount", { count: challengeCount })}
                        </Typography>
                    </div>
                )}
            />
            {/* "What you'll learn" — first CONTENT block, gap-10 below the header above */}
            {outcomes.length > 0 ? (
                <LabeledCard frameless label={t("content.outcomes")}>
                    {/* shared check-list card (same as course value-props / challenge outputs) */}
                    <CheckListCard>
                        {outcomes.map((outcome) => (
                            <CheckListItem key={outcome.id}>
                                <Typography type="body-sm">{outcome.text}</Typography>
                            </CheckListItem>
                        ))}
                    </CheckListCard>
                </LabeledCard>
            ) : null}
        </div>
    )
}

"use client"

import React, { useMemo, useState } from "react"
import { Accordion } from "@heroui/react"
import { useTranslations } from "next-intl"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { StatusChip } from "@/components/blocks/chips/StatusChip"
import { useAppSelector } from "@/redux/hooks"
import { ProgrammingLanguageTabs } from "@/components/blocks/navigation/ProgrammingLanguageTabs"
import { ProgrammingLanguageTabsVariant } from "@/components/blocks/navigation/ProgrammingLanguageTabs/enums/programming-language-tabs-variant"

/** One captured E2E flow (shape mirrors the seeded content.e2eFlows jsonb). */
interface E2eFlow {
    id: string
    title: string
    lang?: string
    status: string
    /** Full proof markdown (commands, real output, conclusion) from .e2e/<lang>/flow-*.md. */
    markdown?: string
}

/**
 * E2eBody — the "E2E" tab. Renders each lesson's recorded Playwright proof
 * (`.e2e/<lang>/flow-*.md`) as read-only markdown: per-flow status badge, title
 * and the full proof (commands + real output + conclusion). When flows carry
 * multiple languages (websocket / file-upload run all four stacks) a language
 * filter is shown so learners can read each stack's real run.
 */
export const E2eBody = (): React.JSX.Element => {
    const t = useTranslations()
    const content = useAppSelector((state) => state.content.entity)
    const flows = (content?.e2eFlows as Array<E2eFlow> | null | undefined) ?? []

    const langs = useMemo(() => {
        const set = new Set(flows.map((f) => f.lang ?? "agnostic"))
        return Array.from(set)
    }, [flows])
    const hasLangFilter = langs.length > 1
    const [activeLang, setActiveLang] = useState<string>(langs[0] ?? "agnostic")

    const visible = hasLangFilter
        ? flows.filter((f) => (f.lang ?? "agnostic") === activeLang)
        : flows
    const passed = visible.filter((f) => f.status === "passed").length

    if (flows.length === 0) {
        return (
            <div className="py-10 text-center text-sm text-default-500">
                {t("content.e2e.empty")}
            </div>
        )
    }

    return (
        <div className="mx-auto flex max-w-3xl flex-col gap-6">
            <div className="flex flex-col gap-2">
                <p className="text-sm font-semibold">{t("content.e2e.title")}</p>
                <p className="text-sm text-default-500">
                    {t("content.e2e.passedCount", { passed, total: visible.length })}
                </p>
            </div>

            {hasLangFilter && (
                <ProgrammingLanguageTabs
                    variant={ProgrammingLanguageTabsVariant.Secondary}
                    availableLangs={langs}
                    selectedLang={activeLang}
                    onSelectLang={setActiveLang}
                    ariaLabel={t("content.e2e.languagesAria")}
                    surfaceBorder={false}
                />
            )}

            <Accordion variant="surface">
                {visible.map((flow) => {
                    const ok = flow.status === "passed"
                    return (
                        <Accordion.Item
                            key={`${flow.lang ?? "agnostic"}-${flow.id}`}
                            aria-label={flow.title}
                        >
                            <Accordion.Heading>
                                <Accordion.Trigger>
                                    <span className="flex items-center gap-2 text-start">
                                        <StatusChip tone={ok ? "success" : "danger"}>
                                            {ok ? t("content.e2e.statusPass") : t("content.e2e.statusFail")}
                                        </StatusChip>
                                        <span className="text-sm font-medium">{flow.title}</span>
                                    </span>
                                </Accordion.Trigger>
                            </Accordion.Heading>
                            <Accordion.Panel>
                                <Accordion.Body>
                                    {flow.markdown && <MarkdownContent markdown={flow.markdown} />}
                                </Accordion.Body>
                            </Accordion.Panel>
                        </Accordion.Item>
                    )
                })}
            </Accordion>
        </div>
    )
}

