"use client"

import React, { useMemo } from "react"
import { useTheme } from "next-themes"
import { SandpackPanel } from "@/components/blocks/code/SandpackPanel"
import { CodeBodySkeleton } from "../CodeBodySkeleton"
import type { SandpackFiles } from "@codesandbox/sandpack-react"
import { useAppSelector } from "@/redux/hooks"
import { useQueryContentSwr } from "@/hooks/swr/api/graphql/queries/useQueryContentSwr"
import { useRepoSandpackFiles } from "@/hooks/useRepoSandpackFiles"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"

/**
 * Tailwind v4 theme registered at runtime in the preview iframe. `@tailwindcss/browser`
 * uses the DEFAULT config (no HeroUI colors), and heroui.min.css does not ship
 * `bg-background` / `text-foreground` / `default-*` utilities — so we register them
 * here as a `<style type="text/tailwindcss">`. `@custom-variant dark` makes the
 * `.dark` class drive every token (page bg, text, hover) for both light and dark.
 */
const THEME_TAILWINDCSS = `@custom-variant dark (&:where(.dark, .dark *));
@theme {
  --font-sans: "Inter", ui-sans-serif, system-ui, sans-serif;
  --color-background: var(--sb-bg);
  --color-foreground: var(--sb-fg);
  --color-muted: var(--sb-muted);
  --color-border: var(--sb-border);
  --color-content1: var(--sb-content1);
  --color-default-50: var(--sb-d50);
  --color-default-100: var(--sb-d100);
  --color-default-200: var(--sb-d200);
  --color-default-300: var(--sb-d300);
  --color-default-400: var(--sb-muted);
  --color-default-500: var(--sb-muted);
  --color-default-600: var(--sb-d600);
  --color-default-700: var(--sb-d700);
  --color-accent: var(--sb-accent);
  --color-primary: var(--sb-primary);
  --color-focus: var(--sb-primary);
  --color-danger: var(--sb-danger);
  --color-success: var(--sb-success);
  --color-warning: var(--sb-warning);
}
:root {
  --sb-bg: oklch(97.02% 0.0033 185.90); --sb-fg: #18181b; --sb-muted: #71717a; --sb-border: #e4e4e7;
  --sb-d50: #fafafa; --sb-d100: #f4f4f5; --sb-d200: #e4e4e7; --sb-d300: #d4d4d8; --sb-d600: #52525b; --sb-d700: #3f3f46;
  --sb-content1: #ffffff; --sb-accent: #0d9488; --sb-primary: #006fee; --sb-danger: #f31260; --sb-success: #17c964; --sb-warning: #f5a524;
  /* raw semantic vars (no color- prefix) so the lesson's globals.css var(--border)/var(--background) resolve */
  --background: var(--sb-bg); --foreground: var(--sb-fg); --border: var(--sb-border); --muted: var(--sb-muted);
  --default-100: var(--sb-d100); --default-200: var(--sb-d200); --content1: var(--sb-content1);
}
.dark {
  --sb-bg: oklch(12.00% 0.0033 185.90); --sb-fg: #fafafa; --sb-muted: #a1a1aa; --sb-border: #27272a;
  --sb-d50: oklch(16.00% 0.0033 185.90); --sb-d100: oklch(20.00% 0.0033 185.90); --sb-d200: #3f3f46; --sb-d300: #52525b; --sb-d600: #a1a1aa; --sb-d700: #d4d4d8;
  --sb-content1: oklch(20.00% 0.0033 185.90); --sb-accent: #2dd4bf; --sb-primary: #006fee; --sb-danger: #f31260; --sb-success: #17c964; --sb-warning: #f5a524;
}`

/**
 * Bridges the Sandpack template entry (/App.tsx, imported as ../App) to the real
 * /src/App. Injects the Tailwind theme + toggles the platform light/dark mode on
 * the preview iframe's <html>.
 */
const buildAppBridge = (isDark: boolean, globalsCssImport: string): string => `import { useEffect } from "react"
import App from "./src/App"
${globalsCssImport}

// Force ?sandbox=1 into the URL before App's first render. Sandpack's startRoute
// query does not reliably reach window.location.search inside the preview iframe,
// so multi-client lessons (websocket: chat/presence/reconnection) would otherwise
// fall back to the single-client Local view and lose their User A / User B tabs.
// This runs at module eval — before App's useState reads window.location.search.
if (typeof window !== "undefined" && !new URLSearchParams(window.location.search).has("sandbox")) {
    window.history.replaceState(null, "", window.location.pathname + "?sandbox=1" + window.location.hash)
}

export default function SandboxRoot() {
    useEffect(() => {
        document.documentElement.classList.toggle("dark", ${isDark})
        // load Inter (the font heroui.com uses) so the preview matches the docs
        if (!document.getElementById("sb-font")) {
            const link = document.createElement("link")
            link.id = "sb-font"
            link.rel = "stylesheet"
            link.href = "https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap"
            document.head.appendChild(link)
        }
        if (!document.getElementById("sb-theme")) {
            const style = document.createElement("style")
            style.id = "sb-theme"
            style.setAttribute("type", "text/tailwindcss")
            style.textContent = ${JSON.stringify(THEME_TAILWINDCSS)}
            document.head.appendChild(style)
        }
    }, [])
    return <App />
}
`

/**
 * Rewrites a lesson source file so it runs inside Sandpack's bundler:
 *  - `import.meta.env.VITE_API_BASE` → the session-scoped mock URL literal
 *  - any other `import.meta.env.X` → "" (bundler can't evaluate import.meta)
 *  - `import.meta.hot...` → undefined (HMR not available)
 *  - strips Tailwind/HeroUI @import directives (loaded via CDN instead)
 */
const rewriteForSandpack = (code: string, mockApiBase: string): string =>
    code
        .replace(/import\.meta\.env\.VITE_API_BASE/g, JSON.stringify(mockApiBase))
        .replace(/import\.meta\.env\.\w+/g, "\"\"")
        .replace(/import\.meta\.env/g, "({})")
        .replace(/import\.meta\.hot[^\n]*/g, "undefined")
        .replace(/@import\s+["']tailwindcss["'];?/g, "")
        .replace(/@import\s+["']@heroui\/styles["'];?/g, "")

/**
 * Sandbox tab body — runs the lesson's frontend live in Sandpack against a
 * session-isolated mock API served by the standalone mock app. Always light
 * theme (dark mode is intentionally ignored here).
 *
 * Flow:
 * 1. A random sessionId is generated client-side (the mock app lazily seeds on
 *    first request — no handshake needed).
 * 2. The lesson source is fetched from GitHub (cached by repo URL).
 * 3. Every file's `import.meta.env.VITE_API_BASE` is overridden to the mock URL
 *    `<mockHost>/mocks/<module>/<lesson>/sessions/<sessionId>` — the cloned source
 *    still falls back to `http://localhost:3000` for local dev.
 */
export const SandboxBody = () => {
    const queryContentSwr = useQueryContentSwr()
    const content = useAppSelector((state) => state.content.entity)
    // editor chrome follows the platform theme; the preview app stays light
    const { resolvedTheme } = useTheme()
    const isDark = resolvedTheme !== "light"

    // host of the standalone mock app (e.g. http://localhost:3002 — no /api prefix)
    const mockApiHost = process.env.NEXT_PUBLIC_MOCK_API_BASE_URL ?? ""
    // lesson path on that host (e.g. /mocks/4-server-state.../0-usequery...)
    const lessonPath = content?.backendUrl ?? null

    // fresh isolated session id, stable for this lesson's component lifetime
    const sessionId = useMemo(
        () => (typeof crypto !== "undefined" ? crypto.randomUUID() : `${Date.now()}`),
        [content?.id],
    )

    const { files: githubFiles, dependencies, isLoading: githubLoading } = useRepoSandpackFiles(
        content?.id,
        content?.githubBaseUrl,
        content?.githubDir,
        content?.isPremium,
    )

    const contentReady = !queryContentSwr.isLoading && !!queryContentSwr.data && !queryContentSwr.error
    // first load (content + repo files) → mirror the code-shaped skeleton via AsyncContent
    const isLoading = !contentReady || githubLoading

    // full session-scoped mock URL the lesson's VITE_API_BASE will point at
    const mockApiBase = lessonPath
        ? `${mockApiHost}${lessonPath}/sessions/${sessionId}`
        : ""

    // rewrite every fetched file's env reference to the live mock URL
    const rewrittenFiles: SandpackFiles = {}
    for (const [path, file] of Object.entries(githubFiles ?? {})) {
        const code = typeof file === "string" ? file : file.code
        rewrittenFiles[path] = { code: rewriteForSandpack(code, mockApiBase) }
    }

    // synthetic stubs: bridge the template entry (+ theme sync) and no-op the
    // vite config the bundler can't run. Tailwind v4 + HeroUI load via
    // SandpackProvider externalResources (not index.html — Sandpack ignores tags there).
    // The bridge imports App directly (bypassing main.tsx), so the lesson's
    // globals.css — normally imported by main.tsx — would never load, dropping
    // its body reset and custom rules (e.g. the `.input` border). Re-import it
    // from the bridge when present (path-safe: only if the lesson ships one).
    const globalsKey = Object.keys(rewrittenFiles).find((p) => p.endsWith("/globals.css"))
    const globalsCssImport = globalsKey ? `import ".${globalsKey}"` : ""

    const stubs: SandpackFiles = {
        "/App.tsx": { code: buildAppBridge(isDark, globalsCssImport) },
        "/vite.config.ts": { code: "// vite config omitted in sandbox" },
    }

    const files: SandpackFiles = { ...stubs, ...rewrittenFiles }

    // thin, rounded, theme-aware scrollbars for the editor/file-tree (default ones look crude)
    const thumb = isDark ? "rgba(255,255,255,0.16)" : "rgba(0,0,0,0.16)"
    const thumbHover = isDark ? "rgba(255,255,255,0.28)" : "rgba(0,0,0,0.28)"

    const body = (
        <div className="sb-scroll mt-3">
            <style>{`
                .sb-scroll *::-webkit-scrollbar { width: 8px; height: 8px; }
                .sb-scroll *::-webkit-scrollbar-track { background: transparent; }
                .sb-scroll *::-webkit-scrollbar-thumb { background: ${thumb}; border-radius: 9999px; border: 2px solid transparent; background-clip: content-box; }
                .sb-scroll *::-webkit-scrollbar-thumb:hover { background: ${thumbHover}; background-clip: content-box; }
                .sb-scroll *::-webkit-scrollbar-corner { background: transparent; }
                .sb-scroll * { scrollbar-width: thin; scrollbar-color: ${thumb} transparent; }
            `}</style>
            {/* key on theme forces a full re-mount (fresh preview iframe) when the
                platform light/dark toggles, so the bridge re-runs and the sandbox UI
                reloads with the new theme instead of keeping the stale dark class. */}
            <SandpackPanel
                key={isDark ? "sandbox-dark" : "sandbox-light"}
                files={files}
                dependencies={dependencies}
                isDark={isDark}
            />
        </div>
    )

    return (
        <AsyncContent
            isLoading={isLoading}
            skeleton={<CodeBodySkeleton />}
        >
            {body}
        </AsyncContent>
    )
}

"use client"

import {
    useMemo,
} from "react"
import {
    useLocale,
} from "next-intl"
import {
    pathConfig,
} from "@/resources/path"
import { useAppSelector } from "@/redux/hooks"
import { useQueryMyCourseOutlineSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCourseOutlineSwr"

/** A neighbouring lesson in the linear course order. */
export interface AdjacentLesson {
    /** In-app route to the lesson's reader. */
    href: string
    /** Lesson title shown on the pager card. */
    title: string
}

/** Result of {@link useLessonNavigation}. */
export interface UseLessonNavigationResult {
    /** 1-based position of the active lesson in the flattened course order (0 when unknown). */
    position: number
    /** Total number of lessons across the course. */
    total: number
    /** The previous lesson, or undefined at the start / when unknown. */
    previous?: AdjacentLesson
    /** The next lesson, or undefined at the end / when unknown. */
    next?: AdjacentLesson
    /**
     * Whether the underlying outline is still resolving — lets callers (the
     * pager) tell "still finding out" apart from "genuinely no neighbour"
     * instead of collapsing both into an empty `previous`/`next`.
     */
    isLoading: boolean
}

/**
 * Linear lesson navigation for the reader: flattens the course outline
 * (`myCourseOutline` modules → lessons, in order), locates the active lesson, and
 * exposes its 1-based position + the previous / next lesson with ready routes.
 *
 * Reads the active course id + lesson id from Redux; the outline SWR is shared
 * (deduped) with the content-map rail. Returns zeros / undefined neighbours while
 * the outline is loading or the lesson is not part of it.
 *
 * @returns {@link UseLessonNavigationResult} position, total, and the neighbours.
 */
export const useLessonNavigation = (): UseLessonNavigationResult => {
    const locale = useLocale()
    const courseId = useAppSelector((state) => state.course.id)
    const displayId = useAppSelector((state) => state.course.displayId)
    const contentId = useAppSelector((state) => state.content.id)
    const outlineSwr = useQueryMyCourseOutlineSwr(courseId ?? null)
    const outline = outlineSwr.data

    return useMemo<UseLessonNavigationResult>(() => {
        if (!outline || !displayId) {
            return { position: 0, total: 0, isLoading: outlineSwr.isLoading }
        }
        // flatten modules → lessons into the linear reading order, keeping the
        // owning module id so each lesson route can be rebuilt
        const sequence = outline.modules.flatMap((module) =>
            module.lessons.map((lesson) => ({
                moduleId: module.id,
                contentId: lesson.id,
                title: lesson.title,
            })))
        const total = sequence.length
        const index = sequence.findIndex((entry) => entry.contentId === contentId)
        if (index === -1) {
            return { position: 0, total, isLoading: outlineSwr.isLoading }
        }

        const toLesson = (entry: typeof sequence[number]): AdjacentLesson => ({
            href: pathConfig().locale(locale).course(displayId).learn()
                .module(entry.moduleId).content(entry.contentId).build(),
            title: entry.title,
        })

        return {
            position: index + 1,
            total,
            previous: index > 0 ? toLesson(sequence[index - 1]) : undefined,
            next: index < total - 1 ? toLesson(sequence[index + 1]) : undefined,
            isLoading: outlineSwr.isLoading,
        }
    }, [outline, displayId, locale, contentId, outlineSwr.isLoading])
}

import type { ComponentType } from "react"
import type { ContentTab } from "@/redux/slices/tabs"

/**
 * One entry in the {@link ContentPage} tab bar: which redux {@link ContentTab} it
 * maps to, the i18n label shown on the trigger, and the body rendered when the
 * tab is active.
 */
export interface ContentTabItem {
    /** Redux tab key this entry selects. */
    key: ContentTab
    /** Translated label rendered on the tab trigger. */
    label: string
    /**
     * The tab's own body — an UNCALLED component (never a built element), so a tab
     * that is not selected is never constructed just to be thrown away.
     */
    body: ComponentType
    /**
     * When true the tab is a locked premium feature: rendered muted and, on
     * click, opens the register modal instead of switching to its body.
     */
    locked?: boolean
}

"use client"

import React, { useState } from "react"
import { Button, FieldError, Input, Label, Spinner, Tabs, TextField, Typography } from "@heroui/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { AutosaveStatus } from "../PersonalProjectSubmission"
import { GradeModelDropdown } from "@/components/blocks/grading/GradeModelDropdown"
import { AiModelCategory, AiModelTask } from "@/modules/api/graphql/queries/query-ai-models"
import { usePersonalProjectGithubForm } from "@/hooks/zustand/personalProjectGithub/usePersonalProjectGithubForm"

/** Props for {@link GithubGradingSettings}. */
export type GithubGradingSettingsProps = Record<string, never>
/**
 * Set-once grading config for the personal project — rendered inside the panel's settings Drawer
 * (progressive disclosure): the grading language, the branch to evaluate, and the optional
 * private-repo token. Reads the SHARED store but does NOT enable sync — the panel's
 * {@link import("../PersonalProjectSubmission").PersonalProjectSubmission} owns the debounced
 * url/branch sync, so the autosave status shown here comes from the same store.
 * @param props - {@link GithubGradingSettingsProps}
 */
export const GithubGradingSettings = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const {
        branch,
        lang,
        errors,
        touched,
        autosaveStatus,
        gradeModels,
        gradeSelection,
        canPremium,
        setGradeSelection,
        setBranch,
        setLang,
        setTouchedBranch,
        setBranchError,
        saveGithubToken,
        clearGithubToken,
        tokenSaveStatus,
    } = usePersonalProjectGithubForm()
    /** Local write-only buffer for the private-repo token (never prefilled). */
    const [tokenInput, setTokenInput] = useState("")
    const isSavingToken = tokenSaveStatus === "saving"
    /** Languages the submission can be graded against (V2 per-language approach criteria). */
    const langOptions = [
        { id: "typescript", label: t("programmingLanguage.typescript") },
        { id: "java", label: t("programmingLanguage.java") },
        { id: "csharp", label: t("programmingLanguage.csharp") },
        { id: "go", label: t("programmingLanguage.go") },
    ]
    const branchInvalid = Boolean(touched.branch && errors.branch)

    return (
        <div className={"flex flex-col gap-6"}>
            <div className="flex flex-col gap-2">
                <Label>{t("finalProject.page.submitGithub.langFieldTitle")}</Label>
                <Tabs
                    selectedKey={lang}
                    variant="primary"
                    className="w-fit"
                    onSelectionChange={(key) => setLang(String(key))}
                >
                    <Tabs.ListContainer>
                        <Tabs.List aria-label={t("finalProject.page.submitGithub.langFieldTitle")}>
                            {langOptions.map((option) => (
                                <Tabs.Tab key={option.id} id={option.id}>
                                    {option.label}
                                    <Tabs.Indicator />
                                </Tabs.Tab>
                            ))}
                        </Tabs.List>
                    </Tabs.ListContainer>
                </Tabs>
                <Typography type="body-sm" color="muted">
                    {t("finalProject.page.submitGithub.langFieldHint")}
                </Typography>
            </div>
            <div className="flex flex-col gap-2">
                <Label>{t("finalProject.page.submitGithub.modelFieldTitle")}</Label>
                <GradeModelDropdown
                    models={gradeModels}
                    selection={gradeSelection}
                    canPremium={canPremium}
                    showAutoLane={false}
                    floor={AiModelCategory.Low}
                    task={AiModelTask.TaskGrading}
                    onSelect={setGradeSelection}
                    onUpgrade={() => router.push(`/${locale}/profile/settings/ai-subscription`)}
                />
                <Typography type="body-sm" color="muted">
                    {t("finalProject.page.submitGithub.modelFieldHint")}
                </Typography>
            </div>
            <div className="flex flex-col gap-2">
                <Label>{t("finalProject.page.submitGithub.branchFieldTitle")}</Label>
                <TextField variant="secondary" isInvalid={branchInvalid} className="w-full">
                    <Input
                        className="w-full"
                        placeholder={t("finalProject.page.submitGithub.branchPlaceholder")}
                        name="branch"
                        value={branch}
                        onChange={(event) => setBranch(event.target.value)}
                        onBlur={() => setTouchedBranch(true)}
                    />
                    <FieldError>{errors.branch}</FieldError>
                </TextField>
                {/* autosave status + reset on ONE row so the button sits right under the field */}
                <div className="flex items-center justify-between gap-2">
                    <AutosaveStatus status={autosaveStatus.branch} />
                    <Button
                        variant="secondary"
                        size="sm"
                        isDisabled={autosaveStatus.branch === "saving"}
                        onPress={() => {
                            setBranch("main")
                            setBranchError(null)
                        }}
                    >
                        {t("finalProject.page.submitGithub.resetButton")}
                    </Button>
                </div>
            </div>
            {/* private repo (optional): a write-only GitHub token, encrypted server-side. Only needed
                when the repo is private — public repos grade with the org token. */}
            <div className="flex flex-col gap-2">
                <Label>{t("finalProject.page.submitGithub.privateTokenFieldTitle")}</Label>
                <TextField variant="secondary" className="w-full">
                    <Input
                        className="w-full"
                        type="password"
                        autoComplete="off"
                        placeholder={t("finalProject.page.submitGithub.privateTokenPlaceholder")}
                        name="githubToken"
                        value={tokenInput}
                        onChange={(event) => setTokenInput(event.target.value)}
                    />
                </TextField>
                <Typography type="body-sm" color="muted">
                    {t("finalProject.page.submitGithub.privateTokenHint")}
                </Typography>
                <div className="flex flex-wrap items-center gap-2">
                    <Button
                        variant="secondary"
                        isPending={isSavingToken}
                        isDisabled={isSavingToken || tokenInput.trim().length === 0}
                        onPress={() => {
                            void saveGithubToken(tokenInput).then(() => setTokenInput(""))
                        }}
                    >
                        {({ isPending }) => (
                            <>
                                {isPending ? <Spinner size="sm" color="current" /> : null}
                                {t("finalProject.page.submitGithub.privateTokenSaveButton")}
                            </>
                        )}
                    </Button>
                    <Button
                        variant="tertiary"
                        isDisabled={isSavingToken}
                        onPress={() => {
                            void clearGithubToken().then(() => setTokenInput(""))
                        }}
                    >
                        {t("finalProject.page.submitGithub.privateTokenRemoveButton")}
                    </Button>
                </div>
            </div>
        </div>
    )
}

"use client"

import React, { useCallback, useMemo } from "react"
import { Chip, Typography } from "@heroui/react"
import {
    PlayIcon,
} from "@phosphor-icons/react"
import { GithubIcon } from "@/components/svg/GithubIcon"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import {
    buildMilestoneTaskProgressLookup,
    isPersonalProjectTaskActionUnlocked,
} from "@/components/utils/task-lookup"
import { PersonalProjectDashboardSkeleton } from "./PersonalProjectDashboardSkeleton"
import { TaskBreadcrumb } from "../TaskBreadcrumb"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { setSelectedTaskId } from "@/redux/slices/milestone"
import { useQueryMilestonesSwr } from "@/hooks/swr/api/graphql/queries/useQueryMilestonesSwr"
import { useQueryMilestoneTaskProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryMilestoneTaskProgressSwr"
import { pathConfig } from "@/resources/path"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { ContinueCard } from "@/components/blocks/cards/ContinueCard"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { Grid } from "@/components/frames/Grid"
import type { MilestoneEntity } from "@/modules/types/entities/milestone"

/** Props for {@link PersonalProjectDashboard}. */
export type PersonalProjectDashboardProps = Record<string, never>
/** github.com URL → `owner/repo` (drops scheme + trailing .git) for a compact label. */
const toRepoLabel = (url: string): string =>
    url
        .trim()
        .replace(/^https?:\/\/(www\.)?github\.com\//i, "")
        .replace(/\.git$/i, "")
        .replace(/\/$/, "")

/**
 * Personal-project landing DASHBOARD — shown by {@link
 * import("../PersonalProjectWorkspace").PersonalProjectWorkspace} when the URL has
 * no `tasks/[id]` (overview instead of an empty column).
 *
 * Mirrors the course-content home (`CourseContents`) layout so the two learn home
 * surfaces read consistently: TIER-1 breadcrumb → TIER-2 header (project title +
 * description + a GitHub status chip) → TIER-3 a {@link ContinueCard} `hero` for
 * the next task (chip "Continue") + progress meter, above the keep-going path =
 * current milestone tasks as {@link ContinueCard} `item` cards (with per-card
 * "Continue >" CTA) in a frameless {@link LabeledCard} grid. The milestone LIST
 * for the whole project lives in the left rail — the body only surfaces "where
 * you are + what's next". Every value is grounded in real BE fields
 * (`milestoneTaskProgress`, enrollment github).
 *
 * @param props - {@link PersonalProjectDashboardProps}
 */
export const PersonalProjectDashboard = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const dispatch = useAppDispatch()
    const milestonesSwr = useQueryMilestonesSwr()
    const progressSwr = useQueryMilestoneTaskProgressSwr()
    const milestoneEntities = useAppSelector((state) => state.milestone.entities)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)
    // github connection truth lives on the enrollment (the github store is only seeded inside
    // the task panel, which isn't mounted on the dashboard) — read it straight from redux
    const enrollment = useAppSelector((state) => state.user.enrollment)
    const githubUrl = enrollment?.personalProjectGithubUrl ?? ""
    const githubBranch = enrollment?.personalProjectGithubBranch ?? ""

    const milestones = useMemo(
        () => [...milestoneEntities].sort((prev, next) => prev.sortIndex - next.sortIndex),
        [milestoneEntities],
    )
    const completionTasks = progressSwr.data?.milestoneTaskProgress?.data?.completionTasks
    const progressMap = useMemo(
        () => buildMilestoneTaskProgressLookup(completionTasks),
        [completionTasks],
    )
    const currentTaskId = progressSwr.data?.milestoneTaskProgress?.data?.currentTask?.id

    /** The next task to work on, plus the milestone that owns it (for the continue block). */
    const currentTask = useMemo(() => {
        if (!currentTaskId) {
            return undefined
        }
        for (const milestone of milestones) {
            const task = (milestone.tasks ?? []).find((entity) => entity.id === currentTaskId)
            if (task) {
                return task
            }
        }
        return undefined
    }, [milestones, currentTaskId])

    /** The milestone the learner is in: the one owning the next task, else the first. */
    const currentMilestone = useMemo<MilestoneEntity | undefined>(() => {
        if (currentTaskId) {
            const owning = milestones.find((milestone) =>
                (milestone.tasks ?? []).some((task) => task.id === currentTaskId))
            if (owning) {
                return owning
            }
        }
        return milestones[0]
    }, [milestones, currentTaskId])

    /** Aggregate KPIs across every task in the course (grounded in the progress lookup). */
    const stats = useMemo(() => {
        // total comes from the full milestone tree (every task counts)
        let total = 0
        for (const milestone of milestones) {
            total += (milestone.tasks ?? []).length
        }
        // done / attempts / avg score come from the progress rows (carry lastScore/maxScore)
        let done = 0
        let attempts = 0
        let scoreSum = 0
        let maxSum = 0
        let scored = 0
        for (const item of completionTasks ?? []) {
            attempts += item.numAttempts ?? 0
            if (item.completed) {
                done += 1
                if (typeof item.lastScore === "number") {
                    scoreSum += item.lastScore
                    maxSum += item.maxScore ?? 20
                    scored += 1
                }
            }
        }
        return {
            done,
            total,
            attempts,
            avgScore: scored > 0 ? Math.round(scoreSum / scored) : null,
            avgMax: scored > 0 ? Math.round(maxSum / scored) : 20,
        }
    }, [milestones, completionTasks])

    const isConnected = githubUrl.trim().length > 0
    const avgLabel = stats.avgScore != null ? `${stats.avgScore}/${stats.avgMax}` : "—"

    /** Jump into the next task (or the very first one): mirror the rail's select+route. */
    const onContinue = useCallback(() => {
        const taskId = currentTaskId ?? milestones[0]?.tasks?.[0]?.id
        if (!taskId) {
            return
        }
        dispatch(setSelectedTaskId(taskId))
        router.push(
            pathConfig().locale(locale).course(courseDisplayId).learn().personalProject(taskId).build(),
        )
    }, [currentTaskId, milestones, dispatch, router, locale, courseDisplayId])

    /** Open a task from the keep-going path (the locked brief handles its own gate). */
    const onSelectTask = useCallback(
        (taskId: string) => {
            dispatch(setSelectedTaskId(taskId))
            router.push(
                pathConfig().locale(locale).course(courseDisplayId).learn().personalProject(taskId).build(),
            )
        },
        [dispatch, router, locale, courseDisplayId],
    )

    // gate on first load only (cached redux milestones win); brief skeleton while progress lands
    const hasMilestones = milestones.length > 0
    const isLoading = (!hasMilestones && !milestonesSwr.error && (milestonesSwr.isLoading || !milestonesSwr.data))
        || (progressSwr.isLoading && !progressSwr.data)
    const isEmpty = !hasMilestones && !milestonesSwr.isLoading && !!milestonesSwr.data && !milestonesSwr.error

    return (
        <div className={"mx-auto flex w-full max-w-3xl flex-col gap-10"}>
            {/* shared PageHeader: breadcrumb → H3 title → muted desc → github status chip (meta).
                header → content = gap-10 (page-heading debt). */}
            <PageHeader
                breadcrumb={<TaskBreadcrumb />}
                title={t("finalProject.dashboard.title")}
                description={t("finalProject.dashboard.subtitle")}
                meta={(
                    <div className="flex flex-wrap items-center gap-2">
                        <Chip
                            color={isConnected ? "success" : "default"}
                            className={isConnected ? "bg-success-soft text-success-soft-foreground" : undefined}
                        >
                            <GithubIcon className="size-5" />
                            <Chip.Label>
                                {isConnected
                                    ? `${toRepoLabel(githubUrl)} · ${githubBranch || "main"}`
                                    : t("finalProject.dashboard.notConnected")}
                            </Chip.Label>
                        </Chip>
                    </div>
                )}
            />
            {/* content */}
            <AsyncContent
                isLoading={isLoading}
                skeleton={<PersonalProjectDashboardSkeleton />}
                isEmpty={isEmpty}
                emptyContent={{ title: t("finalProject.dashboard.empty") }}
            >
                <div className="flex flex-col gap-6">
                    {/* next task as ContinueCard hero (chip CTA — not the faint
                        LabeledCard see-more link), then the honest progress meter. */}
                    <div className="flex flex-col gap-3">
                        {currentTask ? (
                            <ContinueCard
                                variant="hero"
                                icon={() => <PlayIcon weight="fill" />}
                                title={`${currentTask.sortIndex}. ${currentTask.title}`}
                                subtitle={t("finalProject.dashboard.nextTask")}
                                ctaLabel={t("finalProject.dashboard.continue")}
                                onPress={onContinue}
                            />
                        ) : (
                            <Typography type="body" weight="semibold">
                                {t("finalProject.dashboard.allDone")}
                            </Typography>
                        )}
                        <ProgressMeter
                            value={stats.done}
                            max={stats.total || 1}
                            label={t("finalProject.dashboard.completion")}
                            showValue
                        />
                        <Typography type="body-xs" color="muted">
                            {t("finalProject.dashboard.statsLine", {
                                done: stats.done,
                                total: stats.total,
                                attempts: stats.attempts,
                                avg: avgLabel,
                            })}
                        </Typography>
                    </div>

                    {/* keep-going: ContinueCard item grid — "Continue >" lives on each
                        card (Storybook Item), not as a soft see-more beside the label. */}
                    {currentMilestone ? (
                        <LabeledCard
                            label={`${t("finalProject.dashboard.keepGoing")} · ${currentMilestone.title}`}
                            frameless
                        >
                            <Grid
                                columns={{ base: 1, sm: 2 }}
                                principle="sibling-stack"
                                explain="Keep-going task tiles share one section grid — not block-boundary, because they stay inside one labeled group."
                                items={(currentMilestone.tasks ?? []).map((task) => {
                                    const isCompleted = progressMap.get(task.id)?.completed ?? false
                                    const isActive = task.id === currentTaskId
                                    const isLocked = !isPersonalProjectTaskActionUnlocked(
                                        task.id,
                                        progressMap,
                                        currentTaskId,
                                    )
                                    const subtitle = isActive
                                        ? t("finalProject.dashboard.nextTask")
                                        : isCompleted
                                            ? t("finalProject.dashboard.taskDone")
                                            : isLocked
                                                ? t("finalProject.dashboard.statLocked")
                                                : t("finalProject.dashboard.taskTodo")
                                    return {
                                        key: task.id,
                                        content: () => (
                                            <ContinueCard
                                                variant="item"
                                                title={`${task.sortIndex}. ${task.title}`}
                                                subtitle={subtitle}
                                                ctaLabel={t("finalProject.dashboard.continue")}
                                                onPress={() => onSelectTask(task.id)}
                                            />
                                        ),
                                    }
                                })}
                            />
                        </LabeledCard>
                    ) : null}
                </div>
            </AsyncContent>
        </div>
    )
}

"use client"

import React from "react"
import { PlayIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { useAppSelector } from "@/redux/hooks"
import { ContinueCard } from "@/components/blocks/cards/ContinueCard"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"
import { Grid } from "@/components/frames/Grid"

/** Course slugs that have a dedicated capstone teaser (`finalProject.gatePreview.<key>`). */
type CourseSlug = "fullstack-mastery" | "system-design-mastery" | "devops-mastery"

const DEFAULT_COURSE: CourseSlug = "fullstack-mastery"

const isCourseSlug = (value: string | undefined): value is CourseSlug =>
    value === "fullstack-mastery" || value === "system-design-mastery" || value === "devops-mastery"

/** `state.course.displayId` slug → i18n key segment under `finalProject.gatePreview`. */
const COURSE_I18N_KEY: Record<CourseSlug, string> = {
    "fullstack-mastery": "fullstackMastery",
    "system-design-mastery": "systemDesignMastery",
    "devops-mastery": "devopsMastery",
}

/**
 * Non-interactive MOCK teaser of the Personal Project (capstone) surface — mirrors
 * {@link import("../PersonalProjectDashboard").PersonalProjectDashboard}'s block
 * layout (hero {@link ContinueCard} + {@link ProgressMeter} + item grid in a
 * {@link LabeledCard}) using the REAL milestone-0 task titles of the active course
 * (`state.course.displayId`, not fabricated copy), fed to
 * {@link import("../../shared/EnrollGate").EnrollGate} as its `preview` so a trial
 * viewer sees the actual hands-on work behind the faded enroll card. Decorative only
 * (`aria-hidden` applied by the gate) — no state, no interactivity.
 */
export const PersonalProjectGatePreview = () => {
    const t = useTranslations()
    const courseSlug = useAppSelector((state) => state.course.displayId)
    const course = isCourseSlug(courseSlug) ? courseSlug : DEFAULT_COURSE
    const key = COURSE_I18N_KEY[course]
    const taskMeta = t("finalProject.gatePreview.taskMeta")

    return (
        <div className="mx-auto flex w-full max-w-3xl flex-col gap-6">
            <div className="flex flex-col gap-3">
                <ContinueCard
                    variant="hero"
                    icon={() => <PlayIcon weight="fill" />}
                    title={t(`finalProject.gatePreview.${key}.heroTitle`)}
                    subtitle={taskMeta}
                    ctaLabel={t("finalProject.dashboard.continue")}
                />
                <ProgressMeter
                    value={0}
                    max={3}
                    label={t("finalProject.dashboard.completion")}
                    showValue
                />
            </div>
            <LabeledCard
                label={t(`finalProject.gatePreview.${key}.milestone`)}
                frameless
            >
                <Grid
                    columns={{ base: 1, sm: 2 }}
                    principle="sibling-stack"
                    explain="Gate-preview task tiles share one section grid — not block-boundary."
                    items={[
                        {
                            key: "item1",
                            content: () => (
                                <ContinueCard
                                    variant="item"
                                    title={t(`finalProject.gatePreview.${key}.item1Title`)}
                                    subtitle={taskMeta}
                                    ctaLabel={t("finalProject.dashboard.continue")}
                                />
                            ),
                        },
                        {
                            key: "item2",
                            content: () => (
                                <ContinueCard
                                    variant="item"
                                    title={t(`finalProject.gatePreview.${key}.item2Title`)}
                                    subtitle={taskMeta}
                                    ctaLabel={t("finalProject.dashboard.continue")}
                                />
                            ),
                        },
                    ]}
                />
            </LabeledCard>
        </div>
    )
}

"use client"

import React from "react"
import { FieldError, Input, Label, Spinner, TextField, Typography } from "@heroui/react"
import { useTranslations } from "next-intl"
import { usePersonalProjectGithubForm } from "@/hooks/zustand/personalProjectGithub/usePersonalProjectGithubForm"
import type { PersonalProjectGithubAutosaveStatus } from "@/hooks/zustand/personalProjectGithub/store"

/** Props for {@link PersonalProjectSubmission}. */
export type PersonalProjectSubmissionProps = Record<string, never>
/**
 * GitHub repo URL field — the panel's PRIMARY input (the thing learners actually change).
 *
 * Also the debounced-sync OWNER (`enableSync: true`): it is always mounted in the panel, so it
 * runs BOTH the url and branch auto-sync even while the grading-settings Drawer (which hosts the
 * branch field) is closed. The set-once config (language / branch / token) now lives in
 * {@link import("../GithubGradingSettings").GithubGradingSettings} inside that Drawer.
 * @param props - {@link PersonalProjectSubmissionProps}
 */
export const PersonalProjectSubmission = () => {
    const t = useTranslations()
    const {
        githubUrl,
        errors,
        touched,
        autosaveStatus,
        setGithubUrl,
        setTouchedGithubUrl,
    } = usePersonalProjectGithubForm({ enableSync: true })
    const urlInvalid = Boolean(touched.githubUrl && errors.githubUrl)

    return (
        <div className={"flex flex-col gap-2"}>
            {/* label + autosave status on ONE row → the section ends at the input, so the gap to
                the next section stays a clean gap-6 (the status no longer adds trailing height). */}
            <div className="flex items-center justify-between gap-2">
                <Label>{t("finalProject.page.submitGithub.repoFieldTitle")}</Label>
                <AutosaveStatus status={autosaveStatus.githubUrl} />
            </div>
            <TextField variant="secondary" isInvalid={urlInvalid} className="w-full">
                <Input
                    className="w-full"
                    placeholder={t("finalProject.page.submitGithub.placeholder")}
                    name="githubUrl"
                    value={githubUrl}
                    onChange={(event) => setGithubUrl(event.target.value)}
                    onBlur={() => setTouchedGithubUrl(true)}
                />
                <FieldError>{errors.githubUrl}</FieldError>
            </TextField>
        </div>
    )
}

/** Props for {@link AutosaveStatus}. */
interface AutosaveStatusProps {
    status: PersonalProjectGithubAutosaveStatus
}

/**
 * Inline autosave feedback at a FIXED height (no layout jump). `saving` = spinner + muted text,
 * `saved` = success-green, `failed` = danger, `idle` = empty. Kept OUTSIDE the `TextField` (a bare
 * Text inside one is treated as a description/errorMessage slot).
 */
export const AutosaveStatus = ({ status }: AutosaveStatusProps) => {
    const t = useTranslations()
    const tAutosave = useTranslations("autosave")
    return (
        <div className="flex h-5 items-center gap-2">
            {status === "saving"
                ? (
                    <>
                        <Spinner size="sm" />
                        <Typography type="body-sm" color="muted">{t("finalProject.page.submitGithub.syncing")}</Typography>
                    </>
                )
                : status === "saved"
                    ? <Typography type="body-sm" className="text-success-soft-foreground">{tAutosave("saved")}</Typography>
                    : status === "failed"
                        ? <Typography type="body-sm" className="text-danger-soft-foreground">{tAutosave("failed")}</Typography>
                        : null}
        </div>
    )
}

"use client"

import { SparkleIcon } from "@phosphor-icons/react"
import React, { useCallback, useMemo } from "react"
import { Button, Spinner } from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    usePathname,
    useRouter,
} from "next/navigation"
import { AIProcessingText } from "@/components/blocks/learn/AIProcessingText"
import { JobCategory } from "@/modules/types/enums/job-category"
import { JobStatus } from "@/modules/types/enums/job-status"
import { usePersonalProjectGithubForm } from "@/hooks/zustand/personalProjectGithub/usePersonalProjectGithubForm"
import { usePersonalProjectTaskAttemptsDrawerOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useQueryMilestoneTaskProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryMilestoneTaskProgressSwr"
import { useQueryUserPersonalTaskAttemptsSwr } from "@/hooks/swr/api/graphql/queries/useQueryUserPersonalTaskAttemptsSwr"
import { useMutateSyncPersonalProjectGithubSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSyncPersonalProjectGithubSwr"
import { useMutateSyncPersonalProjectGithubBranchSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSyncPersonalProjectGithubBranchSwr"
import { useAppSelector } from "@/redux/hooks"
import { buildMilestoneTaskProgressLookup, isPersonalProjectTaskActionUnlocked } from "@/components/utils/task-lookup"

/** Props for {@link TaskActions}. */
export type TaskActionsProps = Record<string, never>
/**
 * Action row for the task panel: evaluate, feedback, attempts, plus AI status.
 *
 * Self-contained: reads all state from redux/SWR/zustand hooks — no callback or
 * flag props needed. Dispatches the submit/open actions directly.
 * @param props - optional className for the root element
 */
export const TaskActions = () => {
    const t = useTranslations()
    const router = useRouter()
    const pathname = usePathname()
    const reviewGithubForm = usePersonalProjectGithubForm()
    const syncGithubSwr = useMutateSyncPersonalProjectGithubSwr()
    const syncBranchSwr = useMutateSyncPersonalProjectGithubBranchSwr()
    const progressSwr = useQueryMilestoneTaskProgressSwr()
    const personalProjectAttemptsDrawer = usePersonalProjectTaskAttemptsDrawerOverlayState()
    const attemptsSwr = useQueryUserPersonalTaskAttemptsSwr()

    const selectedTaskId = useAppSelector((state) => state.milestone.selectedTaskId)
    const milestoneTaskIdToJobId = useAppSelector((state) => state.milestone.milestoneTaskIdToJobId)
    const jobStatusByJobId = useAppSelector((state) => state.socketIo.jobStatusByJobId)

    const attemptRows = useMemo(
        () => attemptsSwr.data?.data ?? [],
        [attemptsSwr.data?.data],
    )
    const hasReviewAttempts = attemptRows.length > 0

    const reviewJobId = selectedTaskId ? milestoneTaskIdToJobId[selectedTaskId] : undefined
    const reviewJobEnvelope = reviewJobId ? jobStatusByJobId[reviewJobId] : undefined
    const reviewJobStatus = reviewJobEnvelope?.data?.status
    const reviewJobError = reviewJobEnvelope?.data?.error

    const progressLookup = useMemo(
        () => buildMilestoneTaskProgressLookup(
            progressSwr.data?.milestoneTaskProgress?.data?.completionTasks,
        ),
        [progressSwr.data],
    )
    const currentTaskId = progressSwr.data?.milestoneTaskProgress?.data?.currentTask?.id

    const isActionUnlocked = useMemo(
        () => {
            if (!selectedTaskId) {
                return true
            }
            if (progressSwr.isLoading) {
                return true
            }
            return isPersonalProjectTaskActionUnlocked(
                selectedTaskId,
                progressLookup,
                currentTaskId,
            )
        },
        [
            selectedTaskId,
            progressLookup,
            currentTaskId,
            progressSwr.isLoading,
        ],
    )

    const isEvaluateDisabled = useMemo(
        () => !isActionUnlocked
            || reviewGithubForm.isSubmitting
            || attemptsSwr.isLoading
            || syncGithubSwr.isMutating
            || syncBranchSwr.isMutating,
        [
            isActionUnlocked,
            reviewGithubForm.isSubmitting,
            attemptsSwr.isLoading,
            syncGithubSwr.isMutating,
            syncBranchSwr.isMutating,
        ],
    )

    const isEvaluatePending = useMemo(
        () => reviewGithubForm.isSubmitting
            || (
                Boolean(reviewJobId)
                && (
                    reviewJobStatus === JobStatus.Processing
                    || reviewJobStatus === JobStatus.Queued
                )
            ),
        [
            reviewGithubForm.isSubmitting,
            reviewJobId,
            reviewJobStatus,
        ],
    )

    const areSecondaryDisabled = !isActionUnlocked || !hasReviewAttempts

    const showAiProcessing =
        reviewGithubForm.isSubmitting
        || Boolean(reviewJobId)

    const aiJobStatus: JobStatus = reviewGithubForm.isSubmitting
        ? JobStatus.Processing
        : (reviewJobStatus ?? JobStatus.Processing)

    /** Submit the GitHub review form (triggers AI evaluation). */
    const onEvaluate = useCallback(
        () => {
            void reviewGithubForm.submit()
        },
        [reviewGithubForm],
    )

    /** Go to the dedicated task result page (replaces the old feedback modal). */
    const onOpenFeedbacks = useCallback(
        () => router.push(`${pathname}/result`),
        [router, pathname],
    )

    /** Open the personal project attempts drawer. */
    const onOpenAttempts = useCallback(
        () => personalProjectAttemptsDrawer.setOpen(true),
        [personalProjectAttemptsDrawer],
    )

    return (
        // button row <-> AI processing status = gap-3 (same block), no manual h-* spacer
        <div className={"flex flex-col gap-3"}>
            <div className="flex flex-wrap items-center gap-2">
                <Button
                    size="lg"
                    isDisabled={isEvaluateDisabled}
                    isPending={isEvaluatePending}
                    onPress={onEvaluate}
                >
                    {({ isPending }) => (
                        <>
                            {isPending ? <Spinner color="current" /> : <SparkleIcon className="size-5" />}
                            {hasReviewAttempts
                                ? t("finalProject.page.submitGithub.ctaReEvaluate")
                                : t("finalProject.page.submitGithub.ctaEvaluate")}
                        </>
                    )}
                </Button>
                <Button
                    size="lg"
                    variant="secondary"
                    isDisabled={areSecondaryDisabled}
                    onPress={onOpenFeedbacks}
                >
                    {t("task.openFeedbackDetailsButton")}
                </Button>
                <Button
                    size="lg"
                    variant="secondary"
                    isDisabled={areSecondaryDisabled}
                    onPress={onOpenAttempts}
                >
                    {t("finalProject.page.attemptsDrawer.openListButton")}
                </Button>
            </div>
            {showAiProcessing && (
                <AIProcessingText
                    jobCategory={JobCategory.ReviewTask}
                    jobStatus={aiJobStatus}
                    error={reviewJobError}
                />
            )}
        </div>
    )
}

"use client"

import React, { useMemo } from "react"
import { useTranslations } from "next-intl"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import type { MilestoneTaskBrief } from "@/modules/types/entities/milestone"
import { usePersonalProjectGithubForm } from "@/hooks/zustand/personalProjectGithub/usePersonalProjectGithubForm"
import { useAppSelector } from "@/redux/hooks"

/** Props for {@link TaskBrief}. */
export type TaskBriefProps = Record<string, never>

/**
 * Pick the brief matching the selected language, falling back to the first brief (handles the
 * single `agnostic` brief used by FE/infra tasks).
 */
const pickBriefByLang = (
    briefs: Array<MilestoneTaskBrief>,
    lang: string,
): MilestoneTaskBrief | undefined =>
    briefs.find((brief) => brief.lang === lang) ?? briefs[0]

/**
 * The brief `body` is already resolved to the active locale by the backend resolver (one localized
 * body per language, no per-locale translation variants), so we read it directly.
 */
const resolveBriefBody = (
    brief: MilestoneTaskBrief | undefined,
): string => brief?.body ?? ""

/**
 * SCHEMA V2 learner-facing task brief. Renders the per-language Markdown instructions (with
 * `:::muted` callouts, fenced code and ```layout``` widgets) for the selected language, resolved to
 * the active locale. Renders nothing when there are no briefs (legacy tasks).
 *
 * Self-contained: reads `briefs` from redux task state and `lang` from the github form store.
 */
export const TaskBrief = () => {
    const t = useTranslations()
    const { lang } = usePersonalProjectGithubForm()

    const selectedTaskDetail = useAppSelector((state) => state.milestone.selectedTaskDetail)
    const selectedTaskId = useAppSelector((state) => state.milestone.selectedTaskId)
    const milestoneEntities = useAppSelector((state) => state.milestone.entities)

    const displayTask = useMemo(() => {
        if (!selectedTaskId) return undefined
        if (selectedTaskDetail?.id === selectedTaskId) {
            return selectedTaskDetail
        }
        for (const milestone of milestoneEntities) {
            const found = milestone.tasks?.find((task) => task.id === selectedTaskId)
            if (found) return found
        }
        return undefined
    }, [selectedTaskId, selectedTaskDetail, milestoneEntities])

    const briefs = displayTask?.briefs ?? []

    const body = useMemo(
        () => resolveBriefBody(pickBriefByLang(briefs, lang)),
        [briefs, lang],
    )

    if (briefs.length === 0) {
        return null
    }

    return (
        // the brief IS a labeled card: "Instructions" is the label OUTSIDE, the markdown body inside.
        <LabeledCard label={t("task.briefTitle")}>
            {/* data-ai-selectable: the task brief is a valid "ask AI about this passage" region */}
            <div data-ai-selectable>
                <MarkdownContent markdown={body} />
            </div>
        </LabeledCard>
    )
}

