/** Props for {@link TaskCodeImplementations}. */
export type TaskCodeImplementationsProps = Record<string, never>
/**
 * Implementation guide for a milestone task, shown for the language picked by the
 * top "grading language" selector in {@link PersonalProjectSubmission} — a single
 * source of truth for the active language, so this section no longer renders its
 * own language tabs. Reuses the lesson implementation card so the look matches.
 *
 * Self-contained: reads `codeImplementations` from redux task state and `lang` from
 * the github form store.
 * @param props - optional className for the root element
 */
export const TaskCodeImplementations = () => {
    // active grading language lives in the shared github-form store (set by the top selector);
    // read-only here, so `enableSync` stays off (default) and no debounced sync runs
    const { lang } = usePersonalProjectGithubForm()

    const selectedTaskId = useAppSelector((state) => state.milestone.selectedTaskId)
    const selectedTaskDetail = useAppSelector((state) => state.milestone.selectedTaskDetail)
    const milestoneEntities = useAppSelector((state) => state.milestone.entities)

    const displayTask = useMemo(() => {
        if (!selectedTaskId) return undefined
        if (selectedTaskDetail?.id === selectedTaskId) {
            return selectedTaskDetail
        }
        for (const milestone of milestoneEntities) {
            const found = milestone.tasks?.find((task) => task.id === selectedTaskId)
            if (found) return found
        }
        return undefined
    }, [selectedTaskId, selectedTaskDetail, milestoneEntities])

    const codeImplementations = displayTask?.codeImplementations ?? []

    // pick the guide for the selected language (lang vocab matches: typescript/java/csharp/go)
    const selected = useMemo(
        () => codeImplementations.find(
            (item) => item.lang?.toLowerCase() === lang?.toLowerCase(),
        ),
        [codeImplementations, lang],
    )

    // no guide authored for the selected language → render nothing for this section
    if (!selected) {
        return null
    }

    // own title dropped — this section now renders under the parent's shared
    // "task.criteriaTitle" LabeledCard (see personal-project/index.tsx) instead of
    // stacking a second hand-rolled header right under the criteria one.
    return (
        <div className={""}>
            <ImplementationCard item={selected} />
        </div>
    )
}

"use client"

import React, { useMemo } from "react"
import {
    Chip,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import _ from "lodash"
import { ListChecksIcon } from "@phosphor-icons/react"
import { LabeledAccordionCard } from "@/components/blocks/cards/LabeledAccordionCard"
import { MarkdownContent } from "@/components/blocks/rendering/MarkdownContent"
import { useAppSelector } from "@/redux/hooks"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { Box } from "@/components/frames/Box"

/** Props for {@link TaskCriteriaList}. */
export type TaskCriteriaListProps = Record<string, never>
/**
 * Accordion list of pass criteria with score chips and markdown hints.
 *
 * Self-contained: reads sorted criteria from the redux task state, no props needed.
 * @param props - optional className for the root element
 */
export const TaskCriteriaList = () => {
    const t = useTranslations()
    const selectedTaskId = useAppSelector((state) => state.milestone.selectedTaskId)
    const selectedTaskDetail = useAppSelector((state) => state.milestone.selectedTaskDetail)
    const milestoneEntities = useAppSelector((state) => state.milestone.entities)

    const displayTask = useMemo(() => {
        if (!selectedTaskId) return undefined
        if (selectedTaskDetail?.id === selectedTaskId) {
            return selectedTaskDetail
        }
        for (const milestone of milestoneEntities) {
            const found = milestone.tasks?.find((task) => task.id === selectedTaskId)
            if (found) return found
        }
        return undefined
    }, [selectedTaskId, selectedTaskDetail, milestoneEntities])

    const sortedCriterias = useMemo(() => {
        if (!displayTask?.criterias) return []
        return _.cloneDeep(displayTask.criterias)
            .sort((prev, next) => prev.sortIndex - next.sortIndex)
    }, [displayTask?.criterias])

    if (sortedCriterias.length === 0) {
        // section sits under the visible "task.criteriaTitle" label, so an empty
        // list needs a proper empty-state instead of a silent null (self-hide is
        // only for un-labeled widgets)
        return (
            <Box>
                <EmptyState
                    icon={ListChecksIcon}
                    title={t("task.criteriaEmpty")}
                />
            </Box>
        )
    }

    return (
        // NO `label`: the parent already renders the "task.criteriaTitle" heading
        // above this list — a label here would be label-on-label (accordion.md §3d).
        // The per-criterion score rides in the header via `titleEnd`.
        <LabeledAccordionCard
            allowsMultipleExpanded
            items={sortedCriterias.map((criteria, index) => ({
                id: criteria.id,
                title: `${index + 1}. ${criteria.text}`,
                titleEnd: () => (
                    <Chip size="sm" variant="secondary" color="accent">
                        {t("task.criteriaScore", { score: criteria.score })}
                    </Chip>
                ),
                body: () => criteria.hint ? (
                    <MarkdownContent markdown={criteria.hint} />
                ) : (
                    <div className="text-sm text-muted italic">
                        {t("task.criteriaNoHint")}
                    </div>
                ),
            }))}
        />
    )
}

"use client"

import React, {
    useCallback,
    useMemo,
} from "react"
import { Alert, Button } from "@heroui/react"
import {
    useTranslations,
    useLocale,
} from "next-intl"
import {
    useRouter,
} from "next/navigation"
import {
    pathConfig,
} from "@/resources/path"
import { useAppDispatch, useAppSelector } from "@/redux/hooks"
import { setSelectedTaskId } from "@/redux/slices/milestone"
import { useQueryMilestoneTaskProgressSwr } from "@/hooks/swr/api/graphql/queries/useQueryMilestoneTaskProgressSwr"
import { buildMilestoneTaskProgressLookup, isPersonalProjectTaskActionUnlocked } from "@/components/utils/task-lookup"

/** Props for {@link TaskLockedAlert}. */
export type TaskLockedAlertProps = Record<string, never>
/**
 * Warning alert shown when previewing a locked (not-yet-unlocked) task.
 *
 * Self-contained section (single-use): reads the selected/current task ids from
 * redux and the milestone task progress from its singleton SWR query, derives
 * whether the previewed task is locked, and owns the "go to current task"
 * navigation handler. Renders nothing when the action is unlocked, so the task
 * container just drops `<TaskLockedAlert />` in place. `"use client"` for redux,
 * routing and i18n.
 * @param props - optional className (unused; alert shape is fixed)
 */
export const TaskLockedAlert = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const dispatch = useAppDispatch()
    const progressSwr = useQueryMilestoneTaskProgressSwr()
    const selectedTaskId = useAppSelector((state) => state.milestone.selectedTaskId)
    const courseDisplayId = useAppSelector((state) => state.course.displayId)

    const progressLookup = useMemo(
        () => buildMilestoneTaskProgressLookup(
            progressSwr.data?.milestoneTaskProgress?.data?.completionTasks,
        ),
        [progressSwr.data],
    )
    const currentTaskId = progressSwr.data?.milestoneTaskProgress?.data?.currentTask?.id

    const isActionUnlocked = useMemo(
        () => {
            if (!selectedTaskId) {
                return true
            }
            if (progressSwr.isLoading) {
                return true
            }
            return isPersonalProjectTaskActionUnlocked(
                selectedTaskId,
                progressLookup,
                currentTaskId,
            )
        },
        [
            selectedTaskId,
            progressLookup,
            currentTaskId,
            progressSwr.isLoading,
        ],
    )

    const isActionLocked = Boolean(selectedTaskId) && !isActionUnlocked
    const canGoToCurrentTask = Boolean(
        currentTaskId
        && selectedTaskId
        && currentTaskId !== selectedTaskId,
    )

    /** Navigate to the current (unlocked) task from the locked-preview alert. */
    const onGoToCurrentTask = useCallback(
        () => {
            if (!currentTaskId || !courseDisplayId) {
                return
            }
            dispatch(setSelectedTaskId(currentTaskId))
            router.push(
                pathConfig().locale(locale).course(courseDisplayId).learn().personalProject(currentTaskId).build(),
            )
        },
        [
            currentTaskId,
            courseDisplayId,
            dispatch,
            router,
            locale,
        ],
    )

    if (!isActionLocked) {
        return null
    }

    return (
        <>
            <Alert status="warning" className={"shadow-none bg-warning-soft"}>
                <Alert.Indicator />
                <Alert.Content className="gap-2">
                    <Alert.Title>{t("task.previewLockedAlertTitle")}</Alert.Title>
                    <Alert.Description>
                        {t("task.previewLockedAlertDescription")}
                    </Alert.Description>
                    {canGoToCurrentTask ? (
                        <Button
                            size="sm"
                            variant="secondary"
                            className="w-fit shrink-0 bg-background text-warning-soft-foreground"
                            onPress={onGoToCurrentTask}
                        >
                            {t("task.previewLockedGoToCurrentTaskButton")}
                        </Button>
                    ) : null}
                </Alert.Content>
            </Alert>
        </>
    )
}

